INSERT INTO NPC (npcID, name, biography, contribution, asset) VALUES
(1, 'Tunku Abdul Rahman Putra Al-Haj', 'Perdana Menteri pertama Persekutuan Tanah Melayu dan Bapa Kemerdekaan.', 'Meyakinkan lima wilayah bersatu tanpa paksaan: mendengar Borneo, menandatangani perjanjian dan mengisytiharkan Malaysia.', 'tunku_abdul_rahman.png'),
(2, 'Tun Temenggong Jugah anak Barieng', 'Pemimpin utama masyarakat Iban dari Sarawak dan pengerusi parti PESAKA.', 'Menegaskan perlindungan hak adat Sarawak dalam rundingan pembentukan Malaysia.', 'tun_temenggung_jugah.png'),
(3, 'Donald Stephens (Tun Fuad Stephens)', 'Tokoh utama Sabah dan Pengerusi Jawatankuasa Setia Kawan Malaysia (JSKM).', 'Membawa suara rakyat Borneo ke meja perundingan supaya hak mereka ditulis dalam Perlembagaan.', 'tun_muhammad_fuad_stephens.png'),
(4, 'Lee Kuan Yew', 'Perdana Menteri Singapura yang menyokong penggabungan dengan Malaysia.', 'Memimpin referendum Singapura dan menangani ancaman pengaruh komunis.', 'lee_kuan_yew.png'),
(5, 'Tun Abdul Razak bin Dato'' Hussein', 'Timbalan Perdana Menteri Persekutuan Tanah Melayu dan Pengerusi JAK.', 'Merangka hak perlembagaan dan perlindungan khas bagi Sabah dan Sarawak.', 'tun_abdul_razak.png'),
(6, 'Tan Sri Stephen Kalong Ningkan', 'Ketua Menteri Sarawak yang pertama dan pengasas Perikatan Sarawak.', 'Memimpin Sarawak menyertai Malaysia dan membaca Pemasyhuran di Kuching.', 'tan_sri_dato_amar_stephen_kalong.png'),
(7, 'Wakil SUPP / Pembangkang', 'Wakil gerakan politik tempatan di Sarawak yang menentang idea gabungan awal.', 'Menuntut kemerdekaan Sarawak secara berasingan sebelum cadangan persekutuan.', 'orang_sarawak.png'),
(8, 'Orang Kampung', 'Penduduk kampung Borneo yang ingin tahu apa untungnya Malaysia.', 'Mewakili suara rakyat biasa yang bertanya dan perlu diyakinkan.', 'orang_bajau.png'),
(9, 'Tun Datu Mustapha bin Datu Harun', 'Pengasas USNO dan Pemimpin Utama Sabah.', 'Memimpin penyatuan rakyat Sabah dan menyokong pembentukan Malaysia.', 'tun_dato_mustapha.png'),
(10, 'Tun Muhammad Ghazali Shafie', 'Diplomat dan perunding keselamatan negara dalam rundingan pembentukan Malaysia.', 'Menjaga keselamatan dan diplomasi di belakang tabir: menghadapi Konfrontasi dan memastikan PBB mengesahkan pilihan rakyat.', 'tun_muhammad_ghazali_shafie.png'),
(11, 'Lord Brassey', 'Pengarah British North Borneo Company (Syarikat Borneo Utara British).', 'Pada 1887 mencadangkan penggabungan Sarawak, Sabah, Negeri-negeri Melayu dan Negeri-negeri Selat.', 'lord_brassey.png'),
(12, 'Malcolm MacDonald', 'Gabenor Jeneral British di Asia Tenggara.', 'Pada 1951 mengadakan perbincangan dengan pemimpin Tanah Melayu, Sarawak, Sabah dan Singapura tentang penggabungan.', 'malcom_macdonald.png'),
(13, 'Ibrahim Haji Yaakob', 'Tokoh tempatan yang memperjuangkan idea penggabungan.', 'Pada 1938 memperjuangkan penggabungan melalui konsep Melayu Raya.', 'ibrahim_yaakob.png'),
(14, 'Harun Aminurrashid', 'Tokoh tempatan yang memperjuangkan idea penggabungan.', 'Pada 1938 bersama Ibrahim Haji Yaakob memperjuangkan konsep Melayu Raya.', 'harun_aminurrashid.png'),
(15, 'Datu Bandar Abang Haji Mustapha', 'Tokoh Sarawak yang terlibat dalam pembentukan Malaysia.', 'Tokoh yang terlibat dalam pembentukan Malaysia dari Sarawak.', 'datu_bandar_abang_haji_mustapha.png'),
(16, 'Tan Sri Wong Pow Nee', 'Ahli Suruhanjaya Cobbold.', 'Turun bersama Suruhanjaya Cobbold mendengar pandangan penduduk Sarawak dan Sabah pada 1962.', 'tan_sri_wong_pow_nee.png'),
(17, 'Wartawan Akhbar', 'Wartawan yang melaporkan setiap peristiwa pembentukan Malaysia.', 'Bertanya soalan yang dijawab pemimpin dalam cerita.', 'jejaka_melayu.png'),
(18, 'Murid Sekolah', 'Murid yang ingin tahu mengapa Hari Malaysia disambut.', 'Bertanya soalan untuk menguji kefahaman pemain.', 'budak_gajet.png'),
(19, 'Ahli UNMM', 'Pegawai misi Pertubuhan Bangsa-Bangsa Bersatu.', 'Mengesahkan persetujuan penduduk Sarawak dan Sabah pada 1963.', 'wakil_pbb(un).png'),
(20, 'Pemudi UNKO', 'Pemudi pertubuhan UNKO di Sabah.', 'Bertanya tentang hubungan dengan negara jiran selepas Pemasyhuran.', 'perempuan_sabah.png'),
(41, 'Tun V.T. Sambanthan', 'Pemimpin MIC dan menteri dalam kerajaan Perikatan yang berjalan dari kampung ke ladang dan bandar untuk mendengar rakyat.', 'Menyokong usaha memupuk perpaduan antara kaum selepas peristiwa 13 Mei 1969.', 'tun_vt_sambanthan.png')
INSERT INTO Narrative (narrativeID, narrativeTitle, eraID, summary) VALUES
(1, 'Perjalanan Sang Arsitek', 1, 'Masuki peranan Tunku Abdul Rahman. Daripada idea lama sejak 1887 hingga Pemasyhuran 16 September 1963, kau menjelaskan sebab, mengatur langkah, mendengar Borneo dan Singapura, lalu menghadapi cabaran dalam dan luar negara.'),
(2, 'Suara dari Borneo', 1, 'Masuki peranan Donald Stephens, pemimpin UNKO di Sabah. Dengar kebimbangan rakyat, bawa suara Borneo ke JSKM, Cobbold, JAK dan UNMM, hingga Pemasyhuran 16 September 1963 dan cabaran selepasnya.'),
(3, 'Pegawai di Sebalik Tabir', 1, 'Masuki peranan Ghazali Shafie, pegawai kanan yang menyusun kerja di sebalik tabir. Susun idea, sebab, jawatankuasa dan perjanjian, hingga Pemasyhuran 16 September 1963 dan cabaran selepasnya.');
INSERT INTO Scene (sceneID, sceneStoryline, sceneOrder, narrativeID, asset) VALUES
('e1_n1_s1', 'Hujan lebat di luar Pejabat Perdana Menteri. Lampu berkelip, dan angin dari tingkap yang tidak tertutup menyapu tiga fail lama ke lantai. Sepucuk surat berlak merah terkoyak separuh, dakwatnya hampir lunyai.', 1, 1, 'perancangan_pembentukan_malaysia.png'),
('e1_n1_s2', 'Razak menghempas empat helai draf di atas meja, semuanya bertarikh berbeza dan bercampur, 1887, 1938, 1951 dan 1955. Pencetak Parlimen sedang menunggu di luar dan pembantu peribadi hampir menangis.', 2, 1, 'bilik_mesyuarat_formal.png'),
('e1_n1_s3', 'Bilik bawah tanah itu gelap dan berbau kertas lembap. Sebuah mentol bergoyang dari siling. Di dinding tergantung dua peta berpin merah, dan di atas meja terdapat timbunan buku laporan hijau.', 3, 1, 'bilik_strategi_keselamatan.png'),
('e1_n1_s4', 'Wong Pow Nee dan Sambanthan sudah duduk apabila Tunku masuk. Di tengah meja ada empat kad kosong bertulis SEBAB, dan tiada siapa mahu bercakap dahulu.', 4, 1, 'bilik_mesyuarat.png'),
('e1_n1_s5', 'Dewan makan Hotel Adelphi, Singapura, penuh sesak dengan wartawan. Tiga puluh kamera menghala ke arah Tunku. Seseorang menjatuhkan pinggan dan semua kepala menoleh.', 5, 1, 'grand_hotel_ballroom.png'),
('e1_n1_s6', 'Julai 1961. Bot berlabuh di tebing berlumpur. Orang ramai menunggu dengan bendera kecil, tetapi tiga lelaki di barisan hadapan tidak tersenyum.', 6, 1, 'lawatan_ke_sarawak.png'),
('e1_n1_s7', 'Tukang masih memaku papan nama di dinding ketika para pemimpin Borneo masuk. Tarikhnya 23 Julai 1961. Tiada siapa tersenyum, dan kerusi di tengah meja dibiarkan kosong.', 7, 1, 'bilik_jskm.png'),
('e1_n1_s8', 'Awal 1962. Fail setinggi lutut diangkut masuk ke bilik suruhanjaya. Ghazali sendiri ahli suruhanjaya ini. Dia memeriksa nama pada setiap sampul sambil menggigit bibir.', 8, 1, 'bilik_suruhanjaya_cobbold.png'),
('e1_n1_s9', 'Wakil SUPP meletakkan halaman laporan yang terkoyak di atas meja lalu menolaknya semula ke arah Tunku. Dewan terdiam.', 9, 1, 'bilik_mesyuarat_formal.png'),
('e1_n1_s10', 'Satu draf perlembagaan diletakkan di tengah meja. Setiap pihak membaca halaman pertama dengan wajah berbeza, dan Abang Haji Mustapha mengetuk meja perlahan.', 10, 1, 'bilik_mesyuarat_formal.png'),
('e1_n1_s11', 'Jalan di Singapura sesak dengan lori pembesar suara. Slip undi dibahagikan kepada orang ramai. Lee mundar-mandir di luar dewan, menunggu keputusan.', 11, 1, 'bandar.png'),
('e1_n1_s12', 'London, hujan renyai. Di bilik besar, dua pen bulu terletak berdakwat basah di atas meja bersalut baldu merah. Seorang pegawai mengetuk jam tangannya, iaitu mereka sudah lewat.', 12, 1, 'marlborough_house.png'),
('e1_n1_s13', 'Perahu menyusur sungai Borneo. Seorang pegawai PBB membawa buku catatan basah, dikelilingi penduduk yang bertanya-tanya siapa dia.', 13, 1, 'bilik_UNMM.png'),
('e1_n1_s14', 'Stadium penuh. Lampu kilat bersilang. Tunku memegang dokumen yang terketar-ketar di tangan, kerana tulisan pada kulit hadapan dipadamkan hujan.', 14, 1, 'laungan_di_stadium_merdeka.png'),
('e1_n1_s15', 'Peta besar tergantung di dewan. Kad negeri berselerak di lantai selepas angin dari pintu terbuka menerbangkannya. Majlis bermula sepuluh minit lagi.', 15, 1, 'peta_negeri.png'),
('e1_n1_s16', 'Empat telegram tiba serentak, setiap satunya berbunyi marah. Razak membacanya satu demi satu dan mengurut pelipisnya.', 16, 1, 'bilik_mesyuarat_dunia.png'),
('e1_n1_s17', 'Arkib negara sunyi pada waktu subuh. Hanya ada lapan kad bertarikh di atas meja kaca. Tiga lampu pendarfluor berkelip.', 17, 1, 'bangunan_perlembagaan.png'),
('e1_n2_s1', 'Malam di pejabat UNKO, Sabah. Kipas siling berderit. Di luar, orang kampung bertengkar tentang khabar angin bahawa Tanah Melayu mahu mengambil Borneo. Di atas meja ada sebuah fail berhabuk bercop British North Borneo Company.', 1, 2, 'bilik_mesyuarat.png'),
('e1_n2_s2', 'Meja panjang pejabat UNKO. Tiga fail terbuka di atas peta, bersama keratan akhbar 1955. Datu Mustapha mundar-mandir sambil memegang secawan kopi sejuk.', 2, 2, 'perancangan_pembentukan_malaysia.png'),
('e1_n2_s3', 'Bilik mesyuarat kecil. Peta Asia Tenggara di dinding, dokumen bertimbun di atas meja. Tun Razak membuka begnya dan mengeluarkan beberapa laporan bertanda merah.', 3, 2, 'bilik_strategi_keselamatan.png'),
('e1_n2_s4', 'Dewan kampung penuh sesak. Kipas kayu berpusing perlahan. Orang kampung duduk bersila, dan Datu Mustapha berdiri dengan timbunan risalah di tangan.', 4, 2, 'kampung_dan_pedalaman.png'),
('e1_n2_s5', 'Pagi di pejabat UNKO. Akhbar terbentang di atas meja dan tajuk besarnya menarik perhatian semua orang. Datu Mustapha masuk dengan wajah cemas.', 5, 2, 'bilik_mesyuarat.png'),
('e1_n2_s6', 'Julai 1961, tebing sungai Kuching. Tunku berdiri di hadapan pemimpin Sarawak. Penduduk berkumpul di belakang mereka, dan rumah panjang berdiri di seberang sungai.', 6, 2, 'lawatan_ke_sarawak.png'),
('e1_n2_s7', '23 Julai 1961, bilik mesyuarat JSKM. Delegasi Sabah dan Sarawak duduk bersebelahan. Peta dan dokumen bertimbun di atas meja. Tunku memandang Donald.', 7, 2, 'bilik_jskm.png'),
('e1_n2_s8', 'Dewan awam Sabah, 17 Januari 1962. Fail dan memorandum bertimbun di atas meja. Wong Pow Nee dan Ghazali Shafie duduk di meja suruhanjaya.', 8, 2, 'bilik_suruhanjaya_cobbold.png'),
('e1_n2_s9', 'Pejabat UNKO, 21 Jun 1962. Laporan Suruhanjaya Cobbold terbuka di atas meja. Seorang wakil SUPP menunggu di luar dengan wajah tegang.', 9, 2, 'bilik_mesyuarat_formal.png'),
('e1_n2_s10', '30 Ogos 1962, bilik rundingan. Wakil British, Persekutuan Tanah Melayu, Sarawak dan Sabah duduk di sisi meja. Dokumen mesyuarat terletak di hadapan setiap pihak.', 10, 2, 'bilik_mesyuarat_modern.png'),
('e1_n2_s11', 'Bilik tetamu, 1 September 1962. Radio bersiaran perlahan. Lee Kuan Yew mencari dokumen yang betul di tengah timbunan kertas, wajahnya letih.', 11, 2, 'bilik_mesyuarat_dunia.png'),
('e1_n2_s12', 'Balai penerangan Sabah, 9 Julai 1963. Orang ramai menunggu berita. Datu Mustapha memegang tiga telegram yang tiba serentak, masing-masing menyebut perkara berbeza.', 12, 2, 'petempatan_pedalaman_sabah.png'),
('e1_n2_s13', '12 Ogos 1963, bilik UNMM. Peti undi dan mesin telex memenuhi ruang. Pegawai PBB berkot biru menghitung kertas dan menaip laporan.', 13, 2, 'bilik_UNMM.png'),
('e1_n2_s14', '16 September 1963, padang di tepi Kota Kinabalu. Bendera dinaikkan dan orang ramai berkumpul. Jugah dan Datu Mustapha hadir. Seorang murid sekolah memegang peta kecil.', 14, 2, 'negeri_sabah.png'),
('e1_n2_s15', 'Pejabat UNKO selepas Pemasyhuran. Sebuah peta Asia Tenggara tergantung di dinding. Datu Mustapha menghulurkan sepucuk surat dari seberang laut.', 15, 2, 'bilik_mesyuarat_dunia.png'),
('e1_n2_s16', 'Pejabat UNKO, kini lengang. Fail Brassey masih di atas meja. Datu Mustapha menghulurkan kertas kosong untuk ucapan Donald.', 16, 2, 'bilik_mesyuarat.png'),
('e1_n3_s1', 'Pejabat Ghazali di Kuala Lumpur lewat malam. Rak fail penuh hingga ke siling dan satu mentol sahaja yang menyala. Tun Razak meletakkan sebuah fail lama berlabel 1938 di atas meja tanpa berkata apa-apa.', 1, 3, 'bilik_mesyuarat.png'),
('e1_n3_s2', 'Meja panjang dengan empat fail terbuka. Razak berdiri di hujung meja dengan jam tangan di tangan, menunggu Ghazali menyusun semula idea gabungan supaya kisahnya jelas.', 2, 3, 'perancangan_pembentukan_malaysia.png'),
('e1_n3_s3', 'Bilik strategi keselamatan di bawah tanah. Peta Asia Tenggara di dinding, kertas laporan bertaburan di atas meja. Lampu suluh Razak menyuluh peta yang bertanda merah.', 3, 3, 'bilik_strategi_keselamatan.png'),
('e1_n3_s4', 'Bilik mesyuarat formal. Di papan hitam, Razak sudah menulis empat perkataan, Keselamatan, Keseimbangan kaum, Kemerdekaan, Sosioekonomi. Wong Pow Nee dan Sambanthan duduk menunggu penjelasan.', 4, 3, 'bilik_mesyuarat_formal.png'),
('e1_n3_s5', 'Sehari sebelum pengumuman. Pembantu Tunku memanggil Ghazali dengan cemas, iaitu teks ucapan hilang di antara timbunan kertas di atas meja. Tunku sendiri berdiri di tepi tingkap, tenang tetapi tegang.', 5, 3, 'bilik_mesyuarat.png'),
('e1_n3_s6', 'Julai 1961. Ghazali menerima nota ringkas dari Kuching dengan tulisan tergesa-gesa. Di atas mejanya hanya ada secawan teh yang sudah sejuk.', 6, 3, 'lawatan_ke_sarawak.png'),
('e1_n3_s7', '23 Julai 1961, bilik JSKM. Delegasi Sabah dan Sarawak duduk bersama pegawai Persekutuan. Peta wilayah tergantung di dinding dan dokumen mesyuarat belum dibuka.', 7, 3, 'bilik_jskm.png'),
('e1_n3_s8', '17 Januari 1962. Suruhanjaya Cobbold bersidang. Ghazali menerima kertas arahan yang masih berbau dakwat segar, dan Wong Pow Nee menunggu di sebelahnya.', 8, 3, 'bilik_suruhanjaya_cobbold.png'),
('e1_n3_s9', '21 Jun 1962. T. Sambanthan berdiri di meja yang penuh dokumen, mencari laporan yang betul. Wakil SUPP menunggu di luar bilik dengan wajah tidak puas hati.', 9, 3, 'bilik_mesyuarat_formal.png'),
('e1_n3_s10', '30 Ogos 1962. JAK bersidang. Wakil British, Persekutuan, Sarawak dan Sabah duduk di sisi meja. Rangka perlembagaan terletak di tengah, kertasnya masih bersih.', 10, 3, 'bilik_mesyuarat_formal.png'),
('e1_n3_s11', '1 September 1962. Radio melaporkan keputusan. Ghazali menerima nota ringkas dengan tangan yang hampir terketar. Di luar, orang ramai bersorak.', 11, 3, 'bilik_mesyuarat_dunia.png'),
('e1_n3_s12', '9 Julai 1963. Di Kuala Lumpur, Ghazali menyemak fail perjanjian yang dihantar ke London. Tiga fail serupa terletak di atas meja, dan Razak berdiri di belakangnya menunggu keputusan.', 12, 3, 'marlborough_house.png'),
('e1_n3_s13', 'Fail empat badan terbuka di atas meja Ghazali. Razak menyuruhnya memadankan tugas setiap badan sebelum pegawai PBB tiba, dan kertas-kertas bertaburan seperti kad yang belum dimain.', 13, 3, 'bilik_mesyuarat.png'),
('e1_n3_s14', '16 September 1963. Dokumen Pemasyhuran terbentang di atas meja perancangan. Peta besar tergantung di belakang, dengan empat pin kosong menunggu untuk diletakkan.', 14, 3, 'perancangan_pembentukan_malaysia.png'),
('e1_n3_s15', 'Selepas Pemasyhuran. Di pejabat Ghazali, laporan cabaran bertimbun di atas meja. Telegram-telegram marah tiba satu demi satu, dan Razak mengurut pelipisnya.', 15, 3, 'bilik_mesyuarat_dunia.png'),
('e1_n3_s16', 'Pejabat Ghazali sunyi. Fail-fail dikemas satu demi satu ke dalam kotak. Razak berdiri di tepi tingkap dan meminta rumusan terakhir sebelum semua fail ditutup.', 16, 3, 'bilik_mesyuarat.png');
INSERT INTO Quest (questID, sceneID, questName, instruction, questType, description, questContent) VALUES
(1, 'e1_n1_s1', 'Tiga Fail Lama', 'Padankan setiap tokoh atau cadangan dalam fail lama dengan pasangannya.', '4', 'Memadankan Lord Brassey (1887) dan Melayu Raya (1938) dengan tokoh dan kawasan yang dicadangkan.', '{"pairs": [{"text": "Lord Brassey", "pair": 1}, {"text": "Mencadangkan penggabungan pada 1887", "pair": 1}, {"text": "Ibrahim Yaakob dan Harun Aminurrashid", "pair": 2}, {"text": "Memperjuangkan Melayu Raya pada 1938", "pair": 2}, {"text": "Cadangan Brassey, 1887", "pair": 3}, {"text": "Sarawak, Sabah, Negeri-negeri Melayu, Negeri-negeri Selat", "pair": 3}, {"text": "Melayu Raya, 1938", "pair": 4}, {"text": "Tanah Melayu, Singapura, Kalimantan, Filipina, Indonesia", "pair": 4}], "aftermath": "Fail tersilap padan, dan Ghazali mengingatkan bahawa wartawan boleh menuduh Tunku mereka-reka sejarah.", "turns": [{"after": 8, "options": [{"text": "Bukan. Idea ini sudah lama dibincangkan oleh pihak British dan pemimpin tempatan.", "isCorrect": true, "reaction": "Wartawan menurunkan pen dan mengangguk. Ghazali menarik nafas lega: Tunku jujur tentang asal-usul idea itu."}, {"text": "Ya, akulah yang merancang semuanya dari awal dan tiada orang lain terlibat langsung dalam hal ini.", "isCorrect": false, "reaction": "Wartawan tersenyum sinis dan menulis laju. Ghazali berbisik bahawa fail di lantai itu akan membuktikan Tunku silap."}, {"text": "Aku belum boleh berkata apa-apa kerana perkara ini masih dalam kajian.", "isCorrect": false, "reaction": "Wartawan mengerutkan dahi dan mengesyaki ada sesuatu yang disembunyikan."}], "clue": "Fail di lantai membuktikan idea ini sudah lama wujud sebelum Tunku."}]}'),
(2, 'e1_n1_s2', 'Susun Empat Idea', 'Susun empat idea penggabungan mengikut tahun, dari yang paling awal.', '1', 'Menyusun kronologi idea penggabungan: Brassey 1887, Melayu Raya 1938, MacDonald 1951, Tunku 1955.', '{"timelineItems": [{"id": 1, "year": "1887", "text": "Lord Brassey mencadangkan penggabungan Sarawak, Sabah, Negeri-negeri Melayu dan Negeri-negeri Selat", "why": "Cadangan paling tua dalam fail. Pengarah syarikat British itu sudah membayangkan wilayah ini bersatu."}, {"id": 2, "year": "1938", "text": "Ibrahim Haji Yaakob dan Harun Aminurrashid memperjuangkan Melayu Raya", "why": "Selepas cadangan British, tokoh tempatan pula memperjuangkan penggabungan."}, {"id": 3, "year": "1951", "text": "Malcolm MacDonald berbincang penggabungan dengan pemimpin Tanah Melayu, Sarawak, Sabah dan Singapura", "why": "Pegawai British menghidupkan semula idea lama dengan berunding secara langsung."}, {"id": 4, "year": "1955", "text": "Tunku mencadangkan Sarawak, Sabah, Singapura dan Brunei menyertai Persekutuan Tanah Melayu", "why": "Idea itu akhirnya disebut oleh seorang pemimpin Persekutuan sendiri, ketika beliau Ketua Menteri."}], "aftermath": "Ucapan Parlimen mencampuradukkan tahun, dan Razak hampir menyebut Tunku sebagai pencadang 1951.", "turns": [{"after": 6, "options": [{"text": "Sebut, supaya Parlimen tahu idea ini datang daripada banyak pihak.", "isCorrect": true, "reaction": "Razak mengangguk dan menulis nama Brassey di margin. Ucapan itu akan kelihatan lebih jujur dan kukuh."}, {"text": "Tidak perlu, orang British tidak penting dalam sejarah kita dan tak patut disebut langsung.", "isCorrect": false, "reaction": "Razak menggeleng. Sejarah tidak boleh dipilih-pilih, dan wakil pembangkang pasti membangkitkannya nanti."}, {"text": "Biar Ghazali yang tentukan, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Ghazali tersentak dan Razak mengeluh perlahan: pemimpin mesti memutuskan sendiri apa yang dibawa ke Parlimen."}], "clue": "Idea ini datang daripada British, tokoh tempatan dan pemimpin Persekutuan."}]}'),
(3, 'e1_n1_s3', 'Bukti di Bilik Strategi', 'Cari empat bukti yang menunjukkan ancaman komunis dan pengalaman Persekutuan menghadapinya.', '2', 'Mencari bukti sebab keselamatan: ancaman komunis di Singapura dan Sarawak, pengalaman Persekutuan dan keputusan gabungan.', '{"bgImage": "../assets/gameAsset/background/bilik_strategi_keselamatan.png", "hotspots": [{"name": "Peta ancaman komunis di Singapura", "top": "30%", "left": "38%"}, {"name": "Peta ancaman komunis di Sarawak", "top": "30%", "left": "62%"}, {"name": "Laporan pengalaman Persekutuan menghadapi komunis", "top": "68.9%", "left": "31.3%"}, {"name": "Papan keputusan: gabungan membendung ancaman", "top": "13%", "left": "52%"}], "aftermath": "Tanpa bukti yang jelas, Lee menganggap Persekutuan tidak bersungguh-sungguh dan mesyuarat berjalan dingin.", "turns": [{"after": 6, "options": [{"text": "Rasanya, hanya ringkasan, tanpa peta pergerakan.", "isCorrect": true, "reaction": "Razak mengangguk: rakyat tahu, musuh tidak. Lee juga bersetuju."}, {"text": "Sebenarnya, buka semuanya, rakyat berhak tahu setiap perkara tanpa kecuali.", "isCorrect": false, "reaction": "Razak risau. Peta itu boleh menimbulkan panik dan menunjukkan kelemahan kita kepada musuh."}, {"text": "Bagi aku, tutup semuanya sampai selepas pilihan raya, walaupun rakyat sudah bertanya.", "isCorrect": false, "reaction": "Razak menggeleng. Rahsia yang terlalu lama akan retak dan akhbar akan mencarinya sendiri."}], "clue": "Rakyat perlu tahu, tetapi musuh tidak boleh melihat peta pergerakan."}]}'),
(4, 'e1_n1_s4', 'Empat Sebab, Empat Penjelasan', 'Padankan setiap sebab pembentukan Malaysia dengan penjelasannya.', '4', 'Memadankan empat sebab: keselamatan, keseimbangan kaum, kemerdekaan dipercepat dan sosioekonomi.', '{"pairs": [{"text": "Menjamin keselamatan negara", "pair": 1}, {"text": "Ancaman komunis di Singapura dan Sarawak dapat dibendung", "pair": 1}, {"text": "Mencapai keseimbangan kaum", "pair": 2}, {"text": "Bilangan penduduk antara kaum menjadi seimbang", "pair": 2}, {"text": "Mempercepat kemerdekaan", "pair": 3}, {"text": "Sarawak, Sabah, Singapura dan Brunei merdeka lebih cepat", "pair": 3}, {"text": "Membangunkan sosioekonomi", "pair": 4}, {"text": "Infrastruktur dan taraf hidup rakyat dipertingkatkan", "pair": 4}], "aftermath": "Padanan tersilap, dan Wong serta Sambanthan pulang tanpa bersetuju kerana hujah Tunku bercelaru.", "turns": [{"after": 6, "options": [{"text": "Rasanya, aku berjanji mendengar, dan perlembagaan melindungi semua kaum.", "isCorrect": true, "reaction": "Sambanthan mengangguk perlahan. Wong menyandar, kurang bimbang: janji itu bersandar pada undang-undang, bukan sekadar kata-kata."}, {"text": "Aku berjanji sepenuhnya, tiada seorang pun akan dipinggirkan walau sedikit.", "isCorrect": false, "reaction": "Sambanthan ragu. Janji yang terlalu mudah selalunya sukar ditepati."}, {"text": "Itu urusan Parlimen sepenuhnya, bukan urusan aku malam ini, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Wong mengerutkan dahi. Tunku seolah-olah mengelak daripada menjawab."}], "clue": "Janji mesti disandarkan pada perlembagaan dan kesediaan mendengar."}]}'),
(5, 'e1_n1_s5', 'Keratan Akhbar Adelphi', 'Nyahkod keratan akhbar itu dan tentukan tarikh pengumuman Tunku.', '5', 'Mengenal pasti tarikh pengumuman cadangan pembentukan Malaysia: 27 Mei 1961, Hotel Adelphi, Singapura.', '{"clueText": "Keratan akhbar: Tunku Abdul Rahman mengumumkan cadangan pembentukan Malaysia di Hotel Adelphi, Singapura. Ini langkah pertama ke arah pembentukan Malaysia, sebelum lawatan ke Sarawak dan penubuhan JSKM.", "options": [{"text": "27 Mei 1961", "isCorrect": true}, {"text": "23 Julai 1961", "isCorrect": false, "consequence": "Itu tarikh JSKM ditubuhkan, selepas pengumuman. Keratan ini ialah langkah yang pertama."}, {"text": "17 Januari 1962", "isCorrect": false, "consequence": "Itu tarikh Suruhanjaya Cobbold dibentuk, jauh selepas pengumuman Adelphi."}, {"text": "16 September 1963", "isCorrect": false, "consequence": "Itu tarikh Pemasyhuran Malaysia, kemuncak cerita ini dan bukan permulaannya."}], "aftermath": "Tarikh tersalah, dan akhbar esok menulis Tunku keliru tentang kisahnya sendiri.", "turns": [{"after": 6, "options": [{"text": "Ini cadangan. Rakyat Sarawak dan Sabah masih perlu didengar.", "isCorrect": true, "reaction": "Wartawan menulis laju dan dewan menjadi lega. Lee mengangguk, jawapan itu jujur dan berhemah."}, {"text": "Bagi aku, ya, semuanya sudah muktamad dan tiada siapa boleh mengubahnya lagi.", "isCorrect": false, "reaction": "Wartawan mengangkat kening. Ghazali menepuk dahinya, pemimpin Borneo belum ditemui lagi."}, {"text": "Soalan itu tidak berkaitan, kerana itu lebih mudah dan cepat.", "isCorrect": false, "reaction": "Wartawan merengus dan mula mengejek. Dewan menjadi riuh."}], "clue": "Ini baru cadangan; suara Sarawak dan Sabah belum didengar."}]}'),
(6, 'e1_n1_s6', 'Pemimpin Sarawak dan Parti Mereka', 'Padankan setiap pemimpin Sarawak dengan partinya.', '4', 'Memadankan Jugah (PESAKA), Ningkan (SNAP) dan Abang Haji Mustapha (PANAS).', '{"pairs": [{"text": "Tun Temenggung Jugah", "pair": 1}, {"text": "PESAKA (Parti Pesaka Anak Sarawak)", "pair": 1}, {"text": "Stephen Kalong Ningkan", "pair": 2}, {"text": "SNAP (Sarawak National Party)", "pair": 2}, {"text": "Datu Bandar Abang Haji Mustapha", "pair": 3}, {"text": "PANAS (Parti Negara Sarawak)", "pair": 3}], "aftermath": "Pemimpin tersalah dipadankan dengan parti, dan Jugah menganggap Tunku tidak mengenali mereka.", "turns": [{"after": 6, "options": [{"text": "Tidak. Hak Sarawak dilindungi dan kamu ada kata putus.", "isCorrect": true, "reaction": "Jugah mengangguk. Dia mula memberi ruang kepada Tunku."}, {"text": "Sarawak akan menjadi sebahagian daripada Malaysia, sama seperti negeri lain.", "isCorrect": false, "reaction": "Jugah tidak puas hati. Tiada jaminan khas untuk Sarawak dalam jawapan itu."}, {"text": "Kamu terlalu banyak bertanya dan tidak cukup mempercayai.", "isCorrect": false, "reaction": "Ningkan menyilang tangan dan keluar dari tebing."}], "clue": "Sarawak mahu dilayan sebagai rakan yang ada kata putus."}]}'),
(7, 'e1_n1_s7', 'Bukti di Bilik JSKM', 'Cari empat bukti yang menunjukkan JSKM ditubuhkan dan siapa yang terlibat.', '2', 'Mencari bukti penubuhan JSKM pada 23 Julai 1961: papan nama, pemimpin Sarawak, pemimpin Sabah dan cadangan Donald Stephens.', '{"bgImage": "../assets/gameAsset/background/bilik_jskm.png", "hotspots": [{"name": "Papan nama Jawatankuasa Setia Kawan Malaysia", "top": "39%", "left": "72%"}, {"name": "Pemimpin Sarawak (Jugah) sebagai ahli JSKM", "top": "66%", "left": "24%"}, {"name": "Pemimpin Sabah di meja jawatankuasa", "top": "60%", "left": "64%"}, {"name": "Dokumen cadangan Donald Stephens di atas meja", "top": "58%", "left": "45%"}], "aftermath": "Tanpa bukti penubuhan, Mustapha Harun mengembalikan fail dan JSKM tidak dipercayai.", "turns": [{"after": 6, "options": [{"text": "Ya. Tulis sendiri syarat kamu, kita bincang bersama di meja ini.", "isCorrect": true, "reaction": "Donald tersenyum, Jugah kembali duduk. Kerusi kosong di tengah meja akhirnya diisi."}, {"text": "Bagi aku, syarat boleh dibincang, tetapi keputusan akhir ada pada Kuala Lumpur sahaja.", "isCorrect": false, "reaction": "Jugah bangun separuh dan merenung tajam. Mereka datang untuk berbincang, bukan menerima arahan."}, {"text": "Syarat apa pula? Kamu belum berhak menyebutnya, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Dewan menjadi sunyi. Mustapha Harun mengemas kertasnya."}], "clue": "Pemimpin Borneo mahu syarat mereka didengar sebagai rakan."}]}'),
(8, 'e1_n1_s8', 'Siapa dan Apa dalam Suruhanjaya', 'Padankan setiap tokoh atau peristiwa dengan peranannya dalam Suruhanjaya Cobbold.', '4', 'Memadankan Wong Pow Nee, Ghazali, Suruhanjaya Cobbold dan ahli lain suruhanjaya dengan peranan masing-masing.', '{"pairs": [{"text": "Tan Sri Wong Pow Nee", "pair": 1}, {"text": "Wakil Persekutuan dalam Suruhanjaya Cobbold", "pair": 1}, {"text": "Ghazali Shafie", "pair": 2}, {"text": "Ahli suruhanjaya yang menemu ramah penduduk", "pair": 2}, {"text": "Suruhanjaya Cobbold, 17 Januari 1962", "pair": 3}, {"text": "Mendapatkan reaksi penduduk Sarawak dan Sabah", "pair": 3}, {"text": "Sir David Watherston dan Sir Anthony Abell", "pair": 4}, {"text": "Ahli lain Suruhanjaya Cobbold", "pair": 4}], "aftermath": "Padanan tersilap, dan penduduk enggan menghadap suruhanjaya yang tujuannya tidak jelas.", "turns": [{"after": 6, "options": [{"text": "Aku baca selepas diserahkan.", "isCorrect": true, "reaction": "Wong dan Ghazali bertukar pandangan lega: suruhanjaya kekal bebas."}, {"text": "Tidak, suruhanjaya mesti bebas, jadi aku tidak mahu campur tangan langsung dalam apa jua keadaan.", "isCorrect": false, "reaction": "Wong mengangguk menghormati, tetapi Ghazali risau Tunku tidak bersedia menghadapi dapatannya."}, {"text": "Ya, aku mahu ubah mana-mana bahagian yang tidak menyenangkan.", "isCorrect": false, "reaction": "Wong membantah. Suruhanjaya yang diubah tidak lagi dipercayai."}], "clue": "Suruhanjaya mesti bebas daripada campur tangan pemimpin."}]}'),
(9, 'e1_n1_s9', 'Petikan Laporan Cobbold', 'Nyahkod petikan laporan itu dan tentukan siapa yang menolak.', '5', 'Memahami dapatan laporan 21 Jun 1962: dua pertiga menyokong dan SUPP menolak kerana mahu persekutuan sendiri.', '{"clueText": "Petikan laporan, 21 Jun 1962: dua pertiga penduduk Sarawak dan Sabah menyokong pembentukan Malaysia. Satu parti menolak kerana mahu membentuk persekutuan sendiri bersama Brunei dan Borneo Utara.", "options": [{"text": "SUPP (Sarawak United People''s Party)", "isCorrect": true}, {"text": "PESAKA, pimpinan Tun Temenggung Jugah", "isCorrect": false, "consequence": "Jugah menjadi ahli JSKM, jadi parti beliau tidak menolak. Cari parti yang mahu persekutuan sendiri."}, {"text": "SNAP, pimpinan Stephen Kalong Ningkan", "isCorrect": false, "consequence": "Ningkan menyokong dan membentuk Perikatan Sarawak. Bukan parti ini yang menolak."}, {"text": "PANAS, pimpinan Abang Haji Mustapha", "isCorrect": false, "consequence": "Abang Haji Mustapha menyokong pembentukan Malaysia, jadi bukan beliau yang menolak."}], "aftermath": "Penolak tersalah dikenal pasti, dan laporan tidak dapat dijawab dengan betul.", "turns": [{"after": 6, "options": [{"text": "Menurut aku, suara kamu dicatat dengan teliti. Kami akan terus mendengar bantahan.", "isCorrect": true, "reaction": "Wakil SUPP menarik nafas. Setidak-tidaknya suaranya didengar."}, {"text": "Dua pertiga sudah menyokong, jadi suara kamu tidak akan mengubah apa-apa.", "isCorrect": false, "reaction": "Wakil SUPP berpaling tanpa berkata apa-apa."}, {"text": "Kamu patut menyertai demi kebaikan Sarawak, tanpa banyak soal, kerana itu lebih senang.", "isCorrect": false, "reaction": "Wakil SUPP mengerutkan dahi. Tiada penghormatan pada pendiriannya."}], "clue": "Suara yang menolak mesti dicatat dan didengar, bukan diperkecilkan."}]}'),
(10, 'e1_n1_s10', 'Siapa dalam JAK, Apa Tugasnya', 'Padankan JAK dengan ahli, tujuan dan tarikhnya.', '4', 'Memadankan JAK dengan ahlinya (British, Persekutuan, Sarawak, Sabah), tujuan (rangka perlembagaan) dan tarikh 30 Ogos 1962.', '{"pairs": [{"text": "Ahli JAK", "pair": 1}, {"text": "Wakil British, Persekutuan Tanah Melayu, Sarawak dan Sabah", "pair": 1}, {"text": "Tujuan JAK", "pair": 2}, {"text": "Menyediakan rangka perlembagaan yang melindungi kepentingan Sarawak dan Sabah", "pair": 2}, {"text": "Tarikh mesyuarat JAK", "pair": 3}, {"text": "30 Ogos 1962", "pair": 3}], "aftermath": "Padanan tersilap, dan wakil Sabah serta Sarawak bimbang kepentingan mereka diabaikan.", "turns": [{"after": 6, "options": [{"text": "Boleh. Semak dahulu.", "isCorrect": true, "reaction": "Abang Haji Mustapha mengangguk. Wakil Sarawak turut menandatangani."}, {"text": "Boleh, tetapi selepas Kuala Lumpur meluluskannya terlebih dahulu.", "isCorrect": false, "reaction": "Abang Haji Mustapha mengerutkan dahi. Semakan selepas kelulusan bukan semakan."}, {"text": "Tidak perlu, kami sudah menimbangkan segalanya dengan teliti.", "isCorrect": false, "reaction": "Donald menarik nafas panjang. Mereka pernah dijanjikan didengar."}], "clue": "Pihak Borneo mahu menyemak draf sebelum ia muktamad."}]}'),
(11, 'e1_n1_s11', 'Dari Cobbold ke Referendum', 'Susun empat langkah ini mengikut tarikh, dari yang paling awal.', '1', 'Menyusun kronologi: Cobbold dibentuk, laporan Cobbold, JAK dan referendum Singapura.', '{"timelineItems": [{"id": 1, "year": "17 Januari 1962", "text": "Suruhanjaya Cobbold dibentuk untuk mendapatkan reaksi penduduk Sarawak dan Sabah", "why": "Mulakan dengan langkah yang bertanya kepada rakyat Sarawak dan Sabah."}, {"id": 2, "year": "21 Jun 1962", "text": "Cobbold menyerahkan laporan: dua pertiga penduduk menyokong", "why": "Selepas bertanya, suruhanjaya menyerahkan dapatan kepada British dan Persekutuan."}, {"id": 3, "year": "30 Ogos 1962", "text": "JAK bermesyuarat untuk menyediakan rangka perlembagaan", "why": "Dapatan laporan memerlukan perlindungan bertulis, maka JAK bersidang."}, {"id": 4, "year": "1 September 1962", "text": "Referendum di Singapura: rakyat bersetuju dengan pembentukan Malaysia", "why": "Dua hari selepas JAK, rakyat Singapura pula memberi jawapan melalui undi."}], "aftermath": "Susunan tersilap, dan Lee tidak dapat membuktikan Singapura memberi persetujuan selepas langkah yang betul.", "turns": [{"after": 5, "options": [{"text": "Kita tunggu bersama di sini sehingga keputusan diumumkan, Lee.", "isCorrect": true, "reaction": "Lee mengangguk. Rakyat Singapura merasa dihormati."}, {"text": "Sebenarnya, ya, aku sendiri akan menunggu di sini sehingga setiap undi dikira dengan pasti.", "isCorrect": false, "reaction": "Lee tersenyum, tetapi wartawan mula bosan dan beredar."}, {"text": "Aku penat, beritahu keputusannya kemudian sahaja, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Lee menggeleng kecewa. Hari penting itu dilayan sambil lewa."}], "clue": "Menunggu bersama menunjukkan penghormatan kepada rakyat Singapura."}]}'),
(12, 'e1_n1_s12', 'Bukti di Marlborough House', 'Cari empat bukti yang menunjukkan Perjanjian Malaysia ditandatangani di sini.', '2', 'Mencari bukti penandatanganan Perjanjian Malaysia: meja perjanjian, dua pen bulu penandatangan Sarawak dan dokumen perjanjian.', '{"bgImage": "../assets/gameAsset/background/marlborough_house.png", "hotspots": [{"name": "Meja perjanjian beralas baldu merah", "top": "63%", "left": "45%"}, {"name": "Pen bulu Tun Temenggung Jugah", "top": "38%", "left": "22%"}, {"name": "Pen bulu Datu Bandar Abang Haji Mustapha", "top": "40%", "left": "38%"}, {"name": "Dokumen Perjanjian Malaysia, 9 Julai 1963", "top": "53%", "left": "31%"}], "aftermath": "Tanpa bukti penandatanganan, Indonesia dan Filipina mendakwa perjanjian itu tidak sah.", "turns": [{"after": 6, "options": [{"text": "Pada pendapat aku, ia memulakan tanggungjawab baharu.", "isCorrect": true, "reaction": "Jugah dan Abang Haji Mustapha menandatangani serentak. Mereka faham maknanya."}, {"text": "Tidak, tandatangan ini mengikat kita semua dan menjaga hak yang dijanjikan.", "isCorrect": false, "reaction": "Jugah mengangguk perlahan, tetapi dia masih berasa jawapan itu tidak menjawab soalannya."}, {"text": "Aku fikir ya, semua tanggungjawab lama dihapuskan serta-merta.", "isCorrect": false, "reaction": "Jugah mengerutkan dahi. Itu janji kosong."}], "clue": "Tandatangan ini bukan penamat, tetapi permulaan tanggungjawab baharu."}]}'),
(13, 'e1_n1_s13', 'Petikan Misi UNMM', 'Nyahkod petikan itu dan tentukan siapa yang persetujuannya disahkan.', '5', 'Memahami tujuan UNMM, tarikh penubuhannya dan pihak yang persetujuannya disahkan.', '{"clueText": "Petikan misi, 12 Ogos 1963: PBB mewujudkan misi ini untuk mengesahkan persetujuan. Pegawai misi bertemu penduduk Borneo bagi memastikan mereka benar-benar bersetuju dengan pembentukan Malaysia.", "options": [{"text": "Penduduk Sarawak dan Sabah", "isCorrect": true}, {"text": "Penduduk Singapura", "isCorrect": false, "consequence": "Rakyat Singapura sudah menjawab melalui referendum 1 September 1962, bukan UNMM."}, {"text": "Pemimpin British", "isCorrect": false, "consequence": "UNMM tidak mengesahkan pendapat pemimpin British. Ia bertemu penduduk Borneo."}, {"text": "Semua rakyat Persekutuan Tanah Melayu", "isCorrect": false, "consequence": "Persetujuan yang disahkan ialah persetujuan penduduk Sarawak dan Sabah."}], "aftermath": "Sasaran UNMM tersalah, dan orang ramai menyangka ada sesuatu yang disembunyikan.", "turns": [{"after": 5, "options": [{"text": "Aku hormati apa jua keputusan kamu, walaupun kamu menolak Malaysia.", "isCorrect": true, "reaction": "Penghulu mengangguk dan pegawai PBB mencatat. Kepercayaan penduduk bertambah."}, {"text": "Kami sudah memutuskan, misi ini hanya untuk melengkapkan rekod.", "isCorrect": false, "reaction": "Penghulu merenung tajam. Dia berasa suaranya tidak dihargai."}, {"text": "Aku fikir soalan itu tidak wajar ditanya kepada seorang pemimpin, jadi aku enggan menjawabnya.", "isCorrect": false, "reaction": "Donald menggeleng. Pegawai PBB berhenti menulis."}], "clue": "Misi PBB wujud untuk mendengar kehendak penduduk Borneo yang sebenar."}]}'),
(14, 'e1_n1_s14', 'Petikan Dokumen Pemasyhuran', 'Nyahkod petikan dokumen dan tentukan perkara yang dimasyhurkan.', '5', 'Memahami dokumen Pemasyhuran: yang menandatangani, tarikh, negeri terlibat dan nilai yang dijanjikan.', '{"clueText": "Petikan dokumen: Tunku Abdul Rahman Putra Al-Haj, Perdana Menteri, memasyhurkan bahawa mulai 16 September 1963, negeri-negeri Persekutuan Tanah Melayu bersama Singapura, Sabah dan Sarawak akan kekal menjadi sebuah negara demokrasi yang merdeka lagi berdaulat.", "options": [{"text": "Pemasyhuran Malaysia", "isCorrect": true}, {"text": "Perjanjian Malaysia", "isCorrect": false, "consequence": "Perjanjian ditandatangani di London pada 9 Julai 1963. Dokumen ini ialah Pemasyhuran."}, {"text": "Laporan Suruhanjaya Cobbold", "isCorrect": false, "consequence": "Laporan itu pada 21 Jun 1962. Dokumen ini memasyhurkan Malaysia."}, {"text": "Keputusan referendum Singapura", "isCorrect": false, "consequence": "Referendum diadakan 1 September 1962. Dokumen ini ialah Pemasyhuran."}], "aftermath": "Dokumen tersalah dikenal pasti, dan Hari Malaysia hilang maknanya dalam kalendar sekolah.", "turns": [{"after": 6, "options": [{"text": "Aku fikir sebut secara ringkas.", "isCorrect": true, "reaction": "Razak tersenyum. Harapan dan kejujuran seimbang dalam ucapan itu."}, {"text": "Ya, rakyat mesti tahu setiap kesukaran yang menanti, satu demi satu, dengan terperinci.", "isCorrect": false, "reaction": "Razak mengangguk perlahan, tetapi malam kemenangan itu terasa berat."}, {"text": "Aku fikir tidak, malam ini hanya untuk meraikan tanpa sebarang amaran.", "isCorrect": false, "reaction": "Razak risau. Rakyat mungkin terkejut apabila cabaran tiba."}], "clue": "Malam ini patut ada harapan tanpa melupakan cabaran."}]}'),
(15, 'e1_n1_s15', 'Kad Negeri di Dewan', 'Padankan setiap negeri atau wilayah dengan keterangan yang betul.', '4', 'Memadankan Persekutuan Tanah Melayu (11 negeri), Singapura, Sabah, Sarawak, Brunei dan Malaysia 1963.', '{"pairs": [{"text": "Persekutuan Tanah Melayu", "pair": 1}, {"text": "Sebelas negeri termasuk Pahang dan Melaka", "pair": 1}, {"text": "Singapura", "pair": 2}, {"text": "Bergabung pada 16 September 1963", "pair": 2}, {"text": "Sabah", "pair": 3}, {"text": "Disebut Borneo Utara dalam perjanjian 1963", "pair": 3}, {"text": "Sarawak", "pair": 4}, {"text": "Dilawat Tunku pada Julai 1961", "pair": 4}, {"text": "Brunei", "pair": 5}, {"text": "Menolak penyertaan dalam Malaysia", "pair": 5}, {"text": "Malaysia 1963", "pair": 6}, {"text": "Empat belas negeri pada tarikh Pemasyhuran", "pair": 6}], "aftermath": "Kad tersilap padan, dan guru membetulkan murid di hadapan kelas.", "turns": [{"after": 7, "options": [{"text": "Di mana-mana tempat yang selesa, sama seperti wakil negeri lain di dewan.", "isCorrect": true, "reaction": "Lee lega. Dia dilayan sebagai tetamu setara."}, {"text": "Di barisan hadapan, bersama Perdana Menteri, supaya Singapura sentiasa dekat.", "isCorrect": false, "reaction": "Lee tersenyum, tetapi wakil negeri lain berasa dipinggirkan."}, {"text": "Menurut aku, di belakang, kerana kamu belum biasa dengan protokol kami di sini.", "isCorrect": false, "reaction": "Lee menahan marah. Hari pertama sudah menyakitkan hati."}], "clue": "Semua rakan dalam Malaysia dilayan sama rata."}]}'),
(16, 'e1_n1_s16', 'Cabaran dan Pihaknya', 'Padankan setiap cabaran dengan pihak yang menimbulkannya.', '4', 'Memadankan cabaran: SUPP menolak, Indonesia konfrontasi 1963 hingga 1966, Filipina mendakwa Sabah dan Singapura berpisah 1965.', '{"pairs": [{"text": "SUPP", "pair": 1}, {"text": "Menolak kerana mahu persekutuan sendiri", "pair": 1}, {"text": "Indonesia", "pair": 2}, {"text": "Konfrontasi terhadap Malaysia, 1963 hingga 1966", "pair": 2}, {"text": "Filipina", "pair": 3}, {"text": "Mendakwa Sabah sebahagian daripada wilayahnya", "pair": 3}, {"text": "Singapura", "pair": 4}, {"text": "Berpisah daripada Malaysia pada 1965", "pair": 4}], "aftermath": "Padanan tersilap, dan setiap pihak menuduh pihak lain.", "turns": [{"after": 6, "options": [{"text": "Rasanya, tegas, tetapi berunding.", "isCorrect": true, "reaction": "Razak mengangguk. Pendirian yang kukuh tanpa menutup pintu."}, {"text": "Aku fikir balas ancaman dengan ancaman yang sama kuat, tanpa berunding langsung.", "isCorrect": false, "reaction": "Ghazali menarik nafas. Perang tidak akan memadamkan konfrontasi."}, {"text": "Aku fikir biarkan sahaja, nanti mereka berhenti sendiri tanpa kita berbuat apa-apa.", "isCorrect": false, "reaction": "Razak menggeleng. Berdiam diri akan dianggap lemah."}], "clue": "Tegas pada pendirian tetapi tetap membuka ruang rundingan."}]}'),
(17, 'e1_n1_s17', 'Rekod Lengkap untuk Arkib', 'Susun lapan langkah dari Adelphi hingga Pemasyhuran mengikut tarikh.', '1', 'Menyusun kronologi lapan langkah pembentukan Malaysia dari 27 Mei 1961 hingga 16 September 1963.', '{"timelineItems": [{"id": 1, "year": "27 Mei 1961", "text": "Tunku mengumumkan cadangan pembentukan Malaysia di Hotel Adelphi, Singapura", "why": "Langkah pertama: cadangan diumumkan kepada umum."}, {"id": 2, "year": "Julai 1961", "text": "Tunku melawat Sarawak untuk menerangkan idea Malaysia", "why": "Selepas pengumuman, Tunku menerangkan sendiri kepada pemimpin tempatan."}, {"id": 3, "year": "23 Julai 1961", "text": "JSKM ditubuhkan untuk meyakinkan pemimpin Sarawak dan Sabah", "why": "Pemimpin yang ragu memerlukan satu jawatankuasa bersama."}, {"id": 4, "year": "17 Januari 1962", "text": "Suruhanjaya Cobbold dibentuk untuk mendapatkan reaksi penduduk", "why": "Pemimpin sudah diyakinkan, kini rakyat pula perlu ditanya."}, {"id": 5, "year": "21 Jun 1962", "text": "Suruhanjaya Cobbold menyerahkan laporan: dua pertiga menyokong", "why": "Dapatan daripada rakyat dihantar kepada British dan Persekutuan."}, {"id": 6, "year": "9 Julai 1963", "text": "Perjanjian Malaysia ditandatangani di Marlborough House, London", "why": "Selepas dapatan dan perlembagaan, perjanjian pun ditandatangani."}, {"id": 7, "year": "12 Ogos 1963", "text": "UNMM mengesahkan persetujuan penduduk Sarawak dan Sabah", "why": "Persetujuan rakyat Borneo disahkan oleh PBB selepas perjanjian."}, {"id": 8, "year": "16 September 1963", "text": "Pemasyhuran Malaysia di empat tempat", "why": "Setelah semua disahkan, Malaysia dimasyhurkan."}], "aftermath": "Langkah bercampur, dan arkib negara mencatat sejarah yang tersilap.", "turns": [{"after": 5, "options": [{"text": "Tuliskan semua yang terlibat, daripada pemimpin hingga rakyat.", "isCorrect": true, "reaction": "Razak mengangguk. Sejarah dicatat sebagai kerja bersama."}, {"text": "Nama aku sahaja, kerana akulah yang mengumumkannya dan biarkan sahaja.", "isCorrect": false, "reaction": "Razak mengangkat kening. Fail di meja itu menunjukkan ramai yang terlibat."}, {"text": "Rasanya, semua pemimpin yang bekerjasama dari British hingga Borneo, termasuk rakyat biasa.", "isCorrect": false, "reaction": "Ghazali tersenyum, tetapi nama-nama itu terlalu panjang untuk satu baris rekod."}], "clue": "Pembentukan Malaysia ialah kerja bersama banyak pihak."}]}'),
(18, 'e1_n2_s1', 'Fail Lord Brassey', 'Nyahkod fail lama itu dan tentukan wilayah yang disebut Brassey selain Sarawak, Sabah dan Negeri-negeri Melayu.', '5', 'Memahami cadangan Lord Brassey 1887: menggabungkan Sarawak, Sabah, Negeri-negeri Melayu dan Negeri-negeri Selat.', '{"clueText": "Fail lama, 1887, tulisan Lord Brassey, Pengarah British North Borneo Company: dia mencadangkan penggabungan Sarawak, Sabah, Negeri-negeri Melayu dan sekumpulan negeri di Selat Melaka.", "options": [{"text": "Negeri-negeri Selat", "isCorrect": true}, {"text": "Brunei dan Filipina", "isCorrect": false, "consequence": "Itu bukan cadangan Brassey. Filipina muncul dalam konsep Melayu Raya 1938."}, {"text": "Kepulauan Indonesia", "isCorrect": false, "consequence": "Indonesia juga hanya muncul dalam Melayu Raya 1938, bukan fail ini."}, {"text": "Hong Kong", "isCorrect": false, "consequence": "Tiada kaitan dengan fail ini. Brassey bercakap tentang Borneo dan Tanah Melayu."}], "aftermath": "Fail tidak dapat dibaca, dan Mustapha Harun menyimpulkan idea ini rancangan British semata-mata.", "turns": [{"after": 7, "options": [{"text": "Idea ini sudah lama wujud. Sekarang barulah kita dilibatkan.", "isCorrect": true, "reaction": "Orang kampung mengangguk perlahan. Dia sedar suaranya kini dicari, bukan diabaikan."}, {"text": "Aku fikir kerana pemimpin mahu merahsiakannya supaya rakyat tidak membantah.", "isCorrect": false, "reaction": "Orang kampung makin marah dan menuduh semua pemimpin berbohong."}, {"text": "Kerana itu hanya khabar angin dan tidak perlu dipercayai langsung.", "isCorrect": false, "reaction": "Orang kampung berasa diperlekeh. Datu Mustapha menggeleng kecewa."}], "clue": "Idea itu lama, tetapi rakyat Sabah baru mula ditanya."}]}'),
(19, 'e1_n2_s2', 'Empat Tahun, Empat Idea', 'Padankan setiap tahun dengan tokoh dan idea yang betul.', '4', 'Memadankan 1887 (Brassey), 1938 (Melayu Raya), 1951 (MacDonald) dan 1955 (Tunku).', '{"pairs": [{"text": "1887", "pair": 1}, {"text": "Lord Brassey: Sarawak, Sabah, Negeri-negeri Melayu, Negeri-negeri Selat", "pair": 1}, {"text": "1938", "pair": 2}, {"text": "Ibrahim Yaakob dan Harun Aminurrashid: Melayu Raya", "pair": 2}, {"text": "1951", "pair": 3}, {"text": "Malcolm MacDonald: berbincang dengan pemimpin empat wilayah", "pair": 3}, {"text": "1955", "pair": 4}, {"text": "Tunku: empat wilayah menyertai Persekutuan Tanah Melayu", "pair": 4}], "aftermath": "Padanan tersilap, dan Mustapha menyebut Melayu Raya bukan cadangan Tunku. Tunku hanya menyebut empat wilayah.", "turns": [{"after": 5, "options": [{"text": "Tidak. Idea lama tidak bermakna keputusan sudah dibuat. Rakyat tetap perlu ditanya.", "isCorrect": true, "reaction": "Pemudi UNKO tersenyum lega. Kampung akan melihat UNKO benar-benar mahu mendengar."}, {"text": "Ya, kerana idea yang lama pasti baik untuk semua orang dan tidak perlu dipersoalkan lagi oleh sesiapa.", "isCorrect": false, "reaction": "Pemudi UNKO ragu. Cara itu persis cara yang ditakuti orang kampung."}, {"text": "Tidak perlu, pemimpin lebih tahu daripada orang kampung, kerana kita tidak rugi apa-apa.", "isCorrect": false, "reaction": "Datu Mustapha mengerutkan dahi. Itu sikap yang membuatkan rakyat menjauh."}], "clue": "Idea lama tidak menghilangkan hak rakyat untuk ditanya."}]}'),
(20, 'e1_n2_s3', 'Bukti Keselamatan di Atas Meja', 'Cari tiga bukti yang menunjukkan ancaman komunis dan pengalaman Persekutuan.', '2', 'Mencari bukti sebab keselamatan: ancaman komunis di Singapura, di Sarawak dan pengalaman Persekutuan Tanah Melayu.', '{"bgImage": "../assets/gameAsset/background/bilik_strategi_keselamatan.png", "hotspots": [{"name": "Laporan ancaman komunis di Singapura", "top": "68.9%", "left": "31.3%"}, {"name": "Laporan ancaman komunis di Sarawak", "top": "80.5%", "left": "20.6%"}, {"name": "Nota pengalaman Persekutuan menghadapi komunis", "top": "72%", "left": "56.1%"}], "aftermath": "Tanpa bukti, Razak menganggap hujah Donald lemah dan penduduk kampung kekal bimbang.", "turns": [{"after": 6, "options": [{"text": "Bersama Persekutuan yang berpengalaman, dengan hak Sabah tetap terjamin.", "isCorrect": true, "reaction": "Razak mengangguk. Jawapan itu mengakui keperluan keselamatan tanpa menggadai hak Sabah."}, {"text": "Pada pendapat aku, sabah cukup kuat menjaga dirinya sendiri tanpa bantuan sesiapa, kerana pasukannya sudah lengkap.", "isCorrect": false, "reaction": "Razak diam. Dia tahu pasukan di Sabah masih kecil."}, {"text": "Biar British sahaja yang menjaga Sabah selama-lamanya dan Sabah tidak perlu berbuat apa-apa.", "isCorrect": false, "reaction": "Razak menggeleng. Kemerdekaan tidak akan bermakna jika bergantung sepenuhnya pada orang luar."}], "clue": "Keselamatan dijaga bersama tanpa mengorbankan hak Sabah."}]}'),
(21, 'e1_n2_s4', 'Risalah Empat Sebab', 'Bantu Mustapha Harun memberi risalah yang betul kepada penduduk kampung.', '3', 'Membantu NPC memilih risalah yang menyenaraikan empat sebab pembentukan Malaysia yang betul.', '{"npcName": "Datu Mustapha", "prompt": "Penduduk kampung bertanya mengapa Sabah patut menyertai. Aku perlukan risalah yang menyenaraikan keempat-empat sebab pembentukan Malaysia.", "options": [{"text": "Keselamatan, keseimbangan kaum, kemerdekaan cepat, sosioekonomi", "item": "dokumen", "isCorrect": true}, {"text": "Keselamatan, keseimbangan kaum, kemerdekaan cepat, tambah tentera British", "item": "dokumen", "isCorrect": false, "consequence": "Orang kampung membantah: kami bukan mahu tentera tambahan. Sebab keempat ialah sosioekonomi."}, {"text": "Keselamatan dan ekonomi sahaja, tanpa soal kaum dan kemerdekaan", "item": "dokumen", "isCorrect": false, "consequence": "Seorang tua bertanya tentang kaum kita. Risalah itu terlepas dua sebab."}, {"text": "Hanya keseimbangan kaum, kerana Singapura sahaja sudah cukup", "item": "dokumen", "isCorrect": false, "consequence": "Mustapha menggeleng. Risalah ini tinggal satu sebab dan alasannya salah."}], "aftermath": "Risalah yang salah diedarkan, dan orang kampung mula bertanya adakah pemimpin mereka memahami rancangan ini.", "turns": [{"after": 5, "options": [{"text": "Rasanya, kita akan menulis perlindungan itu dalam perjanjian, bukan sekadar janji lisan.", "isCorrect": true, "reaction": "Orang kampung mengangguk. Dia lebih percaya kepada tulisan yang boleh dirujuk."}, {"text": "Pemimpin akan menjaga semuanya dengan baik dan kamu tidak perlu risau tentang perkara itu.", "isCorrect": false, "reaction": "Orang kampung diam. Dia sudah banyak mendengar janji yang tidak ditulis."}, {"text": "Rasanya, tanah hanya urusan pemerintah, bukan urusan kampung, kerana ramai orang buat begitu.", "isCorrect": false, "reaction": "Dewan berbisik marah. Tanah ialah nadi kehidupan mereka."}], "clue": "Janji mesti ditulis supaya boleh dirujuk."}]}'),
(22, 'e1_n2_s5', 'Tajuk Utama Adelphi', 'Nyahkod keratan akhbar dan tentukan tarikh pengumuman Tunku.', '5', 'Mengenal pasti tarikh pengumuman cadangan pembentukan Malaysia: 27 Mei 1961.', '{"clueText": "Keratan akhbar: Tunku Abdul Rahman mengumumkan cadangan pembentukan Malaysia di Hotel Adelphi, Singapura. Ini berlaku sebelum JSKM, sebelum Suruhanjaya Cobbold dan sebelum Perjanjian Malaysia.", "options": [{"text": "27 Mei 1961", "isCorrect": true}, {"text": "23 Julai 1961", "isCorrect": false, "consequence": "Itu tarikh JSKM ditubuhkan, selepas pengumuman."}, {"text": "17 Januari 1962", "isCorrect": false, "consequence": "Itu tarikh Suruhanjaya Cobbold dibentuk, lebih lewat lagi."}, {"text": "16 September 1963", "isCorrect": false, "consequence": "Itu tarikh Pemasyhuran Malaysia, kemuncak cerita ini."}], "aftermath": "Tarikh tersalah, dan akhbar esok menulis bahawa pemimpin Sabah keliru tentang kisahnya sendiri.", "turns": [{"after": 5, "options": [{"text": "Kami belum menolak atau menerima. Rakyat Sabah mesti didengar dahulu.", "isCorrect": true, "reaction": "Wartawan menulis pantas. Jawapan itu berimbang dan memberi ruang kepada UNKO."}, {"text": "Sebenarnya, kami menolak serta-merta kerana Sabah tidak mahu bergabung dengan sesiapa dalam keadaan ini.", "isCorrect": false, "reaction": "Wartawan tersenyum dan terus menulis tajuk besar. UNKO kini kelihatan tergesa-gesa menolak."}, {"text": "Kami menyokong sepenuhnya tanpa sebarang syarat, lagipun tiada akibatnya.", "isCorrect": false, "reaction": "Datu Mustapha menggeleng. Menyokong tanpa syarat bermakna menyerahkan semua tuntutan."}], "clue": "Jangan terburu-buru menerima atau menolak sebelum rakyat didengar."}]}'),
(23, 'e1_n2_s6', 'Bukti Lawatan di Tebing Sungai', 'Cari tiga bukti yang menunjukkan tujuan lawatan Tunku ke Sarawak.', '2', 'Mencari bukti lawatan Tunku ke Sarawak pada Julai 1961: menerangkan, mendengar dan menjawab soalan.', '{"bgImage": "../assets/gameAsset/background/lawatan_ke_sarawak.png", "hotspots": [{"name": "Pemimpin mendengar Tunku menerangkan idea Malaysia", "top": "61%", "left": "50%"}, {"name": "Penduduk berkumpul untuk bertanya tentang Sarawak", "top": "80%", "left": "30%"}, {"name": "Bot dan bendera di tebing, tanda lawatan Julai 1961", "top": "57%", "left": "71%"}], "aftermath": "Bukti tidak ditemui, dan Ningkan menyindir bahawa pemimpin patut memerhati perbincangan, bukan perabot.", "turns": [{"after": 6, "options": [{"text": "Ya. Sabah dan Sarawak patut bercakap bersama supaya suara Borneo lebih kuat.", "isCorrect": true, "reaction": "Jugah mengangguk. Dua suara Borneo kini berdiri sebaris."}, {"text": "Tidak, Sabah akan bersetuju dengan apa sahaja yang Tunku mahu tanpa perlu berunding dahulu.", "isCorrect": false, "reaction": "Jugah merenung tajam. Sabah dilihat tidak punya pendirian."}, {"text": "Sabah tidak perlu memikirkan Sarawak langsung kerana Sabah mempunyai kepentingan sendiri.", "isCorrect": false, "reaction": "Ningkan menyilang tangan. Borneo kelihatan berpecah sebelum berunding."}], "clue": "Borneo lebih kuat jika Sabah dan Sarawak bersuara bersama."}]}'),
(24, 'e1_n2_s7', 'Tokoh dan Parti di Meja JSKM', 'Padankan setiap tokoh dengan partinya.', '4', 'Memadankan Donald (UNKO), Jugah (PESAKA), Mustapha Harun (USNO), Ningkan (SNAP), Abang Haji Mustapha (PANAS) dan Tunku (UMNO).', '{"pairs": [{"text": "Donald Stephens", "pair": 1}, {"text": "UNKO (United National Kadazan Organization)", "pair": 1}, {"text": "Tun Temenggung Jugah", "pair": 2}, {"text": "PESAKA (Parti Pesaka Anak Sarawak)", "pair": 2}, {"text": "Datu Mustapha Datu Harun", "pair": 3}, {"text": "USNO (United Sabah National Organisation)", "pair": 3}, {"text": "Stephen Kalong Ningkan", "pair": 4}, {"text": "SNAP (Sarawak National Party)", "pair": 4}, {"text": "Datu Bandar Abang Haji Mustapha", "pair": 5}, {"text": "PANAS (Parti Negara Sarawak)", "pair": 5}, {"text": "Tunku Abdul Rahman", "pair": 6}, {"text": "UMNO (United Malays National Organisation)", "pair": 6}], "aftermath": "Pemimpin tersalah dipadankan, dan Abang Haji Mustapha menegur bahawa dia dari PANAS dan Jugah dari PESAKA.", "turns": [{"after": 5, "options": [{"text": "Ruang untuk pemimpin Borneo berunding sebelum apa-apa dimuktamadkan.", "isCorrect": true, "reaction": "Tunku mengangguk. Jawatankuasa ini benar-benar milik semua yang duduk di meja."}, {"text": "Supaya keputusan dibuat lebih pantas tanpa banyak soal daripada pemimpin-pemimpin yang ragu.", "isCorrect": false, "reaction": "Jugah mengerutkan dahi. Mereka datang untuk berunding, bukan untuk tergesa-gesa."}, {"text": "Supaya UNKO memperoleh kuasa lebih besar daripada parti lain di Sabah dan Sarawak.", "isCorrect": false, "reaction": "Datu Mustapha tersenyum sinis. Niat sebenar Donald dipersoalkan."}], "clue": "JSKM wujud untuk meyakinkan pemimpin Borneo melalui perundingan."}]}'),
(25, 'e1_n2_s8', 'Surat yang Dicari Wong Pow Nee', 'Bantu Wong Pow Nee memilih surat yang betul untuk suruhanjaya.', '3', 'Membantu NPC memilih memorandum penduduk, bukan laporan atau perjanjian yang belum wujud.', '{"npcName": "Wong Pow Nee", "prompt": "Saya mencari surat yang mencatat pendirian penduduk Sabah tentang Malaysia. Surat mana yang patut saya baca?", "options": [{"text": "Memorandum penduduk tentang pembentukan Malaysia", "item": "surat", "isCorrect": true}, {"text": "Laporan Cobbold kepada British dan Tanah Melayu", "item": "surat", "isCorrect": false, "consequence": "Laporan itu belum wujud. Ia ditulis selepas Cobbold selesai bertanya."}, {"text": "Perjanjian Malaysia yang ditandatangani di London", "item": "surat", "isCorrect": false, "consequence": "Perjanjian ini 9 Julai 1963, jauh selepas suruhanjaya."}, {"text": "Surat jemputan majlis kampung", "item": "surat", "isCorrect": false, "consequence": "Wong menggeleng. Surat ini tiada kaitan dengan pendirian penduduk."}], "aftermath": "Surat yang salah dipilih, dan suruhanjaya terlepas pandang suara penduduk.", "turns": [{"after": 5, "options": [{"text": "Sebenarnya, beritahu mereka memorandum akan dibaca dan suara mereka akan dicatat.", "isCorrect": true, "reaction": "Wong mengangguk. Penduduk yang takut mula berani menulis."}, {"text": "Beritahu mereka tidak perlu risau kerana keputusan sudah dibuat dan suara mereka tidak diperlukan.", "isCorrect": false, "reaction": "Wong menggeleng. Penduduk berasa tiada gunanya menulis."}, {"text": "Menurut aku, biarkan mereka diam supaya laporan lebih cepat siap dan lupakan sahaja.", "isCorrect": false, "reaction": "Ghazali membantah. Suruhanjaya wujud untuk mendengar, bukan menyenyapkan."}], "clue": "Suara penduduk mesti dicatat dan dibaca."}]}'),
(26, 'e1_n2_s9', 'Dari Adelphi ke Laporan', 'Susun lima langkah mengikut tarikh, dari yang paling awal.', '1', 'Menyusun kronologi: pengumuman Adelphi, lawatan Sarawak, JSKM, Cobbold dibentuk dan laporan Cobbold.', '{"timelineItems": [{"id": 1, "year": "27 Mei 1961", "text": "Tunku mengumumkan cadangan Malaysia di Hotel Adelphi, Singapura", "why": "Langkah pertama yang membuka seluruh cerita."}, {"id": 2, "year": "Julai 1961", "text": "Tunku melawat Sarawak untuk menerangkan idea Malaysia", "why": "Selepas mengumumkan, Tunku menerangkan sendiri kepada pemimpin Sarawak."}, {"id": 3, "year": "23 Julai 1961", "text": "JSKM ditubuhkan untuk meyakinkan pemimpin Sarawak dan Sabah", "why": "Pemimpin yang ragu memerlukan jawatankuasa bersama."}, {"id": 4, "year": "17 Januari 1962", "text": "Suruhanjaya Cobbold dibentuk untuk mendapatkan reaksi penduduk", "why": "Selepas pemimpin diyakinkan, rakyat pula ditanya."}, {"id": 5, "year": "21 Jun 1962", "text": "Cobbold menyerahkan laporan: dua pertiga menyokong", "why": "Dapatan daripada rakyat dikumpulkan dan diserahkan."}], "aftermath": "Langkah tersusun terbalik, dan Mustapha menyebut bagaimana kita boleh bertanya sebelum meyakinkan.", "turns": [{"after": 5, "options": [{"text": "Tidak. Suara kamu tetap dicatat dan dibawa ke rundingan seterusnya.", "isCorrect": true, "reaction": "Wakil SUPP melembut. Dia tahu pendiriannya tidak dibuang."}, {"text": "Ya, kerana majoriti sudah memutuskan dan selebihnya tidak penting untuk dibincangkan lagi.", "isCorrect": false, "reaction": "Wakil SUPP berpaling dan keluar tanpa kata."}, {"text": "Suara kamu berharga jika kamu bersetuju dengan kami sahaja dan menyertai gabungan ini.", "isCorrect": false, "reaction": "Ningkan mencebik. Itu bukan penghargaan yang sebenar."}], "clue": "Suara yang tidak bersetuju juga mesti dicatat."}]}'),
(27, 'e1_n2_s10', 'Dokumen Mesyuarat 30 Ogos 1962', 'Nyahkod dokumen dan tentukan badan yang dimaksudkan.', '5', 'Mengenal pasti JAK: wakil British, Persekutuan Tanah Melayu, Sarawak dan Sabah menyediakan rangka perlembagaan.', '{"clueText": "Dokumen mesyuarat, 30 Ogos 1962: wakil British, Persekutuan Tanah Melayu, Sarawak dan Sabah duduk bersama untuk menyediakan rangka perlembagaan yang melindungi kepentingan Sarawak dan Sabah.", "options": [{"text": "Jawatankuasa Antara Kerajaan (JAK)", "isCorrect": true}, {"text": "Jawatankuasa Setia Kawan Malaysia (JSKM)", "isCorrect": false, "consequence": "JSKM meyakinkan pemimpin Sarawak dan Sabah, ditubuhkan 23 Julai 1961."}, {"text": "Suruhanjaya Cobbold", "isCorrect": false, "consequence": "Cobbold mendapatkan reaksi penduduk, bukan menyediakan perlembagaan."}, {"text": "United Nations Malaysia Mission (UNMM)", "isCorrect": false, "consequence": "UNMM mengesahkan persetujuan penduduk, pada 12 Ogos 1963."}], "aftermath": "Badan tersilap dikenal pasti, dan Ningkan mempersoalkan siapa yang menulis perlindungan itu.", "turns": [{"after": 5, "options": [{"text": "Kepentingan Sabah dan Sarawak, seperti yang dituntut oleh penduduk.", "isCorrect": true, "reaction": "Razak mencatat. Tuntutan itu akan dimasukkan ke dalam rangka."}, {"text": "Kuasa Kuala Lumpur sahaja, supaya perkara lebih mudah diuruskan oleh satu pihak sahaja.", "isCorrect": false, "reaction": "Ningkan menepuk meja. Itu tidak betul. Cuba ingat semula apa yang kita dengar tadi."}, {"text": "Hal pertahanan dan tentera sahaja, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Razak menggeleng. Penduduk menuntut lebih daripada itu."}], "clue": "Perlindungan mesti meliputi kepentingan Sabah dan Sarawak."}]}'),
(28, 'e1_n2_s11', 'Dokumen Keputusan Referendum', 'Bantu Lee Kuan Yew mencari dokumen keputusan referendum yang betul.', '3', 'Membantu NPC memilih dokumen keputusan referendum Singapura, 1 September 1962.', '{"npcName": "Lee Kuan Yew", "prompt": "Dokumen keputusan referendum Singapura hilang di antara timbunan ini. Yang mana satu dokumen yang betul?", "options": [{"text": "Keputusan referendum: rakyat Singapura bersetuju", "item": "dokumen", "isCorrect": true}, {"text": "Laporan Cobbold: dua pertiga penduduk Sarawak dan Sabah menyokong", "item": "dokumen", "isCorrect": false, "consequence": "Dokumen ini tentang Sarawak dan Sabah, bukan Singapura."}, {"text": "Perjanjian Malaysia yang ditandatangani di London", "item": "dokumen", "isCorrect": false, "consequence": "Perjanjian itu belum wujud. Ia 9 Julai 1963."}, {"text": "Laporan UNMM tentang persetujuan penduduk Sarawak dan Sabah", "item": "dokumen", "isCorrect": false, "consequence": "UNMM ditubuhkan Ogos 1963, setahun lebih lewat."}], "aftermath": "Dokumen yang salah dipilih, dan Lee berasa rakyat Singapura tidak diberi perhatian.", "turns": [{"after": 5, "options": [{"text": "Selepas pegawai PBB bertemu penduduk Borneo dan mengesahkan persetujuan mereka.", "isCorrect": true, "reaction": "Lee mengangguk. Satu lagi langkah rasmi akan menyusul."}, {"text": "Esok pagi, selepas semua pemimpin bersetuju dan menandatangani surat sokongan bersama.", "isCorrect": false, "reaction": "Lee menggeleng. Persetujuan pemimpin tidak sama dengan persetujuan penduduk."}, {"text": "Tidak perlu, jawapan Singapura sudah mewakili semua, kerana ramai orang buat begitu.", "isCorrect": false, "reaction": "Razak menyangkal. Sarawak dan Sabah belum memberi jawapan akhir."}], "clue": "Persetujuan penduduk Borneo akan disahkan oleh PBB."}]}'),
(29, 'e1_n2_s12', 'Telegram yang Betul', 'Bantu Mustapha Harun memilih telegram tentang Perjanjian Malaysia.', '3', 'Membantu NPC memilih telegram yang betul: Perjanjian Malaysia, Marlborough House, London, 9 Julai 1963.', '{"npcName": "Datu Mustapha", "prompt": "Tiga telegram sampai serentak. Yang mana telegram yang betul tentang Perjanjian Malaysia?", "options": [{"text": "Perjanjian Malaysia ditandatangani di Marlborough House, London, 9 Julai 1963", "item": "telegram", "isCorrect": true}, {"text": "Cadangan Malaysia diumumkan di Hotel Adelphi, Singapura, 27 Mei 1961", "item": "telegram", "isCorrect": false, "consequence": "Itu pengumuman Tunku dua tahun lebih awal. Bukan perjanjian."}, {"text": "Suruhanjaya Cobbold dibentuk untuk mendapatkan reaksi, 17 Januari 1962", "item": "telegram", "isCorrect": false, "consequence": "Itu langkah awal. Perjanjian datang selepas laporan dan rundingan."}, {"text": "Pemasyhuran Malaysia diadakan di Kuala Lumpur, 16 September 1963", "item": "telegram", "isCorrect": false, "consequence": "Itu pemasyhuran, bukan perjanjian. Ia belum berlaku lagi."}], "aftermath": "Telegram yang salah dibaca, dan orang ramai mengingat tarikh yang tersilap.", "turns": [{"after": 5, "options": [{"text": "Menurut aku, umumkan hanya yang pasti: perjanjian ditandatangani di London pada 9 Julai 1963.", "isCorrect": true, "reaction": "Orang ramai bersorak perlahan. Datu Mustapha berpuas hati kerana berita itu tepat."}, {"text": "Umumkan semua telegram, biar orang ramai memilih sendiri yang mereka percaya dan membuat keputusan sendiri.", "isCorrect": false, "reaction": "Datu Mustapha menggeleng. Orang ramai akan keliru dan khabar angin bermula."}, {"text": "Umumkan bahawa Malaysia sudah wujud dan perjanjian tidak penting lagi, kerana itu lebih senang.", "isCorrect": false, "reaction": "Orang ramai berbisik. Pemasyhuran belum diadakan lagi."}], "clue": "Umumkan hanya fakta yang pasti."}]}'),
(30, 'e1_n2_s13', 'Tanda Bilik UNMM', 'Cari tiga bukti yang menunjukkan bilik ini bilik UNMM.', '2', 'Mencari bukti UNMM 12 Ogos 1963: perwakilan PBB, sepanduk misi dan peti undi penduduk.', '{"bgImage": "../assets/gameAsset/background/bilik_UNMM.png", "hotspots": [{"name": "Pegawai PBB berbaret biru sedang menghitung", "top": "67%", "left": "33%"}, {"name": "Sepanduk UNMM: meninjau hasil pungutan suara", "top": "10%", "left": "41%"}, {"name": "Peti undi PBB berisi pandangan penduduk", "top": "67%", "left": "9%"}], "aftermath": "Bilik tersalah kenal, dan Mustapha menegur bahawa pasukan PBB datang untuk tugas khusus.", "turns": [{"after": 5, "options": [{"text": "Sebenarnya, supaya pihak luar mengesahkan persetujuan penduduk, bukan paksaan.", "isCorrect": true, "reaction": "Pegawai PBB mencatat. Jawapan itu menepati tujuan misi."}, {"text": "Kerana laporan Cobbold dianggap tidak sah dan perlu disemak semula oleh pihak lain.", "isCorrect": false, "reaction": "Pegawai PBB menggeleng. Laporan Cobbold tidak ditolak."}, {"text": "Kerana penduduk belum pernah ditanya langsung oleh sesiapa sebelum ini di Borneo.", "isCorrect": false, "reaction": "Datu Mustapha menyangkal. Cobbold sudah bertanya kepada mereka."}], "clue": "UNMM mengesahkan persetujuan yang sudah ditanya."}]}'),
(31, 'e1_n2_s14', 'Empat Tempat, Empat Negeri', 'Padankan setiap tempat pemasyhuran dengan negerinya.', '4', 'Memadankan Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall dengan Persekutuan Tanah Melayu, Sarawak, Sabah dan Singapura.', '{"pairs": [{"text": "Kuala Lumpur", "pair": 1}, {"text": "Persekutuan Tanah Melayu", "pair": 1}, {"text": "Kuching", "pair": 2}, {"text": "Sarawak", "pair": 2}, {"text": "Kota Kinabalu", "pair": 3}, {"text": "Sabah", "pair": 3}, {"text": "City Hall", "pair": 4}, {"text": "Singapura", "pair": 4}], "aftermath": "Tempat tersilap dipadankan, dan Jugah membetulkan bahawa setiap negeri ada tempat pemasyhurannya sendiri.", "turns": [{"after": 4, "options": [{"text": "Sebenarnya, kerana empat wilayah itu bersama-sama membentuk Malaysia.", "isCorrect": true, "reaction": "Murid itu tersenyum. Dia faham Malaysia bukan milik satu tempat."}, {"text": "Menurut aku, kerana tempat itu paling dekat dengan tempat tinggal pemimpin.", "isCorrect": false, "reaction": "Murid itu keliru. Jawapan itu tidak menjelaskan apa-apa."}, {"text": "Kerana satu tempat tidak muat untuk semua orang, kerana itu lebih senang.", "isCorrect": false, "reaction": "Jugah tergelak kecil. Bukan itu sebabnya."}], "clue": "Empat wilayah bergabung, maka empat tempat meraikannya."}]}'),
(32, 'e1_n2_s15', 'Surat dari Seberang', 'Nyahkod surat itu dan tentukan wilayah yang didakwa Filipina.', '5', 'Memahami dakwaan Filipina ke atas Sabah sebagai cabaran selepas Pemasyhuran.', '{"clueText": "Surat dari Filipina: Filipina mendakwa wilayah tempat Donald Stephens dan Mustapha Harun berkhidmat sebagai sebahagian daripada wilayahnya.", "options": [{"text": "Sabah", "isCorrect": true}, {"text": "Sarawak", "isCorrect": false, "consequence": "Dakwaan Filipina ialah ke atas Sabah, wilayah Donald sendiri, bukan Sarawak."}, {"text": "Singapura", "isCorrect": false, "consequence": "Bukan Singapura. Cabaran Filipina tertumpu pada Sabah."}, {"text": "Brunei", "isCorrect": false, "consequence": "Brunei menolak penyertaan sendiri, bukan hasil dakwaan Filipina."}], "aftermath": "Wilayah tersilap dikenal pasti, dan jawapan Malaysia kepada Filipina menjadi kabur.", "turns": [{"after": 5, "options": [{"text": "Tidak. Penduduk sudah memilih Malaysia dan kita akan mempertahankannya.", "isCorrect": true, "reaction": "Pemudi UNKO menarik nafas lega. Pendirian Sabah jelas."}, {"text": "Ya, supaya Filipina tidak lagi marah kepada kita dan hubungan kedua-dua negara kembali baik.", "isCorrect": false, "reaction": "Datu Mustapha membantah. Itu bermakna menyerah tanpa melawan."}, {"text": "Tidak tahu, serahkan kepada pemimpin di Kuala Lumpur, kerana itu lebih senang.", "isCorrect": false, "reaction": "Pemudi UNKO kecewa. Sabah perlu ada suara sendiri."}], "clue": "Sabah memilih Malaysia dan akan mempertahankannya."}]}'),
(33, 'e1_n2_s16', 'Lapan Langkah untuk Ucapan', 'Susun lapan langkah dari Adelphi hingga Pemasyhuran mengikut tarikh.', '1', 'Menyusun kronologi: 27 Mei 1961, 23 Julai 1961, 17 Januari 1962, 21 Jun 1962, 30 Ogos 1962, 9 Julai 1963, 12 Ogos 1963 dan 16 September 1963.', '{"timelineItems": [{"id": 1, "year": "27 Mei 1961", "text": "Tunku mengumumkan cadangan Malaysia di Hotel Adelphi, Singapura", "why": "Pengumuman membuka seluruh perjalanan."}, {"id": 2, "year": "23 Julai 1961", "text": "JSKM ditubuhkan untuk meyakinkan pemimpin Sarawak dan Sabah", "why": "Selepas pengumuman, pemimpin perlu diyakinkan."}, {"id": 3, "year": "17 Januari 1962", "text": "Suruhanjaya Cobbold dibentuk untuk mendapatkan reaksi penduduk", "why": "Selepas pemimpin, rakyat pula ditanya."}, {"id": 4, "year": "21 Jun 1962", "text": "Cobbold menyerahkan laporan: dua pertiga menyokong", "why": "Dapatan rakyat dihantar kepada British dan Persekutuan."}, {"id": 5, "year": "30 Ogos 1962", "text": "JAK menyediakan rangka perlembagaan yang melindungi Sarawak dan Sabah", "why": "Dapatan laporan memerlukan perlindungan bertulis."}, {"id": 6, "year": "9 Julai 1963", "text": "Perjanjian Malaysia ditandatangani di Marlborough House, London", "why": "Selepas perlembagaan disediakan, perjanjian ditandatangani."}, {"id": 7, "year": "12 Ogos 1963", "text": "UNMM mengesahkan persetujuan penduduk Sarawak dan Sabah", "why": "Selepas perjanjian, PBB mengesahkan persetujuan rakyat Borneo."}, {"id": 8, "year": "16 September 1963", "text": "Pemasyhuran Malaysia di Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall", "why": "Setelah semua disahkan, Malaysia dimasyhurkan."}], "aftermath": "Langkah tersusun terbalik, dan Mustapha menyebut bagaimana PBB boleh mengesahkan sebelum ada perjanjian.", "turns": [{"after": 5, "options": [{"text": "Bagi aku, dengan mengingatkan bahawa Malaysia dibina dengan mendengar suara Borneo.", "isCorrect": true, "reaction": "Datu Mustapha mengangguk dan menulis. Penutup itu merangkum seluruh perjalanan."}, {"text": "Dengan menuntut lebih banyak kuasa tanpa berunding dengan sesiapa lagi, walaupun dibantah ramai.", "isCorrect": false, "reaction": "Murid-murid mengerutkan dahi. Itu bukan semangat yang membina Malaysia."}, {"text": "Bagi aku, dengan menyatakan bahawa kejayaan ini milik UNKO sahaja, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Datu Mustapha tersenyum sinis. Kejayaan ini milik ramai pihak."}], "clue": "Malaysia dibina dengan mendengar dan berunding."}]}'),
(34, 'e1_n3_s1', 'Fail 1938', 'Nyahkod fail lama itu dan tentukan konsep yang diperjuangkan.', '5', 'Mengenal pasti konsep Melayu Raya 1938 oleh Ibrahim Yaakob dan Harun Aminurrashid.', '{"clueText": "Fail 1938: Ibrahim Yaakob dan Harun Aminurrashid memperjuangkan satu konsep penyatuan Tanah Melayu, Singapura, Kalimantan, Filipina dan Indonesia.", "options": [{"text": "Melayu Raya", "isCorrect": true}, {"text": "Malaysia", "isCorrect": false, "consequence": "Nama Malaysia belum digunakan pada 1938. Konsep ini lebih luas."}, {"text": "Negeri-negeri Selat", "isCorrect": false, "consequence": "Itu cadangan Brassey 1887, bukan fail 1938."}, {"text": "Persekutuan Tanah Melayu", "isCorrect": false, "consequence": "Persekutuan ditubuhkan kemudian dan tidak merangkumi Filipina atau Indonesia."}], "aftermath": "Fail tidak dapat dibaca, dan Razak menegur bahawa pegawai tidak boleh menjawab dengan tekaan.", "turns": [{"after": 6, "options": [{"text": "Fail lama selalunya disimpan dahulu, baru dikaji apabila diperlukan.", "isCorrect": true, "reaction": "Razak mengangguk. Jawapan itu jujur dan tidak menuduh sesiapa."}, {"text": "Fail ini sengaja disorokkan supaya idea Melayu Raya dilupakan terus oleh semua orang.", "isCorrect": false, "reaction": "Razak mengerutkan dahi. Tuduhan tanpa bukti boleh memalukan Tunku."}, {"text": "Kita tidak tahu dan tidak perlu mencari tahu kerana fail itu tidak penting.", "isCorrect": false, "reaction": "Razak menggeleng. Pegawai yang baik tidak mengabaikan rekod."}], "clue": "Jawab dengan jujur: fail lama disimpan dan dikaji semula apabila diperlukan."}]}'),
(35, 'e1_n3_s2', 'Empat Idea Mengikut Tahun', 'Susun empat idea gabungan mengikut tahun, dari yang paling awal.', '1', 'Menyusun kronologi idea: 1887, 1938, 1951 dan 1955.', '{"timelineItems": [{"id": 1, "year": "1887", "text": "Lord Brassey mencadangkan penggabungan Sarawak, Sabah, Negeri-negeri Melayu dan Negeri-negeri Selat", "why": "Idea paling awal datang daripada pengarah syarikat."}, {"id": 2, "year": "1938", "text": "Ibrahim Yaakob dan Harun Aminurrashid memperjuangkan Melayu Raya", "why": "Kemudian orang Melayu pula mengemukakan konsep sendiri."}, {"id": 3, "year": "1951", "text": "Malcolm MacDonald berbincang dengan pemimpin empat wilayah", "why": "Pegawai British kembali membincangkannya."}, {"id": 4, "year": "1955", "text": "Tunku mencadangkan empat wilayah menyertai Persekutuan Tanah Melayu", "why": "Idea sampai kepada pemimpin Persekutuan."}], "aftermath": "Susunan tersilap, dan Razak menegur bahawa fail lama mesti disusun mengikut tahun.", "turns": [{"after": 7, "options": [{"text": "Tidak. Idea ini sudah dibincangkan oleh banyak pihak sebelum Tunku.", "isCorrect": true, "reaction": "Razak mengangguk. Ucapan akan lebih jujur dan selamat daripada pembetulan."}, {"text": "Boleh, kerana Tunku Perdana Menteri dan semua orang akan menerimanya.", "isCorrect": false, "reaction": "Razak membantah. Fail di atas meja ini membuktikan sebaliknya."}, {"text": "Boleh, tetapi hanya jika wartawan tidak bertanya lanjut tentang sejarahnya.", "isCorrect": false, "reaction": "Razak menggeleng. Rancangan itu bergantung pada nasib dan bukan fakta."}], "clue": "Fail-fail ini membuktikan idea gabungan datang daripada banyak pihak."}]}'),
(36, 'e1_n3_s3', 'Bukti Keselamatan', 'Cari empat bukti yang menunjukkan sebab keselamatan.', '2', 'Mencari bukti ancaman komunis di Singapura dan Borneo serta kertas laporan dan papan strategi.', '{"bgImage": "../assets/gameAsset/background/bilik_strategi_keselamatan.png", "hotspots": [{"name": "Peta Singapura", "top": "30%", "left": "38%"}, {"name": "Peta Borneo", "top": "30%", "left": "62%"}, {"name": "Kertas laporan ancaman", "top": "68.9%", "left": "31.3%"}, {"name": "Papan strategi keselamatan", "top": "13%", "left": "52%"}], "aftermath": "Bukti tidak dijumpai, dan Razak menganggap hujah Ghazali kurang kukuh.", "turns": [{"after": 5, "options": [{"text": "Persekutuan mahu membendung ancaman bersama kerana ancaman itu merentasi sempadan.", "isCorrect": true, "reaction": "Lee mengangguk perlahan. Jawapan itu tidak mengelak daripada tuduhannya."}, {"text": "Persekutuan hanya mahu menambah penduduk dan wilayah supaya lebih besar dan lebih berkuasa daripada negara jiran.", "isCorrect": false, "reaction": "Lee tersenyum sinis. Kecurigaannya kini benar-benar disahkan."}, {"text": "Itu bukan urusan pegawai seperti aku, tanyalah Tunku sendiri kerana beliau yang membuat keputusan.", "isCorrect": false, "reaction": "Lee mengangkat kening. Dia mahukan jawapan, bukan cara mengelak."}], "clue": "Ancaman komunis merentasi sempadan, jadi ia dibendung bersama."}]}'),
(37, 'e1_n3_s4', 'Empat Sebab, Empat Penjelasan', 'Padankan setiap sebab dengan penjelasannya.', '4', 'Memadankan empat sebab pembentukan Malaysia dengan penjelasan masing-masing.', '{"pairs": [{"text": "Keselamatan", "pair": 1}, {"text": "Membendung ancaman komunis", "pair": 1}, {"text": "Keseimbangan kaum", "pair": 2}, {"text": "Bilangan penduduk antara kaum menjadi seimbang", "pair": 2}, {"text": "Kemerdekaan", "pair": 3}, {"text": "Mempercepat kemerdekaan Sarawak, Sabah, Singapura dan Brunei", "pair": 3}, {"text": "Sosioekonomi", "pair": 4}, {"text": "Membangunkan ekonomi dan taraf hidup", "pair": 4}], "aftermath": "Padanan tersilap, dan Razak menegur bahawa empat sebab ini tidak boleh bercampur.", "turns": [{"after": 5, "options": [{"text": "Rasanya, supaya bilangan penduduk antara kaum menjadi lebih seimbang.", "isCorrect": true, "reaction": "Sambanthan mengangguk. Hujah itu menjawab kebimbangan kaumnya."}, {"text": "Supaya wilayah Persekutuan menjadi jauh lebih luas daripada Indonesia.", "isCorrect": false, "reaction": "Wong mengerutkan dahi. Keluasan bukan kebimbangan mereka."}, {"text": "Supaya pemimpin Persekutuan memegang jawatan yang lebih banyak.", "isCorrect": false, "reaction": "Sambanthan kecewa. Jawapan itu bersifat peribadi, bukan untuk rakyat."}], "clue": "Jika hanya Singapura bergabung, bilangan antara kaum tidak seimbang."}]}'),
(38, 'e1_n3_s5', 'Teks Ucapan Tunku', 'Bantu Tunku memilih teks ucapan yang betul.', '3', 'Membantu NPC memilih teks ucapan pengumuman Malaysia di Hotel Adelphi.', '{"npcName": "Tunku Abdul Rahman", "prompt": "Teks ucapan untuk Hotel Adelphi hilang. Yang mana satu yang betul?", "options": [{"text": "Teks pengumuman cadangan Malaysia, 27 Mei 1961", "item": "dokumen", "isCorrect": true}, {"text": "Teks Perjanjian Malaysia, 9 Julai 1963", "item": "dokumen", "isCorrect": false, "consequence": "Perjanjian itu belum wujud, dua tahun lagi."}, {"text": "Laporan Cobbold, 21 Jun 1962", "item": "dokumen", "isCorrect": false, "consequence": "Laporan itu belum ditulis lagi."}, {"text": "Teks Pemasyhuran Malaysia, 16 September 1963", "item": "dokumen", "isCorrect": false, "consequence": "Pemasyhuran jauh lebih lewat daripada hari ini."}], "aftermath": "Teks yang salah dibawa, dan wartawan menulis tajuk yang mengelirukan.", "turns": [{"after": 5, "options": [{"text": "Menurut aku, belum, kerana mereka masih perlu didengar dahulu.", "isCorrect": true, "reaction": "Tunku mengangguk. Jawapan itu jujur dan memberi ruang berunding."}, {"text": "Sudah, semua pemimpin Borneo bersetuju tanpa sebarang syarat.", "isCorrect": false, "reaction": "Tunku mengerutkan dahi. Itu belum benar dan wartawan akan membongkarnya."}, {"text": "Pada pendapat aku, itu rahsia kerajaan dan tidak boleh didedahkan kepada akhbar.", "isCorrect": false, "reaction": "Tunku menggeleng. Wartawan akan mengesyaki ada sesuatu yang disembunyikan."}], "clue": "Sarawak dan Sabah masih perlu didengar."}]}'),
(39, 'e1_n3_s6', 'Nota Kuching', 'Nyahkod nota dan tentukan tujuan lawatan.', '5', 'Memahami tujuan lawatan Tunku ke Sarawak pada Julai 1961.', '{"clueText": "Nota Julai 1961: Tunku berada di Kuching untuk bertemu pemimpin Sarawak dan menjelaskan satu idea kepada mereka.", "options": [{"text": "Menerangkan idea pembentukan Malaysia", "isCorrect": true}, {"text": "Menandatangani perjanjian", "isCorrect": false, "consequence": "Perjanjian ditandatangani di London pada 9 Julai 1963."}, {"text": "Menyerahkan laporan Cobbold", "isCorrect": false, "consequence": "Laporan Cobbold diserahkan pada 21 Jun 1962."}, {"text": "Mengadakan pemasyhuran", "isCorrect": false, "consequence": "Pemasyhuran pada 16 September 1963."}], "aftermath": "Tujuan tersilap dibaca, dan Razak menegur bahawa pegawai mesti teliti.", "turns": [{"after": 7, "options": [{"text": "Sebenarnya, terus mendengar dan menjelaskan lagi dengan sabar.", "isCorrect": true, "reaction": "Razak mengangguk. Perundingan memerlukan kesabaran."}, {"text": "Aku fikir memaksa mereka menerima kerana Persekutuan lebih besar dan lebih kuat.", "isCorrect": false, "reaction": "Razak membantah. Paksaan merosakkan seluruh gagasan ini."}, {"text": "Pulang ke Kuala Lumpur dan menggugurkan Sarawak daripada rancangan.", "isCorrect": false, "reaction": "Razak menggeleng. Menyerah terlalu awal bukan penyelesaian."}], "clue": "Penerangan yang sabar lebih berkesan daripada paksaan."}]}'),
(40, 'e1_n3_s7', 'Bukti JSKM', 'Cari empat bukti bahawa ini mesyuarat JSKM.', '2', 'Mencari bukti penubuhan JSKM pada 23 Julai 1961.', '{"bgImage": "../assets/gameAsset/background/bilik_jskm.png", "hotspots": [{"name": "Delegasi Sabah", "top": "60%", "left": "64%"}, {"name": "Delegasi Sarawak", "top": "66%", "left": "24%"}, {"name": "Dokumen mesyuarat", "top": "58%", "left": "45%"}, {"name": "Peta wilayah", "top": "25%", "left": "47%"}], "aftermath": "Bukti tidak ditemui, dan mesyuarat dianggap kurang teratur.", "turns": [{"after": 7, "options": [{"text": "Meyakinkan pemimpin Sarawak dan Sabah tentang pembentukan Malaysia.", "isCorrect": true, "reaction": "Donald mengangguk. Dia boleh menjelaskan kepada orang kampung."}, {"text": "Menandatangani Perjanjian Malaysia bagi pihak semua negeri yang terlibat dalam gabungan ini.", "isCorrect": false, "reaction": "Donald mengerutkan dahi. Perjanjian belum wujud pada tarikh ini."}, {"text": "Mengira undi rakyat Singapura dalam referendum yang akan datang.", "isCorrect": false, "reaction": "Donald menggeleng. Itu bukan tugas JSKM."}], "clue": "JSKM wujud untuk meyakinkan pemimpin Borneo."}]}'),
(41, 'e1_n3_s8', 'Kertas Arahan Cobbold', 'Nyahkod kertas dan tentukan tugas suruhanjaya.', '5', 'Mengenal pasti tugas Suruhanjaya Cobbold: mendapatkan reaksi penduduk Sarawak dan Sabah.', '{"clueText": "Kertas arahan 17 Januari 1962: sebuah suruhanjaya dibentuk untuk menemu ramah penduduk dan meneliti memorandum mereka di Sarawak dan Sabah.", "options": [{"text": "Mendapatkan reaksi penduduk", "isCorrect": true}, {"text": "Menyediakan perlembagaan", "isCorrect": false, "consequence": "Itu tugas JAK, bukan Cobbold."}, {"text": "Mengesahkan persetujuan penduduk", "isCorrect": false, "consequence": "Itu tugas UNMM, setahun kemudian."}, {"text": "Menandatangani perjanjian", "isCorrect": false, "consequence": "Perjanjian ditandatangani di London."}], "aftermath": "Tugas tersilap dikenal pasti, dan suruhanjaya hilang arah.", "turns": [{"after": 5, "options": [{"text": "Menurut aku, menerima memorandum bertulis supaya mereka boleh bersuara tanpa takut.", "isCorrect": true, "reaction": "Wong mengangguk. Cara itu melindungi suara penduduk."}, {"text": "Menunggu sehingga mereka berani bersuara tanpa perlu kita membantu, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Wong menggeleng. Suruhanjaya tidak boleh menunggu terlalu lama."}, {"text": "Meninggalkan mereka dan menulis laporan berdasarkan jawapan orang lain, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Wong membantah. Itu mengkhianati tugas suruhanjaya."}], "clue": "Memorandum bertulis membolehkan penduduk bersuara dengan selamat."}]}'),
(42, 'e1_n3_s9', 'Laporan Cobbold', 'Bantu Sambanthan memilih laporan yang betul.', '3', 'Membantu NPC memilih laporan Cobbold: dua pertiga menyokong.', '{"npcName": "T. Sambanthan", "prompt": "Yang mana laporan Cobbold yang betul?", "options": [{"text": "Laporan: dua pertiga menyokong, SUPP menolak", "item": "dokumen", "isCorrect": true}, {"text": "Laporan: semua penduduk bersetuju", "item": "dokumen", "isCorrect": false, "consequence": "Laporan itu salah. Tidak semua bersetuju."}, {"text": "Laporan: semua penduduk menolak", "item": "dokumen", "isCorrect": false, "consequence": "Laporan itu juga salah. Dua pertiga menyokong."}, {"text": "Perjanjian Malaysia 1963", "item": "dokumen", "isCorrect": false, "consequence": "Perjanjian itu belum wujud."}], "aftermath": "Laporan yang salah dibawa, dan rundingan tersasar.", "turns": [{"after": 5, "options": [{"text": "Aku fikir ya, laporan yang betul mencatat dua pertiga menyokong dan SUPP menolak.", "isCorrect": true, "reaction": "Wakil SUPP mengangguk perlahan. Suaranya tidak dipadam."}, {"text": "Pada pendapat aku, tidak, laporan hanya menyebut yang bersetuju supaya lebih ringkas dan tidak mengelirukan pembaca.", "isCorrect": false, "reaction": "Wakil SUPP marah. Suaranya cuba disenyapkan."}, {"text": "Mungkin, bergantung pada siapa yang menulis laporan itu nanti dan bagaimana keadaan semasa.", "isCorrect": false, "reaction": "Wakil SUPP mengerutkan dahi. Jawapan yang goyah tidak menenangkan sesiapa."}], "clue": "Laporan yang betul mencatat sokongan dan penolakan."}]}'),
(43, 'e1_n3_s10', 'Bukti JAK', 'Cari tiga bukti bahawa ini mesyuarat JAK.', '2', 'Mencari bukti mesyuarat JAK 30 Ogos 1962.', '{"bgImage": "../assets/gameAsset/background/bilik_mesyuarat_formal.png", "hotspots": [{"name": "Tempat duduk wakil British", "top": "49%", "left": "27%"}, {"name": "Tempat duduk wakil Persekutuan", "top": "45%", "left": "50%"}, {"name": "Rangka perlembagaan di atas meja", "top": "65%", "left": "41%"}], "aftermath": "Bukti tidak ditemui, dan mesyuarat dianggap tidak sah.", "turns": [{"after": 5, "options": [{"text": "Aku fikir menerangkan isinya dengan sabar sehingga semua pihak faham.", "isCorrect": true, "reaction": "Razak mengangguk. Rangka ini mesti difahami semua pihak."}, {"text": "Meneruskan mesyuarat tanpa pihak itu supaya cepat selesai dan semua orang boleh pulang.", "isCorrect": false, "reaction": "Razak membantah. JAK wujud untuk semua pihak."}, {"text": "Menggantikan wakil itu dengan orang lain yang lebih patuh kepada arahan sesiapa sahaja.", "isCorrect": false, "reaction": "Donald membantah. Wakil tidak patut dipilih kerana sifat patuh."}], "clue": "Semua pihak mesti faham rangka perlembagaan itu."}]}'),
(44, 'e1_n3_s11', 'Nota Keputusan', 'Nyahkod nota dan tentukan peristiwa itu.', '5', 'Mengenal pasti referendum Singapura 1 September 1962.', '{"clueText": "Nota 1 September 1962: rakyat Singapura mengundi untuk menyatakan pendirian mereka tentang pembentukan Malaysia.", "options": [{"text": "Referendum", "isCorrect": true}, {"text": "Pemasyhuran", "isCorrect": false, "consequence": "Pemasyhuran pada 16 September 1963."}, {"text": "Perjanjian", "isCorrect": false, "consequence": "Perjanjian pada 9 Julai 1963."}, {"text": "Penubuhan UNMM", "isCorrect": false, "consequence": "UNMM pada 12 Ogos 1963."}], "aftermath": "Peristiwa tersilap dikenal pasti.", "turns": [{"after": 5, "options": [{"text": "Aku fikir pendirian mereka tetap dicatat dan perancangan disemak semula.", "isCorrect": true, "reaction": "Lee mengangguk. Itu sikap pemimpin yang menghormati rakyat."}, {"text": "Keputusan itu diabaikan kerana pemimpin sudah bersetuju lebih awal dan tidak perlu diubah.", "isCorrect": false, "reaction": "Lee membantah. Referendum tidak bermakna jika diabaikan."}, {"text": "Referendum diulang berkali-kali sehingga akhirnya mereka bersetuju.", "isCorrect": false, "reaction": "Lee menggeleng. Itu bukan cara menghormati undi."}], "clue": "Keputusan referendum mesti dihormati."}]}'),
(45, 'e1_n3_s12', 'Fail Perjanjian', 'Bantu Razak memilih fail perjanjian yang betul.', '3', 'Membantu NPC memilih fail Perjanjian Malaysia: Marlborough House, 9 Julai 1963.', '{"npcName": "Tun Abdul Razak", "prompt": "Fail mana yang betul untuk Perjanjian Malaysia?", "options": [{"text": "Perjanjian Malaysia, Marlborough House, 9 Julai 1963", "item": "dokumen", "isCorrect": true}, {"text": "Pengumuman Adelphi, 27 Mei 1961", "item": "dokumen", "isCorrect": false, "consequence": "Itu pengumuman awal, bukan perjanjian."}, {"text": "Laporan UNMM, Ogos 1963", "item": "dokumen", "isCorrect": false, "consequence": "UNMM masih sebulan lagi."}, {"text": "Pemasyhuran, 16 September 1963", "item": "dokumen", "isCorrect": false, "consequence": "Pemasyhuran belum berlaku."}], "aftermath": "Fail yang salah dihantar, dan rundingan tertangguh.", "turns": [{"after": 5, "options": [{"text": "Penduduk Sarawak dan Sabah, melalui misi PBB yang akan bertemu mereka.", "isCorrect": true, "reaction": "Razak mengangguk. Ghazali sudah memikirkan langkah seterusnya."}, {"text": "Rasanya, tiada siapa lagi kerana tandatangan pemimpin sudah mencukupi bagi semua pihak yang terlibat.", "isCorrect": false, "reaction": "Razak mengerutkan dahi. Dunia mahu mendengar daripada penduduk sendiri."}, {"text": "Hanya rakyat Singapura kerana mereka sudah mengundi dalam referendum.", "isCorrect": false, "reaction": "Razak membantah. Penduduk Borneo belum disahkan lagi."}], "clue": "Penduduk Borneo masih perlu disahkan oleh misi PBB."}]}'),
(46, 'e1_n3_s13', 'Empat Badan, Empat Tugas', 'Padankan setiap badan dengan tugasnya.', '4', 'Memadankan JSKM, Cobbold, JAK dan UNMM dengan tugas masing-masing.', '{"pairs": [{"text": "JSKM", "pair": 1}, {"text": "Meyakinkan pemimpin Sarawak dan Sabah", "pair": 1}, {"text": "Suruhanjaya Cobbold", "pair": 2}, {"text": "Mendapatkan reaksi penduduk", "pair": 2}, {"text": "JAK", "pair": 3}, {"text": "Menyediakan rangka perlembagaan", "pair": 3}, {"text": "UNMM", "pair": 4}, {"text": "Mengesahkan persetujuan penduduk", "pair": 4}], "aftermath": "Padanan tersilap.", "turns": [{"after": 4, "options": [{"text": "Cobbold bertanya kepada penduduk, UNMM pula mengesahkan persetujuan mereka.", "isCorrect": true, "reaction": "Ahli UNMM mengangguk. Perbezaannya jelas dan tepat."}, {"text": "Kedua-duanya sama, hanya nama berbeza dan tarikh penubuhan yang tidak sama dalam sejarah.", "isCorrect": false, "reaction": "Ahli UNMM tersenyum nipis. Itu menafikan tujuan misinya."}, {"text": "UNMM menyediakan perlembagaan, Cobbold menandatangani perjanjian di London.", "isCorrect": false, "reaction": "Ahli UNMM menggeleng. Tugas itu bukan milik mereka."}], "clue": "Cobbold bertanya, UNMM mengesahkan."}]}'),
(47, 'e1_n3_s14', 'Bukti Pemasyhuran', 'Cari empat tempat Pemasyhuran pada peta.', '2', 'Mencari empat tempat Pemasyhuran Malaysia pada 16 September 1963.', '{"bgImage": "../assets/gameAsset/background/perancangan_pembentukan_malaysia.png", "hotspots": [{"name": "Kuala Lumpur: tempat pemasyhuran", "top": "50%", "left": "32%"}, {"name": "Kuching: tempat pemasyhuran", "top": "53%", "left": "55%"}, {"name": "Kota Kinabalu: tempat pemasyhuran", "top": "38%", "left": "61%"}, {"name": "City Hall, Singapura: tempat pemasyhuran", "top": "64%", "left": "47%"}], "aftermath": "Bukti tidak ditemui.", "turns": [{"after": 4, "options": [{"text": "Kerana Malaysia dibentuk oleh empat wilayah yang bergabung bersama.", "isCorrect": true, "reaction": "Murid itu mengangguk. Dia faham maksudnya."}, {"text": "Menurut aku, kerana satu dewan tidak cukup luas untuk semua orang yang ingin hadir pada hari itu.", "isCorrect": false, "reaction": "Murid itu keliru. Itu tidak betul. Cuba ingat semula apa yang kita dengar tadi."}, {"text": "Menurut aku, kerana setiap pemimpin mahu mengadakan majlis sendiri di wilayah masing-masing.", "isCorrect": false, "reaction": "Tunku tersenyum nipis. Bukan itu tujuannya."}], "clue": "Empat wilayah bergabung, maka empat tempat meraikannya."}]}'),
(48, 'e1_n3_s15', 'Cabaran Selepas Pemasyhuran', 'Padankan setiap pihak dengan cabarannya.', '4', 'Memadankan SUPP, Indonesia, Filipina dan Brunei dengan cabaran masing-masing.', '{"pairs": [{"text": "SUPP", "pair": 1}, {"text": "Mahu persekutuan sendiri", "pair": 1}, {"text": "Indonesia", "pair": 2}, {"text": "Konfrontasi 1963 hingga 1966", "pair": 2}, {"text": "Filipina", "pair": 3}, {"text": "Mendakwa Sabah", "pair": 3}, {"text": "Brunei", "pair": 4}, {"text": "Menolak penyertaan", "pair": 4}], "aftermath": "Padanan tersilap.", "turns": [{"after": 4, "options": [{"text": "Tidak. Cabaran adalah ujian dan Malaysia terus bertahan.", "isCorrect": true, "reaction": "Tunku tersenyum. Semangat itulah yang diperlukan."}, {"text": "Ya, kerana negara yang baik tidak akan menghadapi cabaran.", "isCorrect": false, "reaction": "Tunku menggeleng. Pandangan itu terlalu mudah."}, {"text": "Tidak tahu, kerana laporan ini belum dibaca habis.", "isCorrect": false, "reaction": "Tunku mengerutkan dahi. Seorang pegawai mesti membaca sebelum menjawab."}], "clue": "Cabaran menguji Malaysia, bukan menunjukkan kegagalan."}]}'),
(49, 'e1_n3_s16', 'Lapan Langkah', 'Susun lapan langkah mengikut tarikh.', '1', 'Menyusun kronologi lapan langkah pembentukan Malaysia.', '{"timelineItems": [{"id": 1, "year": "27 Mei 1961", "text": "Tunku mengumumkan cadangan Malaysia di Hotel Adelphi", "why": "Pengumuman membuka perjalanan."}, {"id": 2, "year": "23 Julai 1961", "text": "JSKM ditubuhkan", "why": "Pemimpin perlu diyakinkan."}, {"id": 3, "year": "17 Januari 1962", "text": "Suruhanjaya Cobbold dibentuk", "why": "Rakyat pula ditanya."}, {"id": 4, "year": "21 Jun 1962", "text": "Laporan Cobbold: dua pertiga menyokong", "why": "Dapatan diserahkan."}, {"id": 5, "year": "30 Ogos 1962", "text": "JAK menyediakan rangka perlembagaan", "why": "Perlindungan bertulis disediakan."}, {"id": 6, "year": "9 Julai 1963", "text": "Perjanjian Malaysia ditandatangani di London", "why": "Persetujuan dimeterai."}, {"id": 7, "year": "12 Ogos 1963", "text": "UNMM mengesahkan persetujuan penduduk", "why": "Persetujuan disahkan."}, {"id": 8, "year": "16 September 1963", "text": "Pemasyhuran Malaysia", "why": "Malaysia terbentuk."}], "aftermath": "Langkah tersusun terbalik.", "turns": [{"after": 4, "options": [{"text": "Bahawa ketepatan dan kerjasama membina sesuatu yang besar.", "isCorrect": true, "reaction": "Razak tersenyum. Dia tahu pegawai di sebalik tabir juga membina sejarah."}, {"text": "Bagi aku, bahawa pemimpin boleh bekerja sendirian tanpa pegawai di bawahnya.", "isCorrect": false, "reaction": "Razak mengangkat kening. Itu bukan pengajaran perjalanan ini."}, {"text": "Bahawa tarikh tidak penting selagi ceritanya sama.", "isCorrect": false, "reaction": "Razak menggeleng. Ketepatan ialah kekuatan seorang pegawai."}], "clue": "Ketepatan dan kerjasama membina Malaysia."}]}');
INSERT INTO LearningSupport (questID, sceneID, supportType, hint, explanation, feedback) VALUES
(NULL, 'e1_n1_s1', 'hint', 'Dua surat, dua zaman. Baca nama dan tahun pada setiap mohor.', NULL, NULL),
(1, NULL, 'hint', 'Ada dua tokoh dan dua cadangan. Baca tahun pada setiap kad, iaitu kad yang berkongsi tahun atau nama yang sama berpasangan. Senarai wilayah juga petunjuk.', 'Lord Brassey mencadangkan penggabungan pada 1887. Ibrahim Yaakob dan Harun Aminurrashid memperjuangkan Melayu Raya pada 1938. Idea penggabungan wilayah ini sudah lama wujud sebelum Tunku.', 'Tepat! Fail-fail itu kembali bersusun. Ketukan kuat di pintu. Razak masuk dengan dahi berkerut, "Draf ucapan Parlimen bercampur tarikhnya!" Sehelai telegram bercop 1951 terselit di bawah pintu. Item baharu, iaitu Telegram 1951.'),
(NULL, 'e1_n1_s2', 'hint', 'Empat tarikh, empat peringkat. Mulakan dengan yang paling lama.', NULL, NULL),
(2, NULL, 'hint', 'Baca tahun pada setiap kad. Idea paling awal datang daripada seorang pengarah syarikat British pada abad ke-19. Idea paling akhir disebut oleh pemimpin Persekutuan sendiri.', 'Urutannya ialah 1887 Brassey, 1938 Melayu Raya, 1951 MacDonald, 1955 Tunku. Idea bermula daripada British, kemudian tokoh tempatan, lalu pemimpin Persekutuan. Pada 1955 Tunku sendiri mencadangkan Sarawak, Sabah, Singapura dan Brunei menyertai Persekutuan.', 'Hebat! Draf kini bersusun dan pencetak boleh bermula. Razak mengunci pintu dan merendahkan suara, "Sebab sebenar kita tergesa-gesa bukan di dalam draf. Ada laporan di bilik bawah tanah." Item baharu. Kunci Bilik Strategi.'),
(NULL, 'e1_n1_s3', 'hint', 'Peta di dinding, tajuk papan dan laporan di atas meja ialah buktinya.', NULL, NULL),
(3, NULL, 'hint', 'Empat bukti, iaitu dua peta pada papan besar di dinding (satu di sebelah kiri, satu di sebelah kanan), tajuk papan itu di bahagian paling atas tengah, dan timbunan buku laporan hijau di atas meja sebelah kiri.', 'Punca pertama ialah menjamin keselamatan negara. Ancaman komunis wujud di Singapura dan Sarawak. Pengalaman Persekutuan menghadapi komunis membantu membendungnya.', 'Berjaya! Keempat-empat bukti ditemui dan Lee mengangguk. Telefon di sudut bilik berdering. Ghazali menjawab, wajahnya berubah, "Wong Pow Nee dan Sambanthan meminta bertemu segera. Mereka mahu tahu sebab lain." Item baharu. Laporan Hijau.'),
(NULL, 'e1_n1_s4', 'hint', 'Empat kad kosong, empat sebab. Baca penjelasan, kemudian pasangkan.', NULL, NULL),
(4, NULL, 'hint', 'Padankan mengikut makna, bukan perkataan yang sama sahaja. ''Membendung'' bermaksud menahan sesuatu yang mengancam. ''Taraf hidup'' dan ''infrastruktur'' berkait dengan ekonomi.', 'Empat sebab itu ialah keselamatan, keseimbangan kaum, kemerdekaan lebih cepat dan sosioekonomi. Gabungan menyeimbangkan bilangan penduduk antara kaum. Infrastruktur dan taraf hidup rakyat dipertingkatkan.', 'Bagus! Empat sebab sudah berpadanan dan hujah Tunku kini berlapis. Wong meletakkan sehelai keratan akhbar baharu di atas meja, "Kalau semua ini benar, umumkan sendiri, Tunku. Singapura sedang menunggu." Item baharu. Keratan Akhbar Adelphi.'),
(NULL, 'e1_n1_s5', 'hint', 'Pengumuman ini lebih awal daripada lawatan ke Sarawak dan JSKM.', NULL, NULL),
(5, NULL, 'hint', 'Baca ayat terakhir keratan. Peristiwa ini berlaku sebelum lawatan ke Sarawak dan penubuhan JSKM. Pilih tarikh yang lebih awal daripada Julai 1961.', 'Pada 27 Mei 1961, Tunku mengumumkan cadangan Malaysia di Hotel Adelphi, Singapura. Itu langkah pertama ke arah pembentukan Malaysia. Selepas itu barulah lawatan ke Sarawak dan penubuhan JSKM.', 'Tepat! Tepukan bergema di dewan. Donald Stephens menghampiri Tunku dan berbisik, "Kalau betul mahu membawa Borneo, datanglah ke Sarawak sendiri. Mereka mahu melihat muka orang yang mengumumkan ini." Item baharu. Jemputan ke Sarawak.'),
(NULL, 'e1_n1_s6', 'hint', 'Tiga pemimpin, tiga parti. Jugah bermula dengan PESAKA.', NULL, NULL),
(6, NULL, 'hint', 'Jugah ialah pemimpin Iban bergelar Tun Temenggung, dan partinya bermula dengan ''Pesaka''. Padankan dia dahulu, dua lagi lebih mudah.', 'Tun Temenggung Jugah ialah PESAKA. Stephen Kalong Ningkan ialah SNAP. Datu Bandar Abang Haji Mustapha ialah PANAS. Tunku melawat Sarawak pada Julai 1961 untuk menerangkan idea Malaysia.', 'Betul! Ketiga-tiga pemimpin berpuas hati. Malam itu Jugah berkata perlahan, "Kami boleh mempertimbangkan. Tetapi bukan dalam bilik tertutup. Biar ada jawatankuasa terbuka, dengan wakil Sabah sekali." Item baharu, Surat Cadangan Jawatankuasa.'),
(NULL, 'e1_n1_s7', 'hint', 'Papan nama, pemimpin dan dokumen. Semuanya ada di atas atau sekeliling meja.', NULL, NULL),
(7, NULL, 'hint', 'Empat bukti, iaitu papan nama jawatankuasa di dinding sebelah kanan atas, pemimpin Sarawak duduk di kiri bawah meja, pemimpin Sabah duduk di kanan meja, dan dokumen cadangan di tengah meja.', 'Pada 23 Julai 1961, Jawatankuasa Setia Kawan Malaysia (JSKM) ditubuhkan. Tujuannya meyakinkan pemimpin Sarawak dan Sabah. Donald Stephens dan Jugah antara yang terlibat.', 'Hebat! Keempat-empat bukti ditemui dan mesyuarat bermula. Selepas itu Ghazali menghampiri dengan wajah serius, "Pemimpin sudah yakin, Tuan. Tetapi rakyat biasa belum ditanya. British mahu satu suruhanjaya turun ke Borneo." Item baharu. Mohor JSKM.'),
(NULL, 'e1_n1_s8', 'hint', 'Dua kad ialah nama orang, dua kad ialah tarikh.', NULL, NULL),
(8, NULL, 'hint', 'Dua kad ialah nama orang dan dua kad ialah tarikh. Tarikh Januari ialah suruhanjaya dibentuk untuk bertanya kepada rakyat. Tarikh Jun ialah laporan yang diserahkan selepas bertanya.', 'Pada 17 Januari 1962, Suruhanjaya Cobbold dibentuk untuk mendapatkan reaksi penduduk Sarawak dan Sabah. Wong Pow Nee dan Ghazali Shafie ialah ahli suruhanjaya. Pada 21 Jun 1962, laporan menunjukkan dua pertiga penduduk menyokong Malaysia.', 'Betul! Setiap sampul kembali ke tempatnya. Tidak lama kemudian Ghazali melangkah masuk dengan satu halaman yang koyak, "Laporan jelas, Tuan. Tetapi satu parti enggan ia disebut sebagai persetujuan semua." Item baharu. Halaman Laporan Cobbold.'),
(NULL, 'e1_n1_s9', 'hint', 'Cari parti yang mahu membentuk persekutuan sendiri.', NULL, NULL),
(9, NULL, 'hint', 'Perhatikan ''menolak'' dan ''persekutuan sendiri''. Jugah (PESAKA) menyertai JSKM, jadi partinya bukan yang menolak. Singkirkan PESAKA dahulu.', 'SUPP menolak kerana mahu persekutuan sendiri. Dua pertiga penduduk menyokong, satu pertiga tidak. Bantahan itu membawa kepada perlunya perlindungan bertulis dalam perlembagaan.', 'Tepat! SUPP dikenal pasti. Ghazali menutup fail, "Suara menolak tidak hilang dengan pujukan, Tuan. Mesti ada perlindungan bertulis. Satu jawatankuasa baharu sedang dibentuk." Item baharu. Nota Bantahan SUPP.'),
(NULL, 'e1_n1_s10', 'hint', 'Tiga kategori, iaitu ahli, tujuan dan tarikh.', NULL, NULL),
(10, NULL, 'hint', 'Ada tiga kategori, iaitu ahli, tujuan dan tarikh. Kad tarikh berbentuk hari dan bulan, kad tujuan menyebut perlembagaan, kad ahli menyenaraikan pihak yang duduk bersama.', 'JAK bermesyuarat pada 30 Ogos 1962. Ahlinya terdiri daripada wakil British, Persekutuan Tanah Melayu, Sarawak dan Sabah. Tujuannya ialah menyediakan rangka perlembagaan yang melindungi kepentingan Sarawak dan Sabah.', 'Betul! Butiran JAK tepat. Seorang pegawai British menutup fail, "Satu pihak belum menjawab, Tunku, Singapura. Rakyatnya mesti mengundi." Item baharu. Draf Perlembagaan JAK.'),
(NULL, 'e1_n1_s11', 'hint', 'Semua langkah dalam tahun 1962. Mulakan dengan Januari.', NULL, NULL),
(11, NULL, 'hint', 'Semua langkah dalam tahun 1962. Susun mengikut bulan. Mulakan dengan Januari, dan langkah terakhir ialah undi rakyat Singapura pada September.', 'Urutannya ialah Cobbold (17 Jan), laporan (21 Jun), JAK (30 Ogos), referendum (1 September). Rakyat Singapura bersetuju dengan pembentukan Malaysia melalui referendum. Referendum berlaku dua hari selepas JAK bermesyuarat.', 'Tepat! Seorang pegawai berlari masuk, "Rakyat Singapura bersetuju!" Ghazali menghulurkan sekeping tiket, "Kapal terbang ke London malam ini, Tuan. Perjanjian akhir akan ditandatangani di sana." Item baharu. Tiket ke London.'),
(NULL, 'e1_n1_s12', 'hint', 'Cari bukti di atas dan sekeliling meja perjanjian.', NULL, NULL),
(12, NULL, 'hint', 'Empat bukti di atas meja perjanjian, iaitu dua pen bulu dengan dakwat di bahagian atas meja (kiri dan kanan patung singa), dokumen perjanjian di tengah meja, dan alas meja merah di bahagian depan meja.', 'Pada 9 Julai 1963, Perjanjian Malaysia ditandatangani di Marlborough House, London. Jugah dan Abang Haji Mustapha antara yang menandatangani. Perjanjian ini membawa kepada pemasyhuran Malaysia.', 'Hebat! Keempat-empat bukti ditemui dan perjanjian ditandatangani. Seorang pegawai PBB menyerahkan kad namanya, "Perjanjian sudah ditandatangani. Tetapi dunia mahu memastikan penduduk Borneo benar-benar bersetuju." Item baharu. Salinan Perjanjian Malaysia.'),
(NULL, 'e1_n1_s13', 'hint', 'Cari pihak yang dilawati pegawai misi PBB.', NULL, NULL),
(13, NULL, 'hint', 'Baca ''bertemu penduduk Borneo bagi memastikan mereka bersetuju''. Rakyat Singapura sudah mengundi dalam referendum yang berasingan. Pilih pihak yang dilawati pegawai misi.', 'Pada 12 Ogos 1963, UNMM mengesahkan persetujuan penduduk Sarawak dan Sabah. UNMM ialah misi PBB yang bertemu penduduk Borneo. Rakyat Singapura sudah menjawab melalui referendum, bukan UNMM.', 'Betul! Pegawai PBB menutup begnya, "Laporan akan sampai ke New York. Sekarang kamu perlu menyediakan satu perkara lagi, iaitu pengumuman rasmi." Item baharu, Laporan UNMM.'),
(NULL, 'e1_n1_s14', 'hint', 'Cari dokumen yang menyebut mulai 16 September.', NULL, NULL),
(14, NULL, 'hint', 'Dokumen ini menyatakan Malaysia wujud ''mulai 16 September''. Perjanjian pula ditandatangani di London pada Julai. Pilih nama dokumen yang memberitahu umum bahawa Malaysia sudah wujud.', 'Pada 16 September 1963, Tunku memasyhurkan Malaysia. Malaysia terdiri daripada Persekutuan Tanah Melayu, Singapura, Sabah dan Sarawak. Perjanjian Malaysia (9 Julai) dan Pemasyhuran (16 September) ialah dua dokumen berbeza.', 'Betul! Sorakan bergema ke seluruh stadium. Selepas itu Ghazali menghulurkan sebuah peta, "Malaysia sudah lahir, Tuan. Tetapi kad negeri di dewan masih bercampur. Rakyat perlu tahu siapa yang sudah bersama kita." Item baharu. Naskhah Pemasyhuran.'),
(NULL, 'e1_n1_s15', 'hint', 'Mulakan dengan kad yang bernombor.', NULL, NULL),
(15, NULL, 'hint', 'Mulakan dengan kad yang mempunyai nombor, ''sebelas negeri'' dan ''empat belas negeri'' ialah dua bentuk Persekutuan, sebelum dan selepas bergabung. Kemudian cari negeri yang menolak.', 'Persekutuan Tanah Melayu ialah sebelas negeri. Malaysia ialah empat belas negeri. Singapura, Sabah dan Sarawak bersama Persekutuan Tanah Melayu membentuk Malaysia. Brunei menolak penyertaan dalam Malaysia.', 'Bagus! Setiap kad negeri kembali ke tempatnya. Sepucuk telegram tiba di tangan Ghazali. "Bukan semua pihak gembira, Tuan. Ada yang mahu menggagalkan Malaysia sebelum ia berumur setahun." Item baharu. Peta Negeri Malaysia.'),
(NULL, 'e1_n1_s16', 'hint', 'Padankan pihak dengan tindakannya.', NULL, NULL),
(16, NULL, 'hint', 'Padankan pihak dengan tindakannya, iaitu satu mahu persekutuan sendiri, satu melancarkan konfrontasi dengan tarikh tahun, satu menuntut Sabah, dan satu berpisah pada 1965.', 'Cabarannya ialah SUPP menolak, Indonesia melancarkan konfrontasi (1963 hingga 1966), Filipina menuntut Sabah. Singapura berpisah daripada Malaysia pada 1965. Malaysia diuji dari dalam dan luar sejak awal.', 'Betul! Setiap pihak sudah ditempatkan dengan tepat. Ghazali menghulurkan sampul terakhir, "Semua mengarah ke satu tempat, Tuan. Arkib negara mahu rekod lengkap, satu garis masa dari Adelphi hingga Pemasyhuran." Item baharu, Sampul Arkib.'),
(NULL, 'e1_n1_s17', 'hint', 'Kumpulkan langkah mengikut tahun dahulu.', NULL, NULL),
(17, NULL, 'hint', 'Tiga langkah pada 1961, dua pada 1962 dan tiga pada 1963. Kumpulkan mengikut tahun dahulu, kemudian susun mengikut bulan.', 'Urutannya ialah Adelphi (27 Mei 1961), lawatan Sarawak (Julai 1961), JSKM (23 Julai 1961). Cobbold (17 Januari 1962) dan laporan (21 Jun 1962). Perjanjian Malaysia (9 Julai 1963), UNMM (12 Ogos 1963) dan Pemasyhuran (16 September 1963).', 'Tepat! Rekod lengkap disimpan. Ghazali menutup peti, "Rekod ini lengkap, Tuan. Tetapi cerita Malaysia baharu bermula." Item baharu. Rekod Pembentukan Malaysia.'),
(NULL, 'e1_n2_s1', 'hint', 'Fail 1887 menyebut satu kumpulan negeri di Selat Melaka.', NULL, NULL),
(18, NULL, 'hint', 'Tiga wilayah sudah disebut. Wilayah keempat ialah ''sekumpulan negeri di Selat Melaka''. Pilih nama yang menyebut negeri-negeri di tepi selat itu, bukan negara lain.', 'Lord Brassey (1887) mencadangkan penggabungan Sarawak, Sabah, Negeri-negeri Melayu dan Negeri-negeri Selat. Brassey ialah Pengarah British North Borneo Company. Idea penggabungan sudah lama wujud sebelum Tunku.', 'Tepat! Negeri-negeri Selat ialah kumpulan negeri yang disebut. Di bawah fail Brassey, Donald menemui tiga fail lagi bertahun 1938, 1951 dan 1955. Datu Mustapha berkata, "Bawa semuanya ke meja besar. Orang kampung perlu nampak tali di antaranya." Item baharu. Tiga Fail Tahun.'),
(NULL, 'e1_n2_s2', 'hint', 'Empat tahun, empat tokoh. Padankan tahun dengan tokohnya.', NULL, NULL),
(19, NULL, 'hint', 'Mulakan dengan yang pasti. 1938 ialah Melayu Raya. Kemudian tentukan mana yang lebih awal antara Brassey (pengarah syarikat British) dan MacDonald (pegawai British selepas perang).', 'Urutannya ialah 1887 Brassey, 1938 Melayu Raya, 1951 MacDonald, 1955 Tunku. Ibrahim Yaakob dan Harun Aminurrashid memperjuangkan Melayu Raya pada 1938. Pada 1955 Tunku mencadangkan empat wilayah menyertai Persekutuan Tanah Melayu.', 'Hebat! Empat tahun dan empat idea kini berpasangan. Pintu pejabat dibuka kasar. Tun Razak masuk membawa sebuah beg kulit, "Donald, aku datang membawa kebimbangan, bukan tarikh. Ada laporan yang kau mesti lihat." Item baharu. Beg Laporan Razak.'),
(NULL, 'e1_n2_s3', 'hint', 'Dua laporan dan satu nota di atas meja. Cari ketiga-tiganya.', NULL, NULL),
(20, NULL, 'hint', 'Tiga bukti di atas meja di bahagian bawah gambar, iaitu dua laporan di sebelah kiri (satu lebih rendah, bertulis ''National Security Dossiers'') dan satu nota kertas di tengah-kanan.', 'Punca pertama ialah menjamin keselamatan negara. Ancaman komunis wujud di Singapura dan Sarawak. Persekutuan Tanah Melayu sudah ada pengalaman menghadapi komunis.', 'Berjaya! Ketiga-tiga bukti ditemui. Razak menutup begnya, "Malam ini ada pertemuan di dewan kampung. Datu Mustapha mahu kau menjawab soalan penduduk. Bawa bukti ini." Item baharu. Laporan Ancaman Komunis.'),
(NULL, 'e1_n2_s4', 'hint', 'Risalah yang betul menyenaraikan empat sebab dengan tepat.', NULL, NULL),
(21, NULL, 'hint', 'Cari risalah yang menyenaraikan keempat-empat sebab, iaitu keselamatan, kaum, kemerdekaan dan sosioekonomi. Pilihan yang menggantikan salah satu daripadanya dengan perkara lain adalah salah.', 'Empat sebab itu ialah keselamatan, keseimbangan kaum, kemerdekaan lebih cepat dan sosioekonomi. Kemerdekaan Sarawak, Sabah, Singapura dan Brunei dapat dipercepat. Infrastruktur dan taraf hidup rakyat dipertingkatkan.', 'Tepat! Risalah yang betul diedarkan ke seluruh dewan. Seorang budak berlari masuk dengan sehelai akhbar basah, "Tuan! Tunku sudah bercakap di Singapura!" Item baharu. Akhbar Pagi.'),
(NULL, 'e1_n2_s5', 'hint', 'Pengumuman itu berlaku sebelum JSKM dan Cobbold.', NULL, NULL),
(22, NULL, 'hint', 'Ayat terakhir. Peristiwa ini sebelum JSKM, sebelum Cobbold dan sebelum Perjanjian. JSKM ditubuhkan Julai 1961, jadi tarikh yang dicari mesti lebih awal.', 'Pada 27 Mei 1961, Tunku mengumumkan cadangan Malaysia di Hotel Adelphi, Singapura. Ini berlaku sebelum JSKM, Suruhanjaya Cobbold dan Perjanjian Malaysia. Pengumuman itu cadangan, bukan keputusan akhir.', 'Betul! Tarikh pengumuman dicatat. Datu Mustapha menyerahkan sepucuk surat berlak, "Daripada Kuching. Pemimpin Sarawak menjemput kita menyaksikan lawatan Tunku. Mereka mahu suara Sabah di sana." Item baharu. Jemputan ke Kuching.'),
(NULL, 'e1_n2_s6', 'hint', 'Cari pemimpin yang mendengar, penduduk yang bertanya dan bot di tebing.', NULL, NULL),
(23, NULL, 'hint', 'Tiga bukti di tebing sungai, iaitu kumpulan lelaki berpakaian kemas di tengah, penduduk yang berkumpul di bahagian bawah sebelah kiri, dan bot berbendera di kanan sungai.', 'Pada Julai 1961, Tunku melawat Sarawak untuk menerangkan idea Malaysia. Pemimpin Sarawak mendengar dan penduduk bertanya. Sarawak mahu dilayan sebagai rakan, bukan wilayah tambahan.', 'Bagus! Ketiga-tiga petanda lawatan ditemui. Jugah mendekati Donald, "Kalau Sabah dan Sarawak mahu berunding bersama, kita perlukan satu meja. Tunku sedang memikirkan satu jawatankuasa." Item baharu. Nota Kuching.'),
(NULL, 'e1_n2_s7', 'hint', 'Padankan setiap tokoh dengan parti yang diwakilinya.', NULL, NULL),
(24, NULL, 'hint', 'Nama parti mengandungi kata petunjuk, ''Kadazan'' dan ''Sabah'' menunjuk ke Sabah, ''Pesaka'' dan ''Sarawak'' menunjuk ke Sarawak, ''Malays'' ialah parti Tunku. Mulakan dengan Tunku.', 'Pada 23 Julai 1961, JSKM ditubuhkan untuk meyakinkan pemimpin Sarawak dan Sabah. Donald Stephens ialah UNKO. Mustapha Harun ialah USNO. Jugah ialah PESAKA. Ningkan ialah SNAP. Abang Haji Mustapha ialah PANAS. Tunku ialah UMNO.', 'Betul! Semua tokoh dan parti dipadankan dengan tepat. Selepas mesyuarat, Wong Pow Nee menghampiri dengan sebuah fail kosong, "Suruhanjaya akan turun ke Borneo. Saya perlukan satu perkara daripada kamu, Donald, pendirian penduduk, bukan pendirian pemimpin." Item baharu, Mohor JSKM.'),
(NULL, 'e1_n2_s8', 'hint', 'Pilih surat yang ditulis penduduk, bukan laporan atau perjanjian.', NULL, NULL),
(25, NULL, 'hint', 'Wong Pow Nee mencari surat yang mencatat PENDIRIAN PENDUDUK. Surat itu dikumpulkan semasa Cobbold bertanya. Singkirkan dokumen yang ditulis selepas suruhanjaya selesai.', 'Pada 17 Januari 1962, Suruhanjaya Cobbold dibentuk untuk mendapatkan reaksi penduduk Sarawak dan Sabah. Wong Pow Nee dan Ghazali Shafie ialah ahli suruhanjaya. Memorandum penduduk ialah sumber utama pendirian rakyat.', 'Betul! Memorandum penduduk dipilih dan dicatat dalam rekod. Berbulan-bulan berlalu. Datu Mustapha tiba membawa sehelai laporan baru siap, "Donald, laporan Cobbold sudah ada. Tetapi ada satu pihak yang tidak puas hati." Item baharu. Memorandum Penduduk.'),
(NULL, 'e1_n2_s9', 'hint', 'Lima peristiwa dari Adelphi hingga laporan Cobbold. Mulakan dengan Mei 1961.', NULL, NULL),
(26, NULL, 'hint', 'Perhatikan bulan, iaitu dua kad bertarikh Julai 1961 (lawatan dan jawatankuasa). Pengumuman di Singapura yang pertama, laporan 21 Jun 1962 yang terakhir.', 'Urutannya ialah Adelphi (27 Mei 1961), lawatan Sarawak (Julai 1961), JSKM (23 Julai 1961). Suruhanjaya Cobbold dibentuk 17 Januari 1962 dan melapor 21 Jun 1962. Laporannya menyatakan dua pertiga menyokong, satu pertiga ragu atau menolak.', 'Tepat! Langkah dari Adelphi hingga laporan tersusun. Razak masuk membawa sekeping nota, "Kita perlukan perlindungan bertulis. Satu jawatankuasa baharu bermesyuarat sebentar lagi. Jangan lambat." Item baharu. Halaman Laporan Cobbold.'),
(NULL, 'e1_n2_s10', 'hint', 'Nama badan itu menyebut jawatankuasa antara kerajaan.', NULL, NULL),
(27, NULL, 'hint', 'Lihat siapa yang duduk bersama. British, Persekutuan, Sarawak dan Sabah, dengan tugas menyediakan perlembagaan. Badan yang bertanya kepada rakyat atau mengundi bukan jawapan.', 'Pada 30 Ogos 1962, JAK bermesyuarat. Ahlinya terdiri daripada wakil British, Persekutuan Tanah Melayu, Sarawak dan Sabah. JAK menyediakan rangka perlembagaan yang melindungi kepentingan Sarawak dan Sabah.', 'Betul! Nama JAK dikenal pasti. Lee Kuan Yew menunggu di pintu, "Rakyat Singapura akan mengundi esok. Aku perlukan satu dokumen yang betul untuk disimpan." Item baharu. Draf Perlembagaan JAK.'),
(NULL, 'e1_n2_s11', 'hint', 'Pilih dokumen tentang keputusan rakyat Singapura.', NULL, NULL),
(28, NULL, 'hint', 'Pilih dokumen yang menyebut Singapura dan undi (referendum). Singkirkan dokumen yang menyebut Sarawak, Sabah atau London.', 'Pada 1 September 1962, rakyat Singapura bersetuju dengan pembentukan Malaysia melalui referendum. Referendum ialah undi rakyat Singapura sendiri. Persetujuan Sarawak dan Sabah akan disahkan kemudian.', 'Betul! Dokumen keputusan referendum dipilih dan disimpan. Datu Mustapha datang dengan muka kalut, "Donald, kau mesti bertolak ke London. Perjanjian akhir akan ditandatangani, tetapi tiga telegram yang tiba bercanggah." Item baharu, Dokumen Referendum.'),
(NULL, 'e1_n2_s12', 'hint', 'Pilih telegram yang menyebut London dan 9 Julai 1963.', NULL, NULL),
(29, NULL, 'hint', 'Cari telegram yang menyebut London, Marlborough House dan 9 Julai 1963. Telegram yang menyebut Adelphi, Cobbold atau Kuala Lumpur ialah peristiwa lain.', 'Pada 9 Julai 1963, Perjanjian Malaysia ditandatangani di Marlborough House, London. Perjanjian itu bukan Pemasyhuran. Pemasyhuran diadakan kemudian, pada 16 September 1963.', 'Tepat! Telegram yang betul diumumkan kepada orang ramai. Seorang pegawai UNMM tiba di pintu, "Kami akan meninjau pandangan penduduk Borneo. Bolehkah Encik Stephens menunjukkan di mana bilik kami?" Item baharu. Telegram London.'),
(NULL, 'e1_n2_s13', 'hint', 'Cari pegawai PBB, sepanduk misi dan peti undi.', NULL, NULL),
(30, NULL, 'hint', 'Tiga bukti, iaitu sepanduk UNMM di bahagian paling atas dinding, pegawai berbaret biru di tengah-kiri bawah, dan peti undi bertanda UNMM di bahagian bawah kiri.', 'Pada 12 Ogos 1963, UNMM mengesahkan persetujuan penduduk Sarawak dan Sabah. UNMM ialah misi Pertubuhan Bangsa-Bangsa Bersatu. Cobbold mendapatkan reaksi, UNMM mengesahkan persetujuan.', 'Hebat! Tanda-tanda bilik UNMM ditemui. Jugah dan Datu Mustapha menunggu di luar, "Persetujuan sudah disahkan. Esok kami semua bersedia untuk satu hari yang akan diingati." Item baharu. Laporan UNMM.'),
(NULL, 'e1_n2_s14', 'hint', 'Empat tempat, empat wilayah. Padankan satu demi satu.', NULL, NULL),
(31, NULL, 'hint', 'Mulakan dengan Kuala Lumpur dan City Hall (di Singapura). Dua bandar Borneo, iaitu Kota Kinabalu terletak di utara Borneo, bekas Borneo Utara.', 'Pada 16 September 1963, Pemasyhuran Malaysia diadakan di empat tempat. Kuala Lumpur (Persekutuan Tanah Melayu), Kuching (Sarawak), Kota Kinabalu (Sabah), City Hall (Singapura). Pemasyhuran berbeza daripada Perjanjian 9 Julai 1963.', 'Betul! Empat tempat dipadankan dengan empat wilayah. Malam itu Pemudi UNKO membawa sepucuk surat dari seberang laut, "Encik Stephens, surat ini daripada Manila. Saya rasa Encik perlu membacanya sendiri." Item baharu. Surat Seberang Laut.'),
(NULL, 'e1_n2_s15', 'hint', 'Surat menyebut wilayah tempat Donald dan Mustapha berkhidmat.', NULL, NULL),
(32, NULL, 'hint', 'Surat menyebut Donald Stephens dan Mustapha Harun. Kedua-dua tokoh ini pemimpin negeri di Borneo yang dahulunya bernama Borneo Utara, bukan Sarawak.', 'Filipina mendakwa Sabah sebagai sebahagian daripada wilayahnya. Brunei menolak penyertaan dalam Malaysia. Malaysia menghadapi cabaran dari dalam dan luar selepas Pemasyhuran.', 'Tepat! Wilayah yang didakwa ialah Sabah. Datu Mustapha menghulurkan kertas kosong dan sebatang pena, "Donald, tulis ucapan yang akan meneguhkan hati rakyat Borneo. Mulakan dengan lapan langkah yang kita lalui." Item baharu. Surat dari Manila.'),
(NULL, 'e1_n2_s16', 'hint', 'Lapan langkah dari Mei 1961 hingga September 1963.', NULL, NULL),
(33, NULL, 'hint', 'Tiga langkah pada 1961, dua pada 1962 dan tiga pada 1963. Kumpulkan mengikut tahun dahulu, kemudian susun mengikut bulan.', 'Lapan langkah itu ialah Adelphi, JSKM, Cobbold dibentuk, laporan Cobbold, JAK, Perjanjian Malaysia, UNMM, Pemasyhuran. Tarikhnya ialah 27 Mei 1961 hingga 16 September 1963. Borneo berunding dan didengar sepanjang perjalanan.', 'Hebat! Lapan langkah tersusun dalam ucapan Donald. Datu Mustapha menutup fail Brassey dan tersenyum, "Dahulu orang kampung takut. Sekarang mereka tahu sejarahnya. Itulah kemenangan sebenar." Item baharu. Teks Ucapan Donald.'),
(NULL, 'e1_n3_s1', 'hint', 'Fail 1938 menyebut satu konsep penyatuan yang lebih luas daripada Malaysia.', NULL, NULL),
(34, NULL, 'hint', 'Fail itu menyebut Filipina dan Indonesia. Persekutuan Tanah Melayu dan Negeri-negeri Selat tidak merangkumi dua negara itu. Pilih konsep 1938 yang menyatukan Melayu serumpun.', 'Pada 1938, Ibrahim Yaakob dan Harun Aminurrashid memperjuangkan Melayu Raya. Melayu Raya ialah penyatuan Tanah Melayu, Singapura, Kalimantan, Filipina dan Indonesia. Melayu Raya bukan Malaysia, konsepnya lebih luas.', 'Tepat! Melayu Raya dikenal pasti. Razak menyerahkan tiga lagi fail bercampur, "Susun semuanya sebelum subuh, Ghazali. Aku perlu tahu siapa mencadangkan apa, dan bila." Item baharu, Tiga Fail Bercampur.'),
(NULL, 'e1_n3_s2', 'hint', 'Empat tahun. Mulakan dengan 1887, kemudian ikut urutan.', NULL, NULL),
(35, NULL, 'hint', 'Idea pertama datang daripada pengarah syarikat British pada abad ke-19. Idea terakhir datang daripada pemimpin Persekutuan sendiri pada 1955.', 'Urutannya ialah 1887 Brassey, 1938 Melayu Raya, 1951 MacDonald, 1955 Tunku. Idea bermula daripada British, kemudian tokoh tempatan, lalu pemimpin Persekutuan. Pada 1955 Tunku mencadangkan empat wilayah menyertai Persekutuan Tanah Melayu.', 'Hebat! Empat idea tersusun tepat. Razak mengeluarkan sebatang kunci kecil, "Pergi ke bilik strategi di bawah tanah. Ada laporan yang aku mahu kau teliti sebelum Tunku bertemu Lee." Item baharu. Kunci Bilik Strategi.'),
(NULL, 'e1_n3_s3', 'hint', 'Dua peta, kertas laporan dan papan strategi.', NULL, NULL),
(36, NULL, 'hint', 'Empat bukti, iaitu dua peta pada papan besar di dinding (kiri dan kanan), tajuk papan itu di bahagian paling atas tengah, dan timbunan buku hijau di atas meja sebelah kiri.', 'Punca pertama ialah menjamin keselamatan negara. Ancaman komunis wujud di Singapura dan Borneo. Pengalaman Persekutuan membantu membendung ancaman itu.', 'Berjaya! Keempat-empat bukti ditemui. Razak menutup fail, "Lee puas hati. Tetapi dia membawa kebimbangan lain, iaitu keseimbangan kaum. Kau perlu bertemu Wong dan Sambanthan esok." Item baharu. Laporan Keselamatan.'),
(NULL, 'e1_n3_s4', 'hint', 'Empat perkataan di papan hitam, empat penjelasan di meja.', NULL, NULL),
(37, NULL, 'hint', 'Padankan mengikut makna, bukan perkataan yang sama sahaja. ''Membendung'' bermaksud menahan sesuatu yang mengancam. ''Taraf hidup'' berkait dengan ekonomi.', 'Empat sebab itu ialah keselamatan, keseimbangan kaum, kemerdekaan dan sosioekonomi. Keseimbangan kaum ialah bilangan penduduk antara kaum menjadi seimbang. Kemerdekaan dipercepat dan ekonomi serta taraf hidup dibangunkan.', 'Bagus! Empat sebab sudah berpadanan. Wong menyerahkan sehelai kertas, "Tunku akan membuat pengumuman di Singapura. Teks ucapannya hilang di antara timbunan. Cari ia, Ghazali." Item baharu, Papan Empat Sebab.'),
(NULL, 'e1_n3_s5', 'hint', 'Teks ucapan ialah teks cadangan bertarikh 27 Mei 1961.', NULL, NULL),
(38, NULL, 'hint', 'Teks untuk Hotel Adelphi ialah pengumuman cadangan, bertarikh 27 Mei 1961. Singkirkan dokumen yang menyebut perjanjian, laporan atau pemasyhuran yang datang kemudian.', 'Pada 27 Mei 1961, Tunku mengumumkan cadangan pembentukan Malaysia di Hotel Adelphi. Teks ucapan ialah teks cadangan, bukan perjanjian atau laporan. Perjanjian dan laporan belum wujud pada tarikh itu.', 'Tepat! Teks ucapan Adelphi ditemui. Tunku menyerahkan sekeping nota, "Selepas Adelphi, aku akan ke Kuching. Aku perlukan nota ringkas tentang tujuan lawatan itu. Siapkan ia." Item baharu. Teks Ucapan Adelphi.'),
(NULL, 'e1_n3_s6', 'hint', 'Nota menyebut Tunku menerangkan, bukan menandatangani.', NULL, NULL),
(39, NULL, 'hint', 'Nota menyebut Tunku bertemu pemimpin dan ''menjelaskan satu idea''. Menjelaskan bermaksud memberi penerangan, bukan menandatangani, menyerahkan laporan atau memasyhurkan.', 'Pada Julai 1961, Tunku melawat Sarawak. Tujuannya ialah menerangkan idea pembentukan Malaysia kepada pemimpin Sarawak. Perjanjian ditandatangani lebih kemudian, pada 9 Julai 1963.', 'Betul! Tujuan lawatan ialah menerangkan idea Malaysia. Razak menyerahkan senarai nama, "Pemimpin Borneo mahu satu jawatankuasa. Kita akan menubuhkannya. Ghazali, kau uruskan bilik dan dokumennya." Item baharu, Senarai Ahli Jawatankuasa.'),
(NULL, 'e1_n3_s7', 'hint', 'Delegasi Sabah dan Sarawak, dokumen mesyuarat dan peta wilayah.', NULL, NULL),
(40, NULL, 'hint', 'Empat bukti, iaitu pemimpin Sabah duduk di kanan meja, pemimpin Sarawak duduk di kiri bawah, dokumen mesyuarat di tengah meja dan peta wilayah tergantung di dinding atas tengah.', 'Pada 23 Julai 1961, JSKM ditubuhkan. Tujuannya meyakinkan pemimpin Sarawak dan Sabah. JSKM mempunyai delegasi Sabah dan Sarawak serta pegawai Persekutuan.', 'Hebat! Keempat-empat bukti JSKM ditemui. Razak menghulurkan sepucuk surat, "British mahu suruhanjaya turun ke Borneo untuk bertanya rakyat. Kertas arahannya baru tiba. Baca dan faham tugasnya." Item baharu. Mohor JSKM.'),
(NULL, 'e1_n3_s8', 'hint', 'Kertas arahan menyebut menemu ramah penduduk dan memorandum.', NULL, NULL),
(41, NULL, 'hint', 'Kertas arahan menyebut ''menemu ramah penduduk'' dan ''meneliti memorandum''. Cari tugas yang berkait dengan mendengar pendapat penduduk, bukan menulis perlembagaan.', 'Pada 17 Januari 1962, Suruhanjaya Cobbold dibentuk. Tugasnya mendapatkan reaksi penduduk Sarawak dan Sabah. Ia menemu ramah penduduk dan meneliti memorandum mereka.', 'Tepat! Tugas Cobbold dikenal pasti. Berbulan-bulan berlalu dan Sambanthan menunggu di pintu dengan wajah risau, "Laporan Cobbold sudah siap. Tetapi dua laporan bercanggah ada di atas meja. Mana yang betul?" Item baharu. Kertas Arahan Cobbold.'),
(NULL, 'e1_n3_s9', 'hint', 'Pilih laporan yang menyebut dua pertiga menyokong.', NULL, NULL),
(42, NULL, 'hint', 'Laporan Cobbold menyatakan dua pertiga menyokong, bukan semua. Singkirkan laporan yang menyatakan ''semua'' dan dokumen perjanjian yang bukan laporan.', 'Pada 21 Jun 1962, Laporan Cobbold diserahkan. Dua pertiga penduduk menyokong pembentukan Malaysia. SUPP menolak kerana mahu persekutuan sendiri.', 'Betul! Laporan yang tepat dipilih. Razak menepuk bahu Ghazali, "Perlindungan bertulis diperlukan. JAK akan bersidang tidak lama lagi. Bersiap sedia." Item baharu. Laporan Cobbold.'),
(NULL, 'e1_n3_s10', 'hint', 'Dua tempat duduk wakil dan rangka perlembagaan di meja.', NULL, NULL),
(43, NULL, 'hint', 'Tiga bukti di dewan mesyuarat, iaitu kerusi wakil British di sebelah kiri meja, kerusi wakil Persekutuan di hujung meja bahagian tengah belakang, dan timbunan dokumen perlembagaan di atas meja.', 'Pada 30 Ogos 1962, JAK bermesyuarat. Ahlinya terdiri daripada wakil British, Persekutuan Tanah Melayu, Sarawak dan Sabah. Tujuannya ialah menyediakan rangka perlembagaan yang melindungi Sarawak dan Sabah.', 'Berjaya! Bukti JAK ditemui. Seorang kerani menghulurkan sehelai nota, "Rakyat Singapura akan mengundi pada hari pertama September. Nota ringkas telah tiba." Item baharu. Rangka Perlembagaan JAK.'),
(NULL, 'e1_n3_s11', 'hint', 'Rakyat Singapura mengundi untuk menyatakan pendirian mereka.', NULL, NULL),
(44, NULL, 'hint', 'Nota menyebut rakyat Singapura ''mengundi''. Peristiwa mengundi untuk menyatakan pendirian ialah satu jenis undian, bukan pemasyhuran atau perjanjian.', 'Pada 1 September 1962, rakyat Singapura bersetuju dengan pembentukan Malaysia melalui referendum. Referendum ialah undi terus rakyat Singapura. Ia berbeza daripada Pemasyhuran dan Perjanjian.', 'Betul! Referendum dikenal pasti. Razak menghulurkan sehelai tiket, "Kita ke London. Perjanjian akan ditandatangani di sana. Pastikan fail yang dibawa betul." Item baharu. Tiket ke London.'),
(NULL, 'e1_n3_s12', 'hint', 'Fail perjanjian menyebut Marlborough House dan 9 Julai 1963.', NULL, NULL),
(45, NULL, 'hint', 'Fail perjanjian menyebut Marlborough House dan 9 Julai 1963. Singkirkan fail yang bertarikh 27 Mei 1961, Ogos 1963 atau 16 September 1963.', 'Pada 9 Julai 1963, Perjanjian Malaysia ditandatangani di Marlborough House, London. Perjanjian itu menetapkan pembentukan Malaysia. Persetujuan penduduk Borneo kemudian disahkan oleh UNMM.', 'Tepat! Fail perjanjian yang betul dipilih. Seorang pegawai PBB menyerahkan kad nama, "Kami akan bertemu penduduk Borneo. Bolehkah Encik Ghazali menerangkan siapa melakukan apa dalam proses ini?" Item baharu. Fail Perjanjian.'),
(NULL, 'e1_n3_s13', 'hint', 'Satu badan meyakinkan, satu bertanya, satu merangka, satu mengesahkan.', NULL, NULL),
(46, NULL, 'hint', 'Empat badan, empat tugas. Satu meyakinkan pemimpin, satu bertanya kepada rakyat, satu menulis rangka perlembagaan dan satu mengesahkan persetujuan. Cari kata kerja pada setiap kad.', 'JSKM meyakinkan pemimpin Sarawak dan Sabah. Suruhanjaya Cobbold mendapatkan reaksi penduduk, JAK menyediakan rangka perlembagaan. UNMM mengesahkan persetujuan penduduk.', 'Hebat! Empat badan dan empat tugas berpadanan. Ahli UNMM menyerahkan sampul biru, "Dokumen Pemasyhuran akan diadakan di empat tempat. Cari tempat-tempat itu pada peta." Item baharu. Sampul UNMM.'),
(NULL, 'e1_n3_s14', 'hint', 'Empat tempat, iaitu Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall.', NULL, NULL),
(47, NULL, 'hint', 'Empat tempat pemasyhuran ditandakan pada peta besar. Kuala Lumpur di sebelah kiri, Kuching dan Kota Kinabalu di sebelah kanan (Kota Kinabalu lebih ke atas), dan Singapura di bawah tengah.', 'Pada 16 September 1963, Pemasyhuran Malaysia diadakan di empat tempat. Tempatnya ialah Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall, Singapura. Empat tempat mewakili empat wilayah yang bergabung.', 'Betul! Keempat-empat tempat ditemui. Razak menghulurkan sehelai telegram, "Kita ada masalah. Beberapa pihak tidak senang. Kau perlu menyusun laporan cabaran sebelum esok." Item baharu. Peta Pemasyhuran.'),
(NULL, 'e1_n3_s15', 'hint', 'Empat pihak, empat cabaran. Padankan satu demi satu.', NULL, NULL),
(48, NULL, 'hint', 'Padankan pihak dengan tindakannya. Satu parti mahu persekutuan sendiri, satu negara melancarkan konfrontasi, satu menuntut Sabah dan satu menolak menyertai.', 'Cabarannya ialah SUPP mahu persekutuan sendiri, Indonesia melancarkan konfrontasi (1963 hingga 1966). Filipina menuntut Sabah. Brunei menolak penyertaan dalam Malaysia.', 'Tepat! Setiap pihak dipadankan dengan cabarannya. Razak menutup fail dan merenung Ghazali, "Esok Tunku mahu ucapan penutup. Kau perlu menyusun lapan langkah dari Adelphi hingga Pemasyhuran." Item baharu. Laporan Cabaran.'),
(NULL, 'e1_n3_s16', 'hint', 'Lapan langkah dari 27 Mei 1961 hingga 16 September 1963.', NULL, NULL),
(49, NULL, 'hint', 'Mulakan dengan Adelphi dan tamatkan dengan Pemasyhuran. Kumpulkan mengikut tahun, iaitu dua langkah 1961, tiga 1962 dan tiga 1963, kemudian susun mengikut bulan.', 'Lapan langkah itu ialah 27 Mei 1961 (Adelphi), 23 Julai 1961 (JSKM), 17 Januari 1962 (Cobbold), 21 Jun 1962 (laporan). 30 Ogos 1962 (JAK), 9 Julai 1963 (Perjanjian Malaysia), 12 Ogos 1963 (UNMM). Pada 16 September 1963, Pemasyhuran Malaysia.', 'Hebat! Lapan langkah tersusun dengan tepat. Razak menutup fail terakhir dan berkata perlahan, "Sejarah tidak hanya dibuat oleh yang berucap di pentas. Terima kasih, Ghazali." Item baharu, Rekod Pembentukan Malaysia.');
INSERT INTO DialogueLine (npcID, narrativeID, sceneID, dialogueLine, sequenceOrder) VALUES
(1, 1, NULL, 'Tugasku sebagai Perdana Menteri Persekutuan Tanah Melayu ialah menjelaskan gagasan Malaysia dan meyakinkan Sarawak, Sabah dan Singapura melalui rundingan, bukan paksaan. Jika aku gagal mendengar, tiada Malaysia, {nama}.', 1),
(1, 1, NULL, 'Aku belajar bahawa perpaduan dibina melalui permuafakatan: mendengar, berunding dan menghormati rakan. Kerana itu kita wajar menghargai jasa dan kebijaksanaan pemimpin.', 2),
(1, 1, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, Perdana Menteri Persekutuan Tanah Melayu. Setiap keputusan yang kau ambil akan menentukan nasib Sarawak, Sabah, Singapura dan Tanah Melayu. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(10, 1, 'e1_n1_s1', 'Tuan, jangan sentuh! Itu fail Pejabat Setiausaha Kolonial. Kalau tersalah susun, akhbar esok menuduh kita mencuri dokumen British.', 1),
(NULL, 1, 'e1_n1_s1', 'Surat itu sudah terkoyak, Ghazali. Lebih baik kita baca siapa yang menulisnya sebelum ia hancur.', 2),
(11, 1, 'e1_n1_s1', 'Tahun 1887. Saya Lord Brassey, Pengarah British North Borneo Company. Saya mencadangkan Sarawak, Sabah, Negeri-negeri Melayu dan Negeri-negeri Selat digabungkan.', 3),
(NULL, 1, 'e1_n1_s1', 'Seorang pengarah syarikat British. Jadi idea ini bermula dari luar Tanah Melayu.', 4),
(13, 1, 'e1_n1_s1', 'Tahun 1938. Saya Ibrahim Haji Yaakob. Bersama Harun Aminurrashid, kami memperjuangkan satu konsep penyatuan, Melayu Raya.', 5),
(14, 1, 'e1_n1_s1', 'Melayu Raya meliputi Tanah Melayu, Singapura, Kalimantan, Kepulauan Filipina dan Kepulauan Indonesia.', 6),
(10, 1, 'e1_n1_s1', 'Sebab itu mohor dan sampulnya mesti dipadankan dahulu, Tuan, sebelum sesiapa melihat kita menyusun semula sejarah.', 7),
(17, 1, 'e1_n1_s1', 'Maaf, Tunku. Benarkah gagasan Malaysia ini idea Tunku seorang sahaja? Saya mahu menulis jawapan Tunku malam ini juga.', 8),
(5, 1, 'e1_n1_s2', 'Parlimen akan bertanya siapa yang mula-mula bercakap tentang penggabungan ini. Kalau Tunku tersilap jawab, kita nampak seperti mencipta sejarah.', 1),
(NULL, 1, 'e1_n1_s2', 'Telegram 1951 ini menyebut seorang pegawai British berunding dengan pemimpin empat wilayah.', 2),
(12, 1, 'e1_n1_s2', 'Saya, Malcolm MacDonald. Pada 1951 saya cuba menghidupkan semula idea lama itu dengan berunding terus dengan pemimpin Tanah Melayu, Sarawak, Sabah dan Singapura.', 3),
(5, 1, 'e1_n1_s2', 'Maka empat draf ini ialah empat peringkat. Tugas kita menyusunnya supaya Parlimen faham bagaimana idea ini bergerak sampai ke tangan Tunku.', 4),
(NULL, 1, 'e1_n1_s2', 'Dan pemimpin Persekutuan yang pertama menyebutnya ialah aku, pada 1955. Susun dahulu, Razak, kemudian kita tentukan apa yang disebut.', 5),
(5, 1, 'e1_n1_s2', 'Satu soalan lagi sebelum pencetak mengamuk, Tunku, dalam ucapan nanti, mahu sebut nama Brassey atau tidak?', 6),
(5, 1, 'e1_n1_s3', 'Tengok pin merah itu, Tunku. Bukan hiasan. Setiap satu menandakan tempat ancaman pernah dilaporkan.', 1),
(NULL, 1, 'e1_n1_s3', 'Singapura di kiri, Sarawak di kanan. Kenapa pin di sana lebih banyak daripada di Tanah Melayu?', 2),
(10, 1, 'e1_n1_s3', 'Kerana di sana belum ada pengalaman menghadapi komunis seperti kita di Persekutuan, Tuan. Kita sudah belajar bertahun-tahun.', 3),
(4, 1, 'e1_n1_s3', 'Itu sebabnya saya datang, Tunku. Jika Singapura berdiri sendiri, saya tidak yakin kami mampu mengawalnya.', 4),
(NULL, 1, 'e1_n1_s3', 'Kalau begitu pengalaman kami boleh digunakan di sana juga. Cari empat petunjuk di bilik ini, Ghazali, yang boleh aku bawa ke Parlimen.', 5),
(5, 1, 'e1_n1_s3', 'Satu perkara lagi sebelum kita naik. Akhbar mahu masuk ke bilik ini, Tunku. Bagaimana?', 6),
(41, 1, 'e1_n1_s4', 'Saya wakil rakyat India, Tunku. Rakyat saya bertanya sama ada Malaysia akan menjadikan kami minoriti yang semakin kecil.', 1),
(16, 1, 'e1_n1_s4', 'Begitu juga kerisauan rakyat Cina. Kami takut bilangan antara kaum tidak seimbang.', 2),
(NULL, 1, 'e1_n1_s4', 'Jika Sarawak, Sabah dan Singapura masuk, nisbah itu berubah. Itu salah satu sebabnya.', 3),
(5, 1, 'e1_n1_s4', 'Tetapi rakyat biasa mahu tahu apa yang mereka dapat. Jalan, sekolah, klinik, dan bila negeri-negeri itu boleh merdeka sepenuhnya.', 4),
(10, 1, 'e1_n1_s4', 'Jawapannya ada dalam empat kad ini, Tuan. Padankan sebab dengan penjelasannya sebelum mereka bosan menunggu.', 5),
(41, 1, 'e1_n1_s4', 'Satu soalan terakhir, Tunku. Berani tak Tunku berjanji rakyat India tidak akan dipinggirkan?', 6),
(10, 1, 'e1_n1_s5', 'Tuan, keratan akhbar ini hanya separuh. Wartawan pasti bertanya tarikh sebenar pengumuman ini.', 1),
(NULL, 1, 'e1_n1_s5', 'Aku tidak boleh menyebut tarikh yang salah di hadapan orang sebegini ramai.', 2),
(10, 1, 'e1_n1_s5', 'Tarikhnya dikodkan dalam keratan, Tuan. Ayat terakhir berkata pengumuman ini mendahului lawatan ke Sarawak dan penubuhan JSKM.', 3),
(4, 1, 'e1_n1_s5', 'Sebut nama Malaysia dengan jelas, Tunku. Jangan beri ruang kepada salah faham.', 4),
(NULL, 1, 'e1_n1_s5', 'Aku akan menyebutnya. Tetapi dahulu, nyahkod keratan ini supaya tarikhnya betul.', 5),
(17, 1, 'e1_n1_s5', 'Tunku, adakah pengumuman ini sudah muktamad? Sarawak dan Sabah sudah bersetuju?', 6),
(10, 1, 'e1_n1_s6', 'Tuan, di Sarawak tiada satu suara. Tiga lelaki ini mewakili tiga pihak yang berbeza.', 1),
(2, 1, 'e1_n1_s6', 'Aku Temenggung Jugah, pemimpin PESAKA. Tunku datang untuk bercakap atau untuk memberitahu? Kami bukan anak kecil.', 2),
(NULL, 1, 'e1_n1_s6', 'Aku datang untuk belajar siapa kamu sebelum aku meminta kamu percaya kepadaku.', 3),
(6, 1, 'e1_n1_s6', 'Aku Stephen Kalong Ningkan dari SNAP. Pastikan Tunku tahu parti siapa yang mana. Di sini orang tidak percaya pemimpin yang tidak mengenal mereka.', 4),
(15, 1, 'e1_n1_s6', 'Saya Abang Haji Mustapha dari PANAS. Pasangkan pemimpin dengan partinya dahulu, Tunku. Kemudian kami sudi mendengar.', 5),
(2, 1, 'e1_n1_s6', 'Satu perkara lagi, Tunku. Adakah Sarawak sekadar menjadi tambahan kepada Tanah Melayu?', 6),
(3, 1, 'e1_n1_s7', 'Tunku, mereka datang kerana Tunku berjanji akan ada jawatankuasa terbuka. Jangan hampakan.', 1),
(2, 1, 'e1_n1_s7', 'Di rumah panjang kami, keputusan dibuat bersama. Jawatankuasa ini mesti begitu juga.', 2),
(9, 1, 'e1_n1_s7', 'Saya, Mustapha Harun, mewakili Sabah di meja ini. Kami mahu syarat kami didengar sebelum apa-apa dimuktamadkan.', 3),
(10, 1, 'e1_n1_s7', 'Tuan, semua yang membuktikan jawatankuasa ini sah ada di atas dan sekeliling meja. Cari semuanya sebelum mesyuarat bermula.', 4),
(NULL, 1, 'e1_n1_s7', 'Dokumen Donald itu, ia cadangan syarat Sabah? Biar aku lihat sendiri sebelum menjawab sesiapa.', 5),
(3, 1, 'e1_n1_s7', 'Tunku, jawab dengan jujur. Bersediakah Tunku menerima syarat yang kami sendiri tulis?', 6),
(10, 1, 'e1_n1_s8', 'Tuan, kalau ada fail yang tercicir, nama saya yang dipersoalkan di London.', 1),
(16, 1, 'e1_n1_s8', 'Saya wakil Persekutuan. Saya akan pastikan tiada suara yang dibisukan.', 2),
(NULL, 1, 'e1_n1_s8', 'Berapa lama masa yang ada sebelum British menunggu jawapan?', 3),
(5, 1, 'e1_n1_s8', 'Suruhanjaya mula pada Januari. Laporan mesti sampai ke tangan mereka sebelum pertengahan tahun.', 4),
(10, 1, 'e1_n1_s8', 'Tolong pasangkan sampul ini dahulu, Tuan. Setiap orang dan setiap tarikh ada tugasnya dalam laporan.', 5),
(16, 1, 'e1_n1_s8', 'Satu soalan sebelum kita mula, Tunku. Mahu membaca laporan sebelum diserahkan kepada British?', 6),
(7, 1, 'e1_n1_s9', 'Dua pertiga menyokong. Kami satu pertiga yang tidak. Jangan sebut ia sebagai suara semua.', 1),
(NULL, 1, 'e1_n1_s9', 'Aku tidak pernah berkata semua. Apa yang kamu mahu?', 2),
(7, 1, 'e1_n1_s9', 'Kami tidak mahu sekadar menjadi wilayah kecil di bawah Kuala Lumpur. Kami mahu persekutuan sendiri bersama Brunei dan Borneo Utara.', 3),
(10, 1, 'e1_n1_s9', 'Tuan, halaman itu menyebut parti yang menolak, tetapi dikodkan. Teliti dahulu parti yang tidak menolak, supaya kita tidak menuduh sesiapa.', 4),
(NULL, 1, 'e1_n1_s9', 'Nyahkod dengan teliti, jangan terburu-buru menuduh.', 5),
(7, 1, 'e1_n1_s9', 'Tunku, bagaimana Tunku akan melayan suara yang menolak ini?', 6),
(3, 1, 'e1_n1_s10', 'Tunku, kami tidak mahu janji lisan lagi. Kami mahu tulis.', 1),
(15, 1, 'e1_n1_s10', 'Saya mewakili Sarawak. Siapa yang duduk di meja ini dan atas nama siapa?', 2),
(10, 1, 'e1_n1_s10', 'Ada empat pihak di sini, Tuan. Tarikh mesyuarat dan tujuannya mesti ditulis dengan tepat, supaya dokumen ini sah.', 3),
(NULL, 1, 'e1_n1_s10', 'Susun butirannya dahulu. Kalau satu pihak tertinggal, mesyuarat ini boleh dipersoalkan.', 4),
(5, 1, 'e1_n1_s10', 'Pihak British membantu menyusun, tetapi keputusan tetap pada pihak yang terlibat.', 5),
(15, 1, 'e1_n1_s10', 'Tunku, bolehkah Sarawak menyemak draf ini sebelum dimuktamadkan?', 6),
(4, 1, 'e1_n1_s11', 'Tunku, orang bertanya mengapa kami mengundi selepas semua yang sudah diputuskan di Kuala Lumpur.', 1),
(NULL, 1, 'e1_n1_s11', 'Kerana rakyat Singapura berhak menjawab sendiri, Lee.', 2),
(10, 1, 'e1_n1_s11', 'Tuan, wartawan dari London sudah bertanya langkah-langkah 1962. Susun dari yang paling awal, jangan sampai mereka kata kita memutar belit.', 3),
(NULL, 1, 'e1_n1_s11', 'Jawapan hari ini bermula daripada satu suruhanjaya yang bertanya kepada rakyat.', 4),
(4, 1, 'e1_n1_s11', 'Tunku, mahu menunggu bersama kami sehingga undi dikira?', 5),
(2, 1, 'e1_n1_s12', 'Di kampung kami, apabila tanda tangan ditulis, ia dipegang sepanjang hayat. Ini bukan upacara kosong.', 1),
(15, 1, 'e1_n1_s12', 'Saya pun begitu. Jangan tergesa-gesa.', 2),
(NULL, 1, 'e1_n1_s12', 'Sebelum sesiapa menandatangani, aku mahu yakin dokumen yang betul berada di meja yang betul.', 3),
(10, 1, 'e1_n1_s12', 'Empat benda di meja ini membuktikan ia tempat dan hari yang sah, Tuan. Cari semuanya sebelum pegawai British bertanya.', 4),
(5, 1, 'e1_n1_s12', 'Tarikhnya mesti tepat pada dokumen itu, Tunku. Tiada ruang untuk silap.', 5),
(2, 1, 'e1_n1_s12', 'Tunku, adakah tandatangan ini membebaskan Sarawak daripada tanggungjawab lama?', 6),
(3, 1, 'e1_n1_s13', 'Tunku, penduduk bertanya sama ada pegawai ini diupah British untuk memaksa jawapan.', 1),
(4, 1, 'e1_n1_s13', 'Singapura sudah mengundi dalam cara lain. Jangan campur aduk dengan misi ini.', 2),
(NULL, 1, 'e1_n1_s13', 'Catatan misi mesti menyebut dengan jelas siapa yang ditemui.', 3),
(10, 1, 'e1_n1_s13', 'Petikan misi ada di tangan saya, Tuan. Ia menyebut tarikh dan tujuan, tetapi pihak yang ditemui dikodkan. Baca betul-betul.', 4),
(3, 1, 'e1_n1_s13', 'Seorang penghulu bertanya, Tunku, jika mereka menolak, adakah Tunku akan menghormati keputusan itu?', 5),
(5, 1, 'e1_n1_s14', 'Tunku, dua dokumen sudah ada di atas mimbar. Satu sudah ditandatangani di London. Satu lagi untuk hari ini.', 1),
(NULL, 1, 'e1_n1_s14', 'Yang mana satu patut aku baca kepada rakyat?', 2),
(10, 1, 'e1_n1_s14', 'Yang menyebut mulai 16 September, Tuan. Dokumen London tidak berkata begitu.', 3),
(3, 1, 'e1_n1_s14', 'Salah ambil dokumen, ucapan malam ini jadi sia-sia, Tunku.', 4),
(NULL, 1, 'e1_n1_s14', 'Nyahkod petikan itu dahulu sebelum aku melangkah ke mikrofon.', 5),
(5, 1, 'e1_n1_s14', 'Satu soalan sebelum Tunku naik ke pentas, adakah Tunku mahu menyebut cabaran yang menanti selepas ini?', 6),
(10, 1, 'e1_n1_s15', 'Tuan, kad nama sudah dicetak. Sebelum bergabung, Persekutuan Tanah Melayu ada sebelas negeri, termasuk Pahang dan Melaka.', 1),
(NULL, 1, 'e1_n1_s15', 'Dan selepas 16 September 1963, berapa semuanya, Razak?', 2),
(5, 1, 'e1_n1_s15', 'Empat belas negeri, Tunku, apabila Singapura, Sabah dan Sarawak bergabung. Dalam perjanjian 1963, Sabah disebut Borneo Utara.', 3),
(NULL, 1, 'e1_n1_s15', 'Sarawak pula aku sendiri lawat pada Julai 1961. Dan Brunei?', 4),
(5, 1, 'e1_n1_s15', 'Brunei menolak penyertaan, Tunku. Kad mereka tidak akan duduk di meja ini.', 5),
(NULL, 1, 'e1_n1_s15', 'Kalau begitu susun semua kad sebelum tetamu masuk.', 6),
(4, 1, 'e1_n1_s15', 'Tunku, di mana wakil Singapura patut duduk di dewan ini?', 7),
(5, 1, 'e1_n1_s16', 'Telegram sudah sampai, Tunku. SUPP masih menolak kerana mahu persekutuan sendiri.', 1),
(NULL, 1, 'e1_n1_s16', 'Dan negara jiran kita?', 2),
(10, 1, 'e1_n1_s16', 'Indonesia melancarkan konfrontasi terhadap Malaysia dari 1963 hingga 1966, Tuan. Filipina pula mendakwa Sabah sebahagian daripada wilayahnya.', 3),
(5, 1, 'e1_n1_s16', 'Dan Singapura, Tunku, berpisah daripada Malaysia pada 1965.', 4),
(NULL, 1, 'e1_n1_s16', 'Pasangkan semuanya dahulu. Salah tuduh hanya menambah musuh di meja rundingan.', 5),
(5, 1, 'e1_n1_s16', 'Tunku, bagaimana kita mahu menghadapi Indonesia dan Filipina?', 6),
(5, 1, 'e1_n1_s17', 'Arkib hanya menyimpan sejarah yang tersusun, Tunku. Lapan langkah ini mesti rapi.', 1),
(NULL, 1, 'e1_n1_s17', 'Sepanjang perjalanan ini aku bertemu fail, wajah dan tandatangan. Tak sangka semuanya boleh disusun.', 2),
(10, 1, 'e1_n1_s17', 'Ada tiga kad dalam tahun 1961, dua dalam 1962 dan tiga dalam 1963, Tuan. Kumpulkan mengikut tahun dahulu.', 3),
(NULL, 1, 'e1_n1_s17', 'Mulakan dari Adelphi dan berakhir dengan Pemasyhuran.', 4),
(5, 1, 'e1_n1_s17', 'Satu soalan terakhir untuk rekod, Tunku. Nama siapa patut ditulis sebagai pembentuk Malaysia?', 5),
(3, 2, NULL, 'Aku Donald Stephens, pemimpin UNKO di Sabah. Tugasku menyuarakan harapan dan kebimbangan rakyat Sabah, dan meyakinkan mereka dengan bukti, bukan janji kosong, {nama}.', 1),
(3, 2, NULL, 'Aku belajar bahawa permuafakatan lahir apabila suara rakyat didengar dan setiap langkah dijelaskan dengan jujur. Kerana itu pemimpin wajar dihargai.', 2),
(3, 2, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemimpin UNKO di Sabah. Rakyatmu mahu tahu apa untung dan rugi Malaysia. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(9, 2, 'e1_n2_s1', 'Donald, di pekan orang berbisik Tanah Melayu mahu mengambil Borneo. Kalau kau tidak menjawab malam ini, esok mereka sudah percaya.', 1),
(NULL, 2, 'e1_n2_s1', 'Itu cakap kosong, Datu. Tiada siapa pernah menyebutnya kepada kita.', 2),
(9, 2, 'e1_n2_s1', 'Kalau begitu fail berhabuk itu apa? Cop di atasnya syarikat British, bukan Tanah Melayu.', 3),
(11, 2, 'e1_n2_s1', 'Tahun 1887. Saya Lord Brassey, Pengarah British North Borneo Company. Saya mencadangkan Sarawak, Sabah, Negeri-negeri Melayu dan Negeri-negeri Selat digabungkan dalam satu pentadbiran.', 4),
(NULL, 2, 'e1_n2_s1', 'Fail Lord Brassey, tahun 1887. Dia mencadangkan penggabungan Sarawak, Sabah, Negeri-negeri Melayu dan satu lagi kumpulan negeri di Selat Melaka. Aku belum membaca senarai penuhnya.', 5),
(9, 2, 'e1_n2_s1', 'Nyahkod petikannya sekarang. Orang kampung akan tanya wilayah mana lagi yang disebut, dan kau mesti tahu jawapannya.', 6),
(8, 2, 'e1_n2_s1', 'Pak Donald, kalau benar idea ini sudah lama, mengapa kami baru mendengarnya sekarang?', 7),
(9, 2, 'e1_n2_s2', 'Empat tarikh, empat nama. Orang kampung akan keliru, Donald.', 1),
(NULL, 2, 'e1_n2_s2', 'Mereka tidak perlu menghafal. Mereka perlu nampak talinya, iaitu syarikat British dahulu, kemudian tokoh tempatan, kemudian pegawai British, barulah Tunku.', 2),
(12, 2, 'e1_n2_s2', 'Pada 1951 saya, Malcolm MacDonald, berbincang dengan pemimpin empat wilayah tentang penggabungan. Saya cuma menghidupkan semula idea lama.', 3),
(9, 2, 'e1_n2_s2', 'Maka pasangkan setiap tahun dengan orangnya sebelum pemuda-pemuda UNKO tiba.', 4),
(20, 2, 'e1_n2_s2', 'Encik Stephens, kalau kita beritahu kampung bahawa ini idea lama, adakah itu bermakna kita tidak perlu bertanya pendapat mereka lagi?', 5),
(5, 2, 'e1_n2_s3', 'Donald, aku tidak datang membawa tarikh. Aku datang membawa kebimbangan. Ancaman komunis di Singapura dan Sarawak makin serius.', 1),
(NULL, 2, 'e1_n2_s3', 'Sabah tenang. Mengapa kami perlu risau tentang komunis?', 2),
(5, 2, 'e1_n2_s3', 'Kerana Borneo sebuah pulau. Jika Sarawak lemah, Sabah di sebelahnya turut terdedah. Persekutuan sudah lama menghadapi komunis dan ada pengalamannya.', 3),
(NULL, 2, 'e1_n2_s3', 'Aku akan lihat sendiri buktinya. Laporan Singapura, laporan Sarawak, dan nota pengalaman Persekutuan itu.', 4),
(5, 2, 'e1_n2_s3', 'Cari ketiga-tiganya di atas meja. Aku mahu kau yakin dengan bukti, bukan dengan kata-kataku.', 5),
(5, 2, 'e1_n2_s3', 'Satu soalan yang kuharap kau fikirkan, Donald. Jika ancaman di Sarawak merebak, siapa yang akan menjaga Sabah?', 6),
(8, 2, 'e1_n2_s4', 'Datu, Pak Donald, jangan berkisah tentang komunis sahaja. Apa untungnya kepada kami yang berkebun dan menangkap ikan?', 1),
(9, 2, 'e1_n2_s4', 'Keselamatan bukan satu-satunya sebab. Aku ada risalah dengan empat sebab, tetapi sebahagian sudah tercampur dengan risalah salah.', 2),
(NULL, 2, 'e1_n2_s4', 'Pilih risalah yang menyenaraikan keempat-empat sebab dengan betul. Jangan ada yang diselit palsu.', 3),
(9, 2, 'e1_n2_s4', 'Orang kampung tidak suka cakap yang bengkok, Donald. Pilih dengan teliti.', 4),
(8, 2, 'e1_n2_s4', 'Pak Donald, kalau kami menyokong, siapa yang menjamin tanah dan adat kami tidak diambil?', 5),
(9, 2, 'e1_n2_s5', 'Donald! Kita masih menyusun hujah, dan Tunku sudah bercakap. Sabah akan kelihatan terlewat.', 1),
(NULL, 2, 'e1_n2_s5', 'Enam tahun idea itu tidur sejak 1955. Hari ini ia bangun. Tarikh tepat pengumuman itu?', 2),
(9, 2, 'e1_n2_s5', 'Keratan akhbar ini yang menyebut. Ayat terakhir berkata pengumuman ini mendahului JSKM, Cobbold dan Perjanjian Malaysia.', 3),
(NULL, 2, 'e1_n2_s5', 'Maka ia mesti jauh lebih awal daripada semua itu. Nyahkod tarikhnya.', 4),
(17, 2, 'e1_n2_s5', 'Encik Stephens, wartawan dari Jesselton bertanya. Adakah UNKO menyokong atau menolak cadangan Tunku?', 5),
(1, 2, 'e1_n2_s6', 'Saya datang bukan untuk memaksa. Saya datang untuk menerangkan idea penggabungan ini kepada anda.', 1),
(6, 2, 'e1_n2_s6', 'Tunku, ramai bertanya kepentingan kami. Kami bukan hanya wilayah tambahan.', 2),
(15, 2, 'e1_n2_s6', 'Saya Datu Bandar Abang Haji Mustapha. Kami mahu dengar sendiri daripada Tunku, bukan hanya daripada akhbar.', 3),
(2, 2, 'e1_n2_s6', 'Dengar baik-baik. Di tebing ini ada tiga petanda lawatan ini, iaitu pemimpin yang mendengar, penduduk yang bertanya, dan bot dengan bendera yang membawa Tunku.', 4),
(NULL, 2, 'e1_n2_s6', 'Aku mencari ketiga-tiga petanda itu. Itulah yang akan aku ceritakan kepada Sabah.', 5),
(2, 2, 'e1_n2_s6', 'Kamu datang dari Sabah, Donald. Adakah Sabah juga mahu meletakkan syarat sebelum bersetuju?', 6),
(1, 2, 'e1_n2_s7', 'Donald dari UNKO, kau mencadangkan jawatankuasa ini. Aku, wakil UMNO, mahu kita membinanya bersama.', 1),
(NULL, 2, 'e1_n2_s7', 'Tujuannya satu, iaitu meyakinkan pemimpin Sarawak dan Sabah tentang pembentukan Malaysia.', 2),
(2, 2, 'e1_n2_s7', 'Aku Temenggung Jugah dari PESAKA. Kalau begitu pastikan setiap orang di meja ini dikenali dengan parti masing-masing, supaya tiada siapa dituduh bercakap bagi pihak orang lain.', 3),
(9, 2, 'e1_n2_s7', 'Aku, Mustapha Harun, mewakili USNO. Stephen Kalong Ningkan dari SNAP dan Datu Bandar Abang Haji Mustapha dari PANAS pun ada di sini. Pastikan kad kita betul, jangan sampai tertukar.', 4),
(1, 2, 'e1_n2_s7', 'Donald, apa yang paling kau harapkan daripada jawatankuasa ini?', 5),
(10, 2, 'e1_n2_s8', 'Suruhanjaya ini dibentuk untuk mendapatkan reaksi penduduk Sarawak dan Sabah. Setiap surat dan suara dicatat.', 1),
(16, 2, 'e1_n2_s8', 'Saya menemu ramah penduduk dan meneliti memorandum mereka tentang pembentukan Malaysia. Saya mencari satu surat yang mencatat pendirian mereka.', 2),
(NULL, 2, 'e1_n2_s8', 'Surat itu bukan laporan kerana laporan belum ditulis, dan bukan perjanjian kerana perjanjian belum wujud.', 3),
(16, 2, 'e1_n2_s8', 'Betul. Pilih dokumen yang benar-benar datang daripada penduduk.', 4),
(16, 2, 'e1_n2_s8', 'Encik Stephens, apa yang patut saya sampaikan kepada penduduk yang takut bersuara di hadapan pegawai?', 5),
(9, 2, 'e1_n2_s9', 'Laporan siap. Dua pertiga penduduk Sarawak dan Sabah menyokong pembentukan Malaysia.', 1),
(NULL, 2, 'e1_n2_s9', 'Dua pertiga bukan semua. Satu pertiga lagi masih ragu.', 2),
(6, 2, 'e1_n2_s9', 'Aku, Ningkan, tidak mahu hasil ini dikatakan tanda semua sudah bersetuju. Wakil SUPP di luar itu akan bercakap lantang.', 3),
(9, 2, 'e1_n2_s9', 'Sebelum dia masuk, susun dahulu langkah dari Adelphi hingga laporan. Kita mesti tunjuk perjalanan ini teratur.', 4),
(7, 2, 'e1_n2_s9', 'Encik Stephens, jika satu pertiga tidak bersetuju, adakah suara kami tidak berharga?', 5),
(5, 2, 'e1_n2_s10', 'Wakil British, Persekutuan Tanah Melayu, Sarawak dan Sabah duduk di sisi meja yang sama. Tidak ada pihak yang dipinggirkan.', 1),
(NULL, 2, 'e1_n2_s10', 'Janji lisan mudah dilupakan. Kami mahu tulisan.', 2),
(6, 2, 'e1_n2_s10', 'Aku mahu perlindungan untuk Sarawak dinyatakan jelas dalam rangka perlembagaan, bukan diserahkan kepada budi bicara orang lain.', 3),
(5, 2, 'e1_n2_s10', 'Itulah sebab mesyuarat ini diadakan. Nyahkod nama badan yang dibentuk untuk tugas itu.', 4),
(5, 2, 'e1_n2_s10', 'Donald, apa yang paling perlu dilindungi dalam rangka perlembagaan bagi Sabah?', 5),
(4, 2, 'e1_n2_s11', 'Rundingan antara Persekutuan Tanah Melayu dan Singapura sudah selesai. Rakyat sudah mengundi.', 1),
(NULL, 2, 'e1_n2_s11', 'Mengapa pemimpin PAP menyokong?', 2),
(4, 2, 'e1_n2_s11', 'Kerana kami yakin gabungan membawa keselamatan dan kemajuan. Tetapi dokumen keputusan itu hilang di antara timbunan ini.', 3),
(5, 2, 'e1_n2_s11', 'Pilih dokumen yang betul, Donald. Jangan tersalah ambil laporan Cobbold atau perjanjian yang belum wujud.', 4),
(4, 2, 'e1_n2_s11', 'Rakyat Singapura sudah menjawab. Bila pula Sarawak dan Sabah memberi jawapan akhir?', 5),
(9, 2, 'e1_n2_s12', 'Donald, tiga telegram sampai serentak. Satu berkata London, satu berkata Singapura, satu lagi berkata Kuala Lumpur.', 1),
(NULL, 2, 'e1_n2_s12', 'Datu, jangan baca yang salah. Orang akan mengingati tarikh yang kau sebut.', 2),
(8, 2, 'e1_n2_s12', 'Mana satu yang betul, Datu? Kami sudah menunggu sejak pagi.', 3),
(9, 2, 'e1_n2_s12', 'Pilih telegram yang menyebut tempat dan tarikh perjanjian dengan tepat.', 4),
(9, 2, 'e1_n2_s12', 'Donald, orang ramai menunggu. Apa yang kau mahu aku umumkan kepada mereka?', 5),
(9, 2, 'e1_n2_s13', 'Mengapa PBB perlu bertanya lagi? Cobbold sudah bertanya.', 1),
(NULL, 2, 'e1_n2_s13', 'Cobbold mendapat reaksi penduduk dan melapor kepada British dan Persekutuan. UNMM pula datang untuk mengesahkan.', 2),
(19, 2, 'e1_n2_s13', 'Benar, Encik Stephens. Cari tiga tanda bilik ini, iaitu pegawai berbaret biru, sepanduk misi dan peti undi pandangan penduduk.', 3),
(NULL, 2, 'e1_n2_s13', 'Aku akan menunjukkan kepada Datu supaya dia faham kerja PBB dengan mata sendiri.', 4),
(19, 2, 'e1_n2_s13', 'Encik Stephens, mengapa penduduk perlu ditanya sekali lagi oleh PBB selepas Cobbold?', 5),
(2, 2, 'e1_n2_s14', 'Pemasyhuran diadakan serentak di empat tempat. Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall, Singapura.', 1),
(NULL, 2, 'e1_n2_s14', 'Dokumen itu menyebut perjanjian 9 Julai 1963 antara Persekutuan Tanah Melayu, Sarawak, Sabah dan Singapura.', 2),
(9, 2, 'e1_n2_s14', 'Padankan setiap tempat dengan negeri atau wilayah yang bergabung. Murid-murid mahu tahu.', 3),
(18, 2, 'e1_n2_s14', 'Pak Donald, mengapa pemasyhuran diadakan di empat tempat, bukan satu tempat sahaja?', 4),
(9, 2, 'e1_n2_s15', 'Brunei menolak penyertaan dalam Malaysia. Singapura datang, Sabah dan Sarawak datang. Tetapi masih ada yang tidak senang.', 1),
(NULL, 2, 'e1_n2_s15', 'Tetapi itu bukan masalah terbesar.', 2),
(9, 2, 'e1_n2_s15', 'Surat ini daripada Filipina. Ia menuntut wilayah tempat kita berkhidmat. Baca dengan teliti dan nyahkod wilayahnya.', 3),
(20, 2, 'e1_n2_s15', 'Encik Stephens, wilayah yang dimaksudkan itu rumah kami semua.', 4),
(20, 2, 'e1_n2_s15', 'Kalau Filipina mendakwa wilayah itu, adakah kita akan keluar daripada Malaysia?', 5),
(9, 2, 'e1_n2_s16', 'Pemasyhuran sudah lama berlalu. Tetapi kisah tidak habis di situ. Singapura, Brunei, Filipina, semuanya meninggalkan kesan.', 1),
(NULL, 2, 'e1_n2_s16', 'Dan Brunei tidak menyertai. Walau begitu, dahulu aku tidak yakin Malaysia akan lahir.', 2),
(18, 2, 'e1_n2_s16', 'Pak Donald, murid-murid mahu tahu bagaimana Malaysia dibentuk daripada awal hingga akhir.', 3),
(9, 2, 'e1_n2_s16', 'Susun lapan langkah itu dahulu, Donald, supaya ucapanmu kemas dan tidak ada tarikh tertinggal.', 4),
(9, 2, 'e1_n2_s16', 'Donald, bagaimana kau mahu menutup ucapan ini?', 5),
(10, 3, NULL, 'Aku Ghazali Shafie. Aku bukan di pentas, aku di bilik fail. Tugasku memastikan setiap tarikh, dokumen dan nama tepat, {nama}.', 1),
(10, 3, NULL, 'Aku belajar bahawa kejayaan besar bergantung pada kerja teliti di sebalik tabir. Satu tarikh yang salah boleh menggoyahkan sebuah rundingan.', 2),
(10, 3, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pegawai yang menyusun fail di sebalik tabir. Setiap dokumen mesti tepat. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(5, 3, 'e1_n3_s1', 'Ghazali, fail ini baru muncul dari stor. Tiada siapa tahu isinya, tetapi esok Tunku mahu menyebut tahun ini dalam ucapan.', 1),
(NULL, 3, 'e1_n3_s1', 'Tulisan di dalamnya kabur, Tun. Aku nampak dua nama, Ibrahim Yaakob dan Harun Aminurrashid, dan satu konsep yang menyatukan beberapa tanah.', 2),
(13, 3, 'e1_n3_s1', 'Pada 1938 kami memperjuangkan penyatuan Tanah Melayu, Singapura, Kalimantan, Filipina dan Indonesia dalam satu konsep.', 3),
(14, 3, 'e1_n3_s1', 'Kami perlukan nama untuk impian itu, tetapi nama itu bukan Malaysia.', 4),
(NULL, 3, 'e1_n3_s1', 'Nyahkod konsep itu dahulu. Tun mahu aku bercakap dengan tepat, bukan menekan hati.', 5),
(5, 3, 'e1_n3_s1', 'Ghazali, kalau Tunku bertanya mengapa fail ini disimpan di stor selama ini, apa yang patut kita jawab?', 6),
(5, 3, 'e1_n3_s2', 'Empat fail, empat idea. Kalau satu tahun tersalah, ucapan Tunku esok akan dikoreksi oleh wartawan.', 1),
(NULL, 3, 'e1_n3_s2', 'Aku tahu urutannya. Brassey dahulu, kemudian Melayu Raya, kemudian MacDonald, dan barulah Tunku.', 2),
(11, 3, 'e1_n3_s2', 'Pada 1887 saya, Lord Brassey, Pengarah British North Borneo Company, mencadangkan Sarawak, Sabah, Negeri-negeri Melayu dan Negeri-negeri Selat digabungkan.', 3),
(12, 3, 'e1_n3_s2', 'Pada 1951 saya, Malcolm MacDonald, berbincang dengan pemimpin Tanah Melayu, Sarawak, Sabah dan Singapura tentang penggabungan.', 4),
(1, 3, 'e1_n3_s2', 'Dan pada 1955 aku sendiri mencadangkan Sarawak, Sabah, Singapura dan Brunei bersama Persekutuan Tanah Melayu, Ghazali.', 5),
(5, 3, 'e1_n3_s2', 'Itu yang ditulis dalam fail. Tetapi susun bukan hanya ingatan. Susun betul-betul, Ghazali.', 6),
(5, 3, 'e1_n3_s2', 'Satu soalan sebelum kau mula. Bolehkah kita menyebut dalam ucapan bahawa idea ini milik Tunku seorang?', 7),
(5, 3, 'e1_n3_s3', 'Singapura dan Sarawak sama-sama dilanda ancaman komunis. Persekutuan sudah ada pengalaman menghadapinya.', 1),
(NULL, 3, 'e1_n3_s3', 'Jadi kalau Malaysia dibentuk, pengalaman itu boleh dikongsi.', 2),
(5, 3, 'e1_n3_s3', 'Tepat. Tetapi Lee akan bertanya bukti. Cari empat bukti di bilik ini, iaitu dua peta, kertas laporan dan papan strategi.', 3),
(NULL, 3, 'e1_n3_s3', 'Peta Singapura dan peta Borneo di dinding, laporan di atas meja, dan papan strategi di bahagian atas. Aku akan menyemaknya.', 4),
(4, 3, 'e1_n3_s3', 'Ghazali, adakah Persekutuan benar-benar bersungguh-sungguh menolong Singapura, atau hanya mahu menambah kuasa sendiri?', 5),
(16, 3, 'e1_n3_s4', 'Ghazali, empat perkataan ini nampak indah di papan hitam. Tetapi apa maksudnya untuk rakyat biasa?', 1),
(41, 3, 'e1_n3_s4', 'Rakyat India bertanya sama ada bilangan mereka akan menjadi semakin kecil. Jelaskan, jangan berselindung.', 2),
(NULL, 3, 'e1_n3_s4', 'Setiap perkataan ada pasangannya. Aku akan padankan keempat-empatnya supaya jelas, satu demi satu.', 3),
(5, 3, 'e1_n3_s4', 'Padankan dengan teliti, Ghazali. Kalau tersilap, Wong dan Sambanthan pulang tanpa yakin.', 4),
(41, 3, 'e1_n3_s4', 'Ghazali, mengapa Sarawak, Sabah dan Brunei perlu diajak sama, bukan hanya Singapura?', 5),
(1, 3, 'e1_n3_s5', 'Ghazali, teks ucapan itu mesti dijumpai malam ini. Esok seluruh dewan akan menunggu.', 1),
(NULL, 3, 'e1_n3_s5', 'Tuan, ada beberapa teks bercampur dalam timbunan ini. Perjanjian, laporan, dan ucapan. Aku akan memilih satu yang betul.', 2),
(5, 3, 'e1_n3_s5', 'Pilih dengan teliti, Ghazali. Teks yang salah boleh memalukan Tunku di hadapan wartawan dari beberapa negara.', 3),
(1, 3, 'e1_n3_s5', 'Ingat, Ghazali, pengumuman esok ialah cadangan pertama. Perjanjian dan laporan belum wujud lagi.', 4),
(1, 3, 'e1_n3_s5', 'Satu perkara lagi. Kalau wartawan bertanya sama ada Sarawak dan Sabah sudah bersetuju, apa yang patut aku jawab?', 5),
(5, 3, 'e1_n3_s6', 'Nota ini datang dari Kuching, Ghazali. Tunku berada di sana. Baca tujuan lawatan itu.', 1),
(2, 3, 'e1_n3_s6', 'Aku Temenggung Jugah. Tunku datang untuk menerangkan, tetapi kami mahu lihat bukti sebelum percaya.', 2),
(15, 3, 'e1_n3_s6', 'Saya Datu Bandar Abang Haji Mustapha. Kami mahu pemimpin Sarawak didengar sebelum apa-apa diputuskan.', 3),
(NULL, 3, 'e1_n3_s6', 'Nota ini menyebut Tunku bertemu pemimpin Sarawak dan menjelaskan satu idea kepada mereka. Aku perlu menyahkod idea itu.', 4),
(5, 3, 'e1_n3_s6', 'Teliti, Ghazali. Bukan perjanjian, bukan laporan. Pilih dengan tepat apa yang Tunku jelaskan di sana.', 5),
(NULL, 3, 'e1_n3_s6', 'Tunku tidak membawa dokumen untuk ditandatangani. Dia membawa penerangan.', 6),
(5, 3, 'e1_n3_s6', 'Kalau pemimpin Sarawak menolak, apa yang patut Tunku lakukan, Ghazali?', 7),
(3, 3, 'e1_n3_s7', 'Ghazali, delegasi Sabah sudah duduk. Kami mahu pastikan semuanya sah dan jelas.', 1),
(6, 3, 'e1_n3_s7', 'Delegasi Sarawak juga sudah hadir. Tunjukkan kami dokumen mesyuarat dan peta wilayah.', 2),
(9, 3, 'e1_n3_s7', 'Aku Mustapha Harun dari USNO, mewakili Sabah bersama Donald. Kami hadir supaya JSKM bukan satu suara sahaja.', 3),
(2, 3, 'e1_n3_s7', 'Aku Temenggung Jugah dari Sarawak. Kami mahu bukti bahawa suara kami dihormati, bukan janji.', 4),
(NULL, 3, 'e1_n3_s7', 'Bilik ini mesti menunjukkan empat perkara, iaitu delegasi Sabah, delegasi Sarawak, dokumen mesyuarat di tengah meja dan peta wilayah di dinding.', 5),
(5, 3, 'e1_n3_s7', 'Cari semuanya, Ghazali. Aku mahu bukti bahawa JSKM benar-benar mewakili semua pihak.', 6),
(3, 3, 'e1_n3_s7', 'Ghazali, apa tugas jawatankuasa ini sebenarnya? Orang kampung bertanya kepada saya.', 7),
(16, 3, 'e1_n3_s8', 'Kertas arahan ini baru dikeluarkan, Ghazali. Ia menyebut tugas suruhanjaya ini dengan jelas.', 1),
(NULL, 3, 'e1_n3_s8', 'Aku membacanya. Suruhanjaya dibentuk untuk menemu ramah penduduk dan meneliti memorandum mereka di Sarawak dan Sabah.', 2),
(5, 3, 'e1_n3_s8', 'Maka tugasnya bukan menyediakan perlembagaan dan bukan mengesahkan persetujuan. Nyahkod tugas yang betul.', 3),
(NULL, 3, 'e1_n3_s8', 'Aku faham. Tugas itu pula menentukan siapa yang kita jumpa dan apa yang kita tulis dalam laporan.', 4),
(16, 3, 'e1_n3_s8', 'Ghazali, kalau penduduk takut bersuara di hadapan pegawai, apa yang patut kita lakukan?', 5),
(41, 3, 'e1_n3_s9', 'Ghazali, tiga laporan di atas meja ini nampak serupa tetapi isinya bercanggah. Satu berkata semua setuju, satu berkata semua menolak.', 1),
(NULL, 3, 'e1_n3_s9', 'Laporan Cobbold yang sebenar menyebut dua pertiga menyokong. Tidak semua, dan tidak ada yang menolak sepenuhnya.', 2),
(5, 3, 'e1_n3_s9', 'Pilih laporan yang betul, Ghazali. Satu kesilapan akan dibangkitkan oleh akhbar esok pagi.', 3),
(7, 3, 'e1_n3_s9', 'Dua pertiga bukan semua. Kami, SUPP, menolak dan kami mahu suara kami dicatat.', 4),
(7, 3, 'e1_n3_s9', 'Ghazali, adakah laporan itu akan menyebut kami menolak?', 5),
(5, 3, 'e1_n3_s10', 'Setiap pihak duduk di tempat masing-masing. Ghazali, pastikan kerusi dan dokumen betul.', 1),
(NULL, 3, 'e1_n3_s10', 'Tempat duduk wakil British, tempat duduk wakil Persekutuan, dan rangka perlembagaan di atas meja. Itulah tiga bukti yang aku cari.', 2),
(6, 3, 'e1_n3_s10', 'Sarawak mahu rangka ini melindungi kepentingan kami. Tulis jelas, jangan abaikan.', 3),
(3, 3, 'e1_n3_s10', 'Sabah pun begitu. Kami tidak mahu hanya janji lisan.', 4),
(5, 3, 'e1_n3_s10', 'Ghazali, kalau satu pihak menolak membaca rangka itu, apa yang patut kita buat?', 5),
(4, 3, 'e1_n3_s11', 'Ghazali, rakyat Singapura sudah menyatakan pendirian mereka. Nota ini mencatat bagaimana mereka berbuat demikian.', 1),
(NULL, 3, 'e1_n3_s11', 'Nota menyebut mereka mengundi untuk menyatakan pendirian tentang pembentukan Malaysia. Aku perlu menamakan cara itu dengan tepat.', 2),
(5, 3, 'e1_n3_s11', 'Ingat, bukan pemasyhuran dan bukan perjanjian. Nama yang betul sahaja, Ghazali.', 3),
(NULL, 3, 'e1_n3_s11', 'Ia kaedah rakyat sendiri menyatakan pendirian secara terus, lalu angkanya dikira.', 4),
(4, 3, 'e1_n3_s11', 'Ghazali, apa yang dicatat kalau rakyat Singapura menolak?', 5),
(5, 3, 'e1_n3_s12', 'Tiga fail serupa, Ghazali. Hanya satu yang betul untuk Perjanjian Malaysia.', 1),
(NULL, 3, 'e1_n3_s12', 'Satu berlabel Adelphi, satu berlabel UNMM, satu lagi berlabel Marlborough House. Aku perlu memilih yang betul.', 2),
(5, 3, 'e1_n3_s12', 'Fail yang salah akan dihantar ke London, dan Tunku akan memalukan kita di hadapan British.', 3),
(NULL, 3, 'e1_n3_s12', 'Aku sudah pasti. Fail perjanjian mesti menyebut tempat dan tarikh penandatanganan.', 4),
(5, 3, 'e1_n3_s12', 'Satu soalan lagi, Ghazali. Selepas perjanjian ini ditandatangani, siapa lagi yang perlu mengesahkannya?', 5),
(5, 3, 'e1_n3_s13', 'Empat badan, iaitu JSKM, Suruhanjaya Cobbold, JAK dan UNMM. Tiap-tiap satu ada tugas berbeza.', 1),
(NULL, 3, 'e1_n3_s13', 'JSKM meyakinkan pemimpin. Cobbold bertanya kepada penduduk. JAK menyediakan perlembagaan. UNMM mengesahkan persetujuan.', 2),
(5, 3, 'e1_n3_s13', 'Kau sudah tahu, tetapi padankan dengan betul. Ahli UNMM akan menyemaknya.', 3),
(19, 3, 'e1_n3_s13', 'Encik Ghazali, saya dari UNMM. Mengapa tugas kami berbeza daripada Cobbold?', 4),
(5, 3, 'e1_n3_s14', 'Pemasyhuran diadakan serentak di empat tempat. Ghazali, tunjukkan empat tempat itu pada peta.', 1),
(NULL, 3, 'e1_n3_s14', 'Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall di Singapura. Aku akan menandakan keempat-empatnya pada peta.', 2),
(1, 3, 'e1_n3_s14', 'Ghazali, setiap tempat mesti betul. Bukan mudah menyatukan empat wilayah dalam satu hari.', 3),
(18, 3, 'e1_n3_s14', 'Encik Ghazali, kenapa Pemasyhuran perlu diadakan di empat tempat?', 4),
(5, 3, 'e1_n3_s15', 'Ghazali, Malaysia baru dilahirkan, tetapi sudah ada yang mahu merobohkannya. Padankan siapa dengan cabaran apa.', 1),
(NULL, 3, 'e1_n3_s15', 'SUPP mahu persekutuan sendiri. Indonesia melancarkan konfrontasi dari 1963 hingga 1966. Filipina menuntut Sabah. Brunei menolak penyertaan.', 2),
(5, 3, 'e1_n3_s15', 'Betul, tetapi pasangkan dengan tepat. Kalau tersilap, kita menuduh pihak yang salah.', 3),
(1, 3, 'e1_n3_s15', 'Ghazali, adakah semua cabaran ini bermakna Malaysia gagal?', 4),
(5, 3, 'e1_n3_s16', 'Lapan langkah dari Adelphi hingga Pemasyhuran. Susun, Ghazali, supaya sejarah ini kemas.', 1),
(NULL, 3, 'e1_n3_s16', 'Adelphi, JSKM, Cobbold dibentuk, laporan Cobbold, JAK, Perjanjian Malaysia, UNMM dan Pemasyhuran. Tarikhnya aku sudah hafal.', 2),
(5, 3, 'e1_n3_s16', 'Kau tahu, Ghazali. Selama ini aku tidak pernah berterima kasih kerana kau yang menyimpan semua ini.', 3),
(5, 3, 'e1_n3_s16', 'Ghazali, apa yang paling kau pelajari daripada perjalanan ini?', 4);
INSERT INTO QuestionBank (bankID, eraID) VALUES (1, 1)
INSERT INTO Question (questionID, bankID, questionText, option_a, option_b, option_c, option_d, correctAnswer, hint, explanation) VALUES
(101, 1, 'Siapakah yang mencadangkan penggabungan Sarawak, Sabah, Negeri-negeri Melayu dan Negeri-negeri Selat pada tahun 1887?', 'Lord Brassey', 'Malcolm MacDonald', 'Ibrahim Haji Yaakob', 'Harun Aminurrashid', 'A', 'Beliau Pengarah British North Borneo Company.', 'Lord Brassey, Pengarah Syarikat Borneo Utara British, mencadangkannya pada 1887. Ini cadangan paling awal.'),
(102, 1, 'Konsep Melayu Raya diperjuangkan oleh tokoh tempatan pada tahun berapa?', '1887', '1951', '1955', '1938', 'D', 'Konsep ini merangkumi Tanah Melayu, Singapura, Kalimantan, Filipina dan Indonesia.', 'Ibrahim Haji Yaakob dan Harun Aminurrashid memperjuangkan Melayu Raya pada 1938.'),
(103, 1, 'Siapakah Gabenor Jeneral British di Asia Tenggara yang berbincang tentang penggabungan pada tahun 1951?', 'Lord Brassey', 'Tunku Abdul Rahman', 'Malcolm MacDonald', 'Lord Cobbold', 'C', 'Namanya bermula dengan huruf M.', 'Malcolm MacDonald berbincang dengan pemimpin Persekutuan Tanah Melayu, Sarawak, Sabah dan Singapura pada 1951.'),
(104, 1, 'Siapakah yang memberikan idea penggabungan Sarawak, Sabah, Singapura dan Brunei dengan Persekutuan Tanah Melayu pada tahun 1955?', 'Lord Brassey', 'Tunku Abdul Rahman Putra Al-Haj', 'Malcolm MacDonald', 'Ibrahim Haji Yaakob', 'B', 'Ketika itu beliau Ketua Menteri Persekutuan Tanah Melayu.', 'Tunku Abdul Rahman mencadangkannya pada 1955.'),
(105, 1, 'Manakah susunan idea pembentukan Malaysia yang betul mengikut kronologi?', '1887, 1938, 1951, 1955', '1951, 1887, 1938, 1955', '1938, 1887, 1955, 1951', '1955, 1951, 1938, 1887', 'A', 'Mulakan dengan tarikh paling lama dahulu.', 'Susunannya ialah 1887 Brassey, 1938 Melayu Raya, 1951 MacDonald dan 1955 Tunku.'),
(106, 1, 'Apakah sebab pembentukan Malaysia yang berkait dengan ancaman komunis di Singapura dan Sarawak?', 'Mempercepat kemerdekaan', 'Membangunkan sosioekonomi', 'Mencapai keseimbangan kaum', 'Menjamin keselamatan negara', 'D', 'Komunis mengancam keselamatan.', 'Ancaman komunis dapat dibendung melalui pembentukan Malaysia, iaitu sebab menjamin keselamatan negara.'),
(107, 1, 'Mengapakah penggabungan Persekutuan Tanah Melayu dengan Singapura sahaja tidak digalakkan?', 'Singapura terlalu jauh daripada Tanah Melayu', 'Singapura tidak mempunyai pelabuhan dagang', 'Bilangan penduduk antara kaum tidak seimbang', 'Penduduk Singapura menolak penggabungan', 'C', 'Fikirkan jumlah penduduk pelbagai kaum.', 'Penggabungan dengan Singapura sahaja menyebabkan ketidakseimbangan antara kaum. Sarawak, Sabah dan Brunei membantu mengimbanginya.'),
(108, 1, 'Pembentukan Malaysia dapat meningkatkan taraf hidup rakyat melalui pembangunan infrastruktur. Ini sebab...', 'menjamin keselamatan negara', 'membangunkan sosioekonomi', 'mencapai keseimbangan kaum', 'mempercepat kemerdekaan', 'B', 'Taraf hidup dan ekonomi ialah sosioekonomi.', 'Penggabungan mempercepat pembangunan infrastruktur, sosial dan ekonomi serta meningkatkan taraf hidup rakyat.'),
(109, 1, 'Apakah sebab pembentukan Malaysia yang memerlukan permuafakatan dan sokongan semua pihak?', 'Mempercepat kemerdekaan', 'Menjamin keselamatan negara', 'Mencapai keseimbangan kaum', 'Membangunkan sosioekonomi', 'A', 'Sarawak, Sabah, Singapura dan Brunei mahu merdeka.', 'Pembentukan Malaysia mampu mempercepat kemerdekaan Sarawak, Sabah, Singapura dan Brunei, dan ia memerlukan permuafakatan semua pihak.'),
(110, 1, 'Di manakah Tunku Abdul Rahman mengumumkan cadangan pembentukan Malaysia pada 27 Mei 1961?', 'Kuala Lumpur', 'Kuching', 'Kota Kinabalu', 'Hotel Adelphi, Singapura', 'D', 'Ia sebuah hotel di Singapura.', 'Cadangan diumumkan di Hotel Adelphi, Singapura.'),
(111, 1, 'Apakah tujuan lawatan Tunku Abdul Rahman ke Sarawak pada Julai 1961?', 'Menandatangani perjanjian rasmi', 'Memungut cukai daripada penduduk', 'Menerangkan idea Malaysia kepada pemimpin tempatan', 'Membuka sekolah baharu di kampung', 'C', 'Beliau datang untuk bercakap dan mendengar.', 'Lawatan itu bertujuan menerangkan idea pembentukan Malaysia kepada pemimpin tempatan.'),
(112, 1, 'Apakah tujuan Jawatankuasa Setia Kawan Malaysia (JSKM) ditubuhkan pada 23 Julai 1961?', 'Merangka perlembagaan', 'Meyakinkan pemimpin Sarawak dan Sabah', 'Mengadakan referendum di Singapura', 'Mengesahkan persetujuan rakyat', 'B', 'Jawatankuasa ini untuk memujuk pemimpin Borneo.', 'JSKM ditubuhkan untuk meyakinkan pemimpin Sarawak dan Sabah tentang pembentukan Malaysia.'),
(113, 1, 'Siapakah yang mencadangkan penubuhan JSKM?', 'Donald Stephens', 'Tun Abdul Razak', 'Datu Bandar Abang Haji Mustapha', 'Lee Kuan Yew', 'A', 'Beliau pemimpin UNKO dari Sabah.', 'Donald Stephens (Tun Muhammad Fuad Stephens), pemimpin UNKO, mencadangkan JSKM.'),
(114, 1, 'Apakah tujuan Suruhanjaya Cobbold dibentuk pada 17 Januari 1962?', 'Menyediakan rangka perlembagaan negara', 'Mengesahkan persetujuan melalui PBB', 'Menandatangani perjanjian di London', 'Mendapatkan reaksi penduduk Sarawak dan Sabah', 'D', 'Suruhanjaya ini turun mendengar penduduk.', 'Suruhanjaya Cobbold dibentuk bagi mendapatkan reaksi penduduk Sarawak dan Sabah.'),
(115, 1, 'Apakah dapatan laporan Suruhanjaya Cobbold pada 21 Jun 1962?', 'Semua penduduk Borneo menolak', 'Satu pertiga penduduk menyokong', 'Dua pertiga penduduk menyokong', 'Penduduk tidak memberi pandangan', 'C', 'Pecahan dua daripada tiga.', 'Laporan mendapati dua pertiga penduduk Sarawak dan Sabah menyokong pembentukan Malaysia.'),
(116, 1, 'Siapakah antara ahli Suruhanjaya Cobbold yang mewakili Persekutuan Tanah Melayu?', 'Tun V.T. Sambanthan dan Lee Kuan Yew', 'Ghazali Shafie dan Wong Pow Nee', 'Donald Stephens dan Tun Jugah', 'Tun Abdul Razak dan Datu Mustapha', 'B', 'Seorang daripada MCA.', 'Tun Muhammad Ghazali Shafie dan Tan Sri Wong Pow Nee menganggotai Suruhanjaya Cobbold.'),
(117, 1, 'Apakah tujuan Jawatankuasa Antara Kerajaan (JAK) yang bermesyuarat pada 30 Ogos 1962?', 'Merangka perlembagaan bagi melindungi Sarawak dan Sabah', 'Menandatangani Perjanjian Malaysia di London', 'Memasyhurkan Malaysia di empat bandar', 'Mengesahkan persetujuan rakyat melalui PBB', 'A', 'JAK ialah jawatankuasa antara kerajaan.', 'JAK dianggotai wakil British, Persekutuan Tanah Melayu, Sarawak dan Sabah untuk menyediakan rangka perlembagaan.'),
(118, 1, 'Apakah yang diadakan di Singapura pada 1 September 1962?', 'Pemasyhuran Malaysia', 'Mesyuarat UNMM', 'Pelancaran JSKM', 'Referendum', 'D', 'Pemungutan suara rakyat.', 'Referendum, iaitu pemungutan suara rakyat, diadakan di Singapura dan rakyat bersetuju dengan pembentukan Malaysia.'),
(119, 1, 'Di manakah Perjanjian Malaysia ditandatangani pada 9 Julai 1963?', 'Hotel Adelphi, Singapura', 'Stadium Merdeka, Kuala Lumpur', 'Marlborough House, London', 'City Hall, Singapura', 'C', 'Ia terletak di ibu negara British.', 'Perjanjian Malaysia ditandatangani di Marlborough House, London.'),
(120, 1, 'Apakah tujuan United Nations Malaysia Mission (UNMM) diwujudkan pada 12 Ogos 1963?', 'Menyediakan perlembagaan baharu Malaysia', 'Mengesahkan persetujuan penduduk Sarawak dan Sabah', 'Menyerahkan laporan kepada kerajaan British', 'Menandatangani perjanjian di London', 'B', 'PBB ingin tahu suara rakyat Borneo.', 'PBB mewujudkan UNMM untuk mengesahkan persetujuan penduduk Sarawak dan Sabah.'),
(121, 1, 'Manakah bandar yang menjadi tempat Pemasyhuran Malaysia pada 16 September 1963?', 'Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall Singapura', 'Kuala Lumpur, Ipoh, Johor Bahru dan Pulau Pinang', 'Kuching, Brunei, Sandakan, Miri dan Labuan', 'London, Singapura, Kuching, Manila dan Jakarta', 'A', 'Empat tempat untuk empat wilayah.', 'Pemasyhuran diadakan di Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall, Singapura.'),
(122, 1, 'Siapakah Perdana Menteri Persekutuan Tanah Melayu yang mengetuai perwakilan ke London?', 'Tun Abdul Razak', 'Lee Kuan Yew', 'Tun V.T. Sambanthan', 'Tunku Abdul Rahman Putra Al-Haj', 'D', 'Pemimpin UMNO yang digelar Bapa Kemerdekaan.', 'Tunku Abdul Rahman mengetuai perwakilan Persekutuan Tanah Melayu dalam Perjanjian Malaysia di London.'),
(123, 1, 'Siapakah pemimpin PESAKA yang menganggotai JSKM dan menandatangani Perjanjian Malaysia di London?', 'Tan Sri Stephen Kalong Ningkan', 'Datu Bandar Abang Haji Mustapha', 'Tun Temenggung Jugah anak Barieng', 'Tun Datu Mustapha', 'C', 'Beliau Temenggung masyarakat Iban.', 'Tun Temenggung Jugah anak Barieng ialah pemimpin PESAKA.'),
(124, 1, 'Siapakah pemimpin USNO yang memberikan penjelasan tentang pembentukan Malaysia kepada penduduk Sabah?', 'Donald Stephens', 'Tun Datu Mustapha Datu Harun', 'Lee Kuan Yew', 'Tun Abdul Razak', 'B', 'USNO ialah parti Sabah.', 'Tun Datu Mustapha Datu Harun memimpin USNO dan menjelaskan Malaysia kepada penduduk Sabah.'),
(125, 1, 'Siapakah yang menyokong idea pembentukan Malaysia bagi membendung ideologi komunis di Singapura?', 'Lee Kuan Yew', 'Tun Temenggung Jugah', 'Stephen Kalong Ningkan', 'Tan Sri Wong Pow Nee', 'A', 'Beliau pemimpin PAP.', 'Lee Kuan Yew, pemimpin PAP, menyokong pembentukan Malaysia bagi membendung ideologi komunis.'),
(126, 1, 'Mengapakah SUPP menolak rancangan pembentukan Malaysia?', 'Menyokong penjajahan British ke atas Borneo', 'Mahu bergabung dengan Filipina secara terus', 'Tidak mahu kemerdekaan untuk Sarawak', 'Mahu persekutuan sendiri dengan Brunei, Sarawak dan Borneo Utara', 'D', 'SUPP mahu persekutuan sendiri.', 'SUPP mahu membentuk persekutuan sendiri yang terdiri daripada Brunei, Sarawak dan Borneo Utara.'),
(127, 1, 'Apakah yang dilakukan Indonesia terhadap Malaysia dari tahun 1963 hingga 1966?', 'Menandatangani perjanjian damai', 'Menyertai Malaysia', 'Mengisytiharkan konfrontasi', 'Menghantar bantuan makanan', 'C', 'Indonesia menganggap Malaysia mengancam kedudukannya.', 'Indonesia mengisytiharkan konfrontasi terhadap Malaysia kerana menganggap pembentukannya mengancam kedudukan negaranya.'),
(128, 1, 'Negara manakah yang mendakwa Sabah sebahagian daripada wilayahnya?', 'Indonesia', 'Filipina', 'Brunei', 'Singapura', 'B', 'Ia terletak di utara Sabah.', 'Filipina mendakwa Sabah sebahagian daripada wilayahnya.'),
(129, 1, 'Manakah negeri yang menolak penyertaan dalam Malaysia dan wilayah yang berpisah pada tahun 1965?', 'Brunei menolak dan Singapura berpisah', 'Sarawak menolak dan Sabah berpisah', 'Singapura menolak dan Brunei berpisah', 'Sabah menolak dan Sarawak berpisah', 'A', 'Satu menolak, satu berpisah.', 'Brunei menolak penyertaan, dan Singapura berpisah daripada Malaysia pada 1965.'),
(130, 1, 'Apakah peribahasa yang menggambarkan hubungan Malaysia dengan Indonesia dan Filipina yang kembali pulih?', 'Hendak seribu daya, tak hendak seribu dalih', 'Bagai aur dengan tebing', 'Sedikit-sedikit lama-lama menjadi bukit', 'Carik-carik bulu ayam, bercantum juga', 'D', 'Selepas bercerai, bercantum semula.', 'Hubungan tegang dapat dipulihkan melalui permuafakatan pemimpin.'),
(131, 1, 'Apakah yang disambut pada 16 September setiap tahun?', 'Hari Kebangsaan', 'Hari Pahlawan', 'Hari Malaysia', 'Hari Kemerdekaan', 'C', 'Ia hari Malaysia dibentuk.', 'Hari Malaysia disambut sebagai tanda syukur dan bangga atas permuafakatan dan perpaduan rakyat.'),
(132, 1, 'Manakah kesan pembentukan Malaysia?', 'Menambah ancaman luar negara', 'Mengekalkan keamanan dan mewujudkan permuafakatan', 'Memecahkan perpaduan rakyat berbilang kaum', 'Menghentikan pembangunan negara', 'B', 'Pilih kesan yang baik.', 'Pembentukan Malaysia mengekalkan keamanan, mewujudkan permuafakatan dan menyatupadukan rakyat berbilang kaum.'),
(133, 1, 'Mengapakah kita wajar menghargai jasa dan kebijaksanaan pemimpin yang memperjuangkan pembentukan Malaysia?', 'Supaya perpaduan kaum dapat dikekalkan', 'Supaya mereka mendapat gaji yang tinggi', 'Supaya negara lain menyerang kita', 'Supaya rakyat tidak bersatu padu', 'A', 'Jawapan yang melibatkan perpaduan.', 'Menghargai jasa pemimpin mengekalkan kestabilan perpaduan, kestabilan ekonomi dan politik, serta membentuk masyarakat yang positif.'),
(134, 1, 'Bagaimanakah permuafakatan pemimpin dapat membawa kepada pembentukan Malaysia?', 'Pemimpin Sarawak dan Sabah menolak semua rundingan dengan British', 'Pemimpin British membuat semua keputusan tanpa bertanya penduduk', 'Pemimpin Singapura mengambil alih pentadbiran Tanah Melayu', 'Pemimpin pelbagai kaum bersepakat menyokong penggabungan', 'D', 'Fikirkan JSKM, Cobbold dan JAK: semuanya melibatkan lebih daripada satu pihak.', 'Pembentukan Malaysia berjaya kerana pemimpin pelbagai wilayah dan kaum mencapai kesepakatan, bukan kerana paksaan.'),
(135, 1, 'Mengapakah Tunku mengadakan lawatan ke Sarawak dan menubuhkan JSKM sebelum Perjanjian Malaysia ditandatangani?', 'Supaya perjanjian boleh ditandatangani tanpa sebarang perundingan', 'Supaya British tidak lagi mempunyai sebarang peranan di Borneo', 'Supaya pemimpin Borneo diyakinkan dan didengar dahulu', 'Supaya Singapura dapat dikeluarkan daripada rancangan itu', 'C', 'Tunku tidak mahu memaksa.', 'Lawatan Julai 1961 dan JSKM 23 Julai 1961 bertujuan menerangkan dan meyakinkan pemimpin Sarawak dan Sabah melalui rundingan.'),
(136, 1, 'Seorang murid berkata pembentukan Malaysia hanyalah idea Tunku seorang. Mengapakah kenyataan itu kurang tepat?', 'Tunku tidak pernah mengumumkan cadangan itu di Singapura', 'Idea itu sudah dibincangkan sejak 1887', 'Idea itu datang daripada Indonesia semasa Konfrontasi 1963', 'Idea itu hanya timbul selepas Malaysia dimasyhurkan', 'B', 'Ingat fail lama bertarikh 1887 dan 1938.', 'Lord Brassey (1887), Melayu Raya (1938) dan MacDonald (1951) menunjukkan idea itu sudah lama wujud sebelum cadangan Tunku.'),
(137, 1, 'Apakah kepentingan laporan Suruhanjaya Cobbold sebelum Perjanjian Malaysia ditandatangani?', 'Menunjukkan majoriti penduduk Borneo menyokong Malaysia', 'Menetapkan tarikh dan tempat Pemasyhuran Malaysia', 'Menggantikan peranan JAK dalam merangka perlembagaan', 'Mengisytiharkan Konfrontasi terhadap Malaysia', 'A', 'Laporan 21 Jun 1962 mendengar suara penduduk.', 'Laporan Cobbold mendapati majoriti menyokong, dan dapatan ini menjadi asas rundingan seterusnya.'),
(138, 1, 'Walaupun dua pertiga penduduk menyokong Malaysia, SUPP tetap menolak. Apakah tindakan yang paling wajar oleh pemimpin?', 'Menghalang SUPP daripada menyuarakan bantahannya', 'Membatalkan pembentukan Malaysia', 'Mengabaikan semua bantahan kerana majoriti sudah cukup besar', 'Terus menerangkan dan mendengar bantahan', 'D', 'Tunku memilih rundingan, bukan paksaan.', 'Pemimpin menghormati suara majoriti dan masih mendengar suara minoriti melalui penerangan dan rundingan.'),
(139, 1, 'Manakah susunan langkah yang betul ke arah pembentukan Malaysia?', 'JSKM, Adelphi, JAK, Cobbold, Pemasyhuran, Perjanjian Malaysia', 'Cobbold, Adelphi, JSKM, Perjanjian Malaysia, JAK, Pemasyhuran', 'Adelphi, JSKM, Suruhanjaya Cobbold, JAK, Perjanjian Malaysia, Pemasyhuran', 'Adelphi, Cobbold, JSKM, JAK, Pemasyhuran, Perjanjian Malaysia', 'C', 'Mulakan dengan 27 Mei 1961 dan akhiri dengan 16 September 1963.', 'Susunan: 27 Mei 1961, 23 Julai 1961, 17 Januari 1962, 30 Ogos 1962, 9 Julai 1963 dan 16 September 1963.'),
(140, 1, 'Mengapakah Pertubuhan Bangsa-Bangsa Bersatu (UNMM) meninjau pendapat penduduk Sarawak dan Sabah selepas Suruhanjaya Cobbold?', 'Untuk menggantikan laporan Cobbold dengan laporan baharu', 'Untuk mengesahkan persetujuan penduduk secara bebas', 'Untuk menetapkan sempadan baharu bagi setiap negeri', 'Untuk menolak penyertaan Singapura dalam Malaysia', 'B', 'Misi ini bertarikh 12 Ogos 1963.', 'UNMM bertugas mengesahkan persetujuan penduduk supaya keputusan pembentukan Malaysia diterima sebagai sah.'),
(141, 1, 'Penduduk yang memahami sejarah pembentukan negara lebih menghargai perjuangan pemimpin. Apakah kesan utamanya kepada negara?', 'Perpaduan dan kestabilan lebih mudah dikekalkan', 'Perselisihan antara kaum dan wilayah bertambah', 'Pergantungan kepada kuasa luar semakin meningkat', 'Penyertaan rakyat dalam pembangunan negara berkurang', 'A', 'Menghargai jasa pemimpin mengekalkan apa yang telah dibina.', 'Menghargai jasa pemimpin memupuk perpaduan dan membantu mengekalkan kestabilan serta kemakmuran negara.'),
(142, 1, 'Antara berikut, yang manakah cabaran dalaman ke arah pembentukan Malaysia?', 'Konfrontasi oleh Indonesia', 'Tuntutan Filipina ke atas Sabah', 'Tuntutan British ke atas Singapura', 'Penolakan SUPP yang mahu persekutuan sendiri', 'D', 'Cabaran dalaman datang dari dalam wilayah yang terlibat.', 'SUPP ialah cabaran dalaman; Konfrontasi Indonesia dan tuntutan Filipina ialah cabaran luaran.'),
(143, 1, 'Mengapakah hubungan yang kembali pulih antara pemimpin Malaysia, Indonesia dan Filipina penting?', 'Konfrontasi dapat diteruskan dengan lebih berkesan lagi', 'Tuntutan terhadap Sabah dapat ditambah oleh Filipina', 'Kerjasama ekonomi dan keselamatan dapat diperkukuh', 'Hubungan diplomatik antara ketiga-tiga negara dapat diputuskan', 'C', 'Peribahasa yang digunakan ialah pulih dan renggang.', 'Permuafakatan memulihkan hubungan diplomatik dan membuka jalan kerjasama ekonomi serta keselamatan serantau.');
